// ════════════════════════════════════════════════════════════════

/// ——2026-09-07 先例；功能门禁=常量集中可调）。
pub const TOOLBAR_BAR_HEIGHT: f32 = 40.0;  // 浮层条高度（px）
pub const TOOLBAR_HOVER_ALPHA: u8 = 230;   // 悬停整条提升不透明度（255×~90%）
pub const TOOLBAR_BAR_RADIUS: f32 = 10.0;  // 浮层条圆角（px）
pub const TOOLBAR_COLLAPSED_Y: f32 = 6.0;  // 收起态迷你条距窗顶偏移（px）
pub const TOOLBAR_TOP_BAND: f32 = 8.0;     // 隐藏态：窗顶边缘热区窄带（px）
pub const TOOLBAR_CORNER_HOT: f32 = 24.0;  // 隐藏态：右上角固定入口热区（px 见方）

/// 会话内记忆，新窗构造即默认；不写配置文件——跨会话重置默认=任务书口径）。
/// 显示且仅显示「全屏」+「展开工具栏」两钮；用户切换会话内记忆。
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub(crate) enum ToolbarState {
    /// 展开：半透明悬浮条（完整工具栏；由收起态点「展开工具栏」进入）。
    Expanded,
    /// 「全屏」+「展开工具栏」（点「展开工具栏」回 Expanded；切换会话内
    /// 记忆，新窗重置默认收起）。
    #[default]
    Collapsed,
    /// 隐藏：完全无工具栏（全幅画面）；热区仅临时浮现，状态恒 Hidden。
    Hidden,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ToolbarEvent {
    /// 点击条右端「收缩」控件（→ Collapsed）。
    Collapse,
    /// 点击条右端「隐藏」控件（→ Hidden）。
    Hide,
    /// 点击「恢复常驻」入口（Hidden 临时浮现形态；→ Expanded）。
    Restore,
    /// 革命性承接为迷你条两钮之一的展开钮；→ Expanded）。原 `HandleHover`
    /// 层，不经状态机）。
    HandleClick,
    /// Hidden 态指针贴近窗顶窄带/固定入口（临时浮现；**状态不变**）。
    TopEdgeHover,
    /// Hidden 态指针移出热区（隐藏；**状态不变**）。
    HotzoneLeave,
}

///
/// 转移矩阵（行=当前态，列=事件；`—` = no-op 自环）：
/// ```text
///               Collapse   Hide     Restore  HandleClick  TopEdgeHover  HotzoneLeave
/// Expanded     Collapsed  Hidden     —         —           —             —
/// Collapsed      —       Hidden     —      Expanded       —             —
/// Hidden         —        —      Expanded     —          —(浮现)       —(隐藏)
/// ```
/// 视觉高亮不改态，判定在渲染层）。
/// Hidden 态 `TopEdgeHover`/`HotzoneLeave` 不改状态——临时浮现/移开即隐藏是
/// 渲染层逐帧热区判定（[`toolbar_hidden_emerge`]），状态恒 `Hidden`（保证
/// 「移开即隐藏」不会误切为常驻，也保证不悬停时工具栏零渲染=全幅画面）。
pub(crate) fn toolbar_state_next(cur: ToolbarState, ev: ToolbarEvent) -> ToolbarState {
    match (cur, ev) {
        (ToolbarState::Expanded, ToolbarEvent::Collapse) => ToolbarState::Collapsed,
        (ToolbarState::Expanded, ToolbarEvent::Hide) => ToolbarState::Hidden,
        (ToolbarState::Collapsed, ToolbarEvent::HandleClick) => ToolbarState::Expanded,
        (ToolbarState::Collapsed, ToolbarEvent::Hide) => ToolbarState::Hidden,
        (ToolbarState::Hidden, ToolbarEvent::Restore) => ToolbarState::Expanded,
        _ => cur,
    }
}

/// 迷你条的按钮 tooltip i18n 键（渲染层按同序取用，单一事实源）：
/// ①「全屏」（与展开条全屏钮同语义：真实视口态单一事实源 + F11 同步）；
/// ②「展开工具栏」（→ 状态机 `HandleClick` 沿 → Expanded）。
pub(crate) fn toolbar_collapsed_buttons() -> [&'static str; 2] {
    ["session.toolbar.fullscreen", "session.toolbar.expand"]
}

/// （`TOOLBAR_COLLAPSED_W`×`TOOLBAR_COLLAPSED_H` = 两钮 + 内边距口径，
/// 渲染层 `set_min/max_size` 同值）。`offset_y` = 状态条（conn_state 浮层，
pub(crate) fn toolbar_collapsed_rect(screen_w: f32, offset_y: f32) -> egui::Rect {
    egui::Rect::from_center_size(
        egui::pos2(
            screen_w / 2.0,
            offset_y + TOOLBAR_COLLAPSED_Y + TOOLBAR_COLLAPSED_H / 2.0,
        ),
        egui::vec2(TOOLBAR_COLLAPSED_W, TOOLBAR_COLLAPSED_H),
    )
}

/// - 尚未实测（`measured_w <= 1.0`）→ 全宽（`screen_w`）过渡帧（次帧收敛）；
/// - 实测内容宽 < 屏宽 → 内容宽（`measured_w`）；**窗口最大化时窗宽大、
/// - 实测内容宽 ≥ 屏宽（超窄窗内容溢出）→ 全宽回退（右端按钮恒可达）。
///
/// （`hover_hint::toolbar_content_width` 逐帧实测；旧实测值 = 被右段右→左布局拉伸的
/// Area 全宽 = 恒 ≥ 窗宽 → 回退分支恒触发 = 永久全宽，即用户所见「宽度
/// 最大」）。回退分支表达式本身对真内容宽成立（溢出时右端按钮恒可达），
/// （渲染层 `set_min/max_size` 同值），不再依赖 Area 自定尺寸。
pub(crate) fn toolbar_bar_width(measured_w: f32, screen_w: f32) -> f32 {
    // NaN 全比较为 false 静默落入 else 全宽分支（输出同值，但属未文档化、
    // 未钉死的输入类）；有限输入行为零变化（r120 族单测零回归）。
    if !measured_w.is_finite() || measured_w <= 1.0 {
        screen_w
    } else if measured_w < screen_w {
        measured_w
    } else {
        screen_w
    }
}

/// `None`/非有限/≤1.0 一律归 1.0（未实测哨兵，决策层 [`toolbar_bar_width`]
/// 显式过渡帧分支）；有限 >1.0 原样。行为保持钉死：对全部输入类，
/// 归一化值的决策输出 ≡ 旧 `unwrap_or(1.0)` 直传的决策输出（单测同态钉）。
pub(crate) fn toolbar_measured_store(measured: Option<f32>) -> f32 {
    measured.filter(|w| w.is_finite() && *w > 1.0).unwrap_or(1.0)
}

/// 复测一次性定判 G1/G2 的观测锚（判读法见交付报告）：
///   `none` = 闭包未回写〔静态核查 + headless 探针钉死可见帧不可能〕/
///   `nan` = 非有限实测值）；
/// - `win` = 窗宽（决策输入第二参同口径）。
pub(crate) fn toolbar_width_trace_lines(
    measured: Option<f32>,
    bar_w: f32,
    win_w: f32,
) -> (String, String) {
    let meas = match measured {
        Some(m) if m.is_finite() => format!("{m:.1}"),
        Some(_) => "nan".to_string(),
        None => "none".to_string(),
    };
    (
    )
}

/// 计数驱动：前 3 可见帧必发 + 其后每 60 可见帧发一对（60fps ≈ 1 对/秒，
/// 低频不刷屏）。**不依赖 `latency_trace` 门控**（常开低频）——09-22 复测
/// `latency_trace::enabled()` + 前 3 帧 + ≥1000ms）采样未命中；下轮用户
/// 复测须可判 → 与旧 lane 并联 OR（旧 lane 保留 = `R133_STREAM_TBW` 流位
/// 引用不漂移、`latency_trace`=on 侧零回归、行格式不变）。
/// 返回 (下一计数, 本帧是否发)。
pub(crate) fn r134_tbw_step(visible_frames: u64) -> (u64, bool) {
    let n = visible_frames.saturating_add(1);
    (n, n <= 3 || n % 60 == 0)
}

/// 聚焦 + 有分辨率 + Desktop + 非锁屏 + 本机板文件数 > 0。门控语义零变化，
/// 仅渲染形态由全宽 24px 黑条改顶部中央紧凑胶囊浮层（不占行、不覆盖画面）。
pub(crate) fn clip_badge_visible(
    focused: bool,
    base_w: u32,
    base_h: u32,
    is_desktop: bool,
    locked: bool,
    n_files: Option<usize>,
) -> bool {
    focused
        && base_w > 0
        && base_h > 0
        && is_desktop
        && !locked
        && n_files.is_some_and(|n| n > 0)
}

/// 见方（内含一个低透明可见小标记，保证可找回）。
pub(crate) fn toolbar_corner_hot_rect(screen_w: f32, offset_y: f32) -> egui::Rect {
    egui::Rect::from_min_size(
        egui::pos2(screen_w - TOOLBAR_CORNER_HOT, offset_y),
        egui::vec2(TOOLBAR_CORNER_HOT, TOOLBAR_CORNER_HOT),
    )
}

pub(crate) fn toolbar_rect_hit(pointer: Option<egui::Pos2>, rect: egui::Rect) -> bool {
    pointer.is_some_and(|p| rect.contains(p))
}

/// ① 窗顶边缘窄带（全宽 × `TOOLBAR_TOP_BAND`）② 浮层条体（防抖：指针已在
/// 条上时保持显示，可从窄带移入条内点按钮不闪断）③ 右上角固定入口热区
/// （`TOOLBAR_CORNER_HOT` 见方）→ 条临时浮现；无指针/窗外/条体下方=隐藏。
pub(crate) fn toolbar_hidden_emerge(
    pointer: Option<egui::Pos2>,
    screen_w: f32,
    offset_y: f32,
) -> bool {
    let Some(p) = pointer else {
        return false;
    };
    if p.x < 0.0 || p.x > screen_w || p.y < offset_y {
        return false;
    }
    let dy = p.y - offset_y;
    let in_top_band = dy <= TOOLBAR_TOP_BAND;
    let in_bar = dy <= TOOLBAR_BAR_HEIGHT;
    let in_corner = dy <= TOOLBAR_CORNER_HOT && p.x >= screen_w - TOOLBAR_CORNER_HOT;
    in_top_band || in_bar || in_corner
}

/// （`TOOLBAR_BASE_ALPHA` 静止 / `TOOLBAR_HOVER_ALPHA` 悬停整条）。
pub(crate) fn toolbar_bar_fill(theme: &Theme, alpha: u8) -> egui::Color32 {
    let [r, g, b, _] = theme.bg.to_srgba_unmultiplied();
    egui::Color32::from_rgba_unmultiplied(r, g, b, alpha)
}

/// `max` = 窗右下）内，保证条体（`size`）完整落在可视区。**条体大于可视区**
/// （零尺寸窗/极端小窗/内容宽超窗宽）→ 该轴回落 `bounds.min`（不越界、不
/// panic；内容超宽时 x 钉左缘，右端按钮仍贴右缘可达=渲染层同口径）。每帧对
/// 已存位置重跑（窗体缩放/状态条出现消失把旧位置推出可视区时自动收回）。
pub(crate) fn toolbar_clamp_pos(pos: egui::Pos2, size: egui::Vec2, bounds: egui::Rect) -> egui::Pos2 {
    let max_x = (bounds.max.x - size.x).max(bounds.min.x);
    let max_y = (bounds.max.y - size.y).max(bounds.min.y);
    egui::pos2(pos.x.clamp(bounds.min.x, max_x), pos.y.clamp(bounds.min.y, max_y))
}

/// 整体收敛进窗体可视区 `bounds`：原点走 [`toolbar_clamp_pos`]（默认/拖动
/// 两态单一入口），size 端再收敛 `min + size ≤ bounds.max`（退化窗取交集）。
/// 与仅夹原点的 [`toolbar_clamp_pos`] 的差别 = **右缘/下缘不出窗**——egui
/// Area 的持久尺寸态滞后一帧 + 内容溢出会把 `min_rect` 撑出钉死宽（只被
/// `clip_rect`=屏缘裁切），窗体移动/缩放/最小化还原/多窗创建时序下条体矩形
/// 可能滞留旧窗坐标/旧尺寸（09-22 复测 §6 截图：右缘按钮伸出窗外被裁切）
/// → 本函数每帧按当帧 `ctx.screen_rect()` 重夹取 = 移动/缩放/最小化/多窗
/// **不脱锚、不出窗**。退化 bounds（`max ≤ min`，最小化极端帧）→ 收敛为
/// `bounds.min` 锚定的非负尺寸矩形（不 panic、不 NaN）。
pub(crate) fn toolbar_live_clamp(min: egui::Pos2, size: egui::Vec2, bounds: egui::Rect) -> egui::Rect {
    let clamped_min = toolbar_clamp_pos(min, size, bounds);
    let clamped_max = egui::pos2(
        (clamped_min.x + size.x).min(bounds.max.x).max(bounds.min.x),
        (clamped_min.y + size.y).min(bounds.max.y).max(bounds.min.y),
    );
    egui::Rect::from_min_max(clamped_min, clamped_max)
}

/// - 指针悬停条/把手 → `TOOLBAR_HOVER_ALPHA`（114-A 悬停 230 逻辑不变）；
/// - 无悬停且空闲（无指针交互）≥ `TOOLBAR_IDLE_DIM_SECS` → `TOOLBAR_ALPHA_IDLE`
///   （向日葵式闲置「幽灵条」≈10%）；
/// 「空闲」由 per-窗 `toolbar_last_interaction` 时间戳判定（条/把手悬停或拖动
/// 即重置为 now），本函数只吃已算好的 `idle_secs` = 可单测。不自动收缩/不自动
/// 隐藏（避免意外 UX；候选见遗留）。
pub(crate) fn toolbar_idle_alpha(hovered: bool, idle_secs: f32) -> u8 {
    if hovered {
        TOOLBAR_HOVER_ALPHA
    } else if idle_secs >= TOOLBAR_IDLE_DIM_SECS {
        TOOLBAR_ALPHA_IDLE
    } else {
        TOOLBAR_BASE_ALPHA
    }
}

/// `drag_anchor` = 按下帧的条体左上角，`drag_delta` = 按下帧至今的指针位移
/// （指针差值，非逐帧增量累加——锚点+总位移 = 无「边界粘滞」），结果夹取在
/// `bounds` 内、尺寸恒为 `size`。返回矩形即本帧浮层条几何 = 输入捕获 occlusion
/// 过滤消费的同一矩形（指针在条上=本端 UI 操作，不转发远端）。
pub(crate) fn toolbar_dragged_rect(
    drag_anchor: egui::Pos2,
    drag_delta: egui::Vec2,
    size: egui::Vec2,
    bounds: egui::Rect,
) -> egui::Rect {
    egui::Rect::from_min_size(
        toolbar_clamp_pos(drag_anchor + drag_delta, size, bounds),
        size,
    )
}

///
/// 按钮卡死根因之一：每点击 spawn 独立线程 + Runtime，`Runtime::new().expect`
/// / 任务内 panic → 线程死亡且 `connection_status` 停留在进行态，全代码无
/// 时间驱动复位 → 按钮永久不可点。此处 `catch_unwind` 把 panic 统一转成
/// 失败终态（按钮立即恢复可用）+ error 日志；正常路径零改动。返回
/// `JoinHandle`（调用方可忽略；测试用于等待线程结束）。
pub(crate) fn spawn_connect_thread<F>(f: F) -> std::thread::JoinHandle<()>
where
    F: FnOnce() + Send + 'static,
{
    std::thread::spawn(move || {
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(f));
        if result.is_err() {
            if let Ok(mut s) = connection_status().lock() {
                *s = t!("connect.error.connect_thread_panic").to_string();
            }
        }
    })
}

