    /// 单 label / 非法字符 / label 超长 / 总长超长）。
    #[test]
    fn test_r137_13_node_domain_is_fqdn() {
        // 合法。
        assert!(node_domain_is_fqdn("relay.example.com").is_ok());
        assert!(node_domain_is_fqdn("a.b").is_ok());
        assert!(node_domain_is_fqdn("r-1.example.co.uk").is_ok());
        assert!(node_domain_is_fqdn("  relay.example.com  ").is_ok()); // trim
        // 非法。
        assert!(node_domain_is_fqdn("").is_err());
        assert!(node_domain_is_fqdn("example.com:7000").is_err()); // 端口
        assert!(node_domain_is_fqdn("example .com").is_err()); // 空白
        assert!(node_domain_is_fqdn(".example.com").is_err());
        assert!(node_domain_is_fqdn("example.com.").is_err());
        assert!(node_domain_is_fqdn("example..com").is_err());
        assert!(node_domain_is_fqdn("example").is_err()); // 单 label
        assert!(node_domain_is_fqdn("-example.com").is_err());
        assert!(node_domain_is_fqdn("example-.com").is_err());
        assert!(node_domain_is_fqdn("exam_ple.com").is_err());
        assert!(node_domain_is_fqdn("example.c0m").is_err()); // TLD 含数字
        // label >63 / 总长 >253。
        let long_label = "a".repeat(64);
        assert!(node_domain_is_fqdn(&format!("{long_label}.com")).is_err());
        let long_total = vec!["a".repeat(63); 4].join("."); // 255 > 253
        assert!(node_domain_is_fqdn(&long_total).is_err());
    }

    /// 字母表/pad 位置/非 4 倍数 → None）。
    #[test]
    fn test_r137_13_b64_standard_decoded_len() {
        assert_eq!(
            b64_standard_decoded_len("AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA="),
            Some(32)
        );
        assert_eq!(b64_standard_decoded_len("QUJDRA=="), Some(4)); // "BCDEF" 前 4 字节组
        assert_eq!(b64_standard_decoded_len("QUJD"), Some(3)); // "ABC"
        assert_eq!(b64_standard_decoded_len("QUJ="), Some(2));
        assert_eq!(b64_standard_decoded_len("QQ=="), Some(1));
        assert_eq!(b64_standard_decoded_len("QQ==="), None); // pad>2
        assert_eq!(b64_standard_decoded_len("Q=JD"), None); // pad 在体内
        assert_eq!(b64_standard_decoded_len("QUJDRA"), None); // 非 4 倍数
        assert_eq!(b64_standard_decoded_len("QU-JDRAA"), None); // URL-safe 字母
        assert_eq!(b64_standard_decoded_len("QU_JDRAA"), None);
        assert_eq!(b64_standard_decoded_len(""), None);
        assert_eq!(
            b64_standard_decoded_len(
                "  AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=  "
            ),
            Some(32)
        ); // trim
    }

