#[cfg(test)]
mod r113_tests {
    use super::*;
    use std::time::{Duration, Instant};

    /// （两槽一并消退，弹窗入口随之失效）；次帧空串 episode 边界不重复
    /// 触发。持 `test_serial` 与 r74e/r62/r74f 等写 `connection_status`
    /// 的测试串行。
    #[tokio::test]
    async fn test_r113_tick_fades_terminal_state_after_5s() {
        let _serial = crate::server_media::test_serial().lock().await;
        let terminal = "Connected to alice@10.0.0.7:59990 (transport: TCP)";
        *connection_status().lock().unwrap() = terminal.to_string();
        *connection_failure_detail().lock().unwrap() = Some("stale detail".to_string());
        {
            let mut f = connect_terminal_fade().lock().unwrap();
            f.last_status = terminal.to_string();
            f.terminal_since =
                Some(Instant::now() - CONNECT_TERMINAL_FADE_TIMEOUT - Duration::from_secs(1));
        }
        connect_watchdog_tick();
        assert!(
            connection_status().lock().unwrap().is_empty(),
            "terminal state must auto-fade after 5s (no longer 常驻)"
        );
        assert!(
            connection_failure_detail().lock().unwrap().is_none(),
        );
        connect_watchdog_tick();
        assert!(
            connection_status().lock().unwrap().is_empty(),
            "second frame must be a no-op (episode switched to empty)"
        );
        // 复位全局态（防泄漏进其他测试）。
        let mut f = connect_terminal_fade().lock().unwrap();
        f.last_status.clear();
        f.terminal_since = None;
        let mut w = connect_watchdog().lock().unwrap();
        w.last_status.clear();
        w.busy_since = None;
    }

    /// （用户阅读窗口保留）；详情槽同保。
    #[tokio::test]
    async fn test_r113_tick_keeps_terminal_state_under_5s() {
        let _serial = crate::server_media::test_serial().lock().await;
        let terminal = "Connected to alice@10.0.0.7:59990 (transport: TCP)";
        *connection_status().lock().unwrap() = terminal.to_string();
        *connection_failure_detail().lock().unwrap() = Some("detail".to_string());
        {
            let mut f = connect_terminal_fade().lock().unwrap();
            f.last_status = terminal.to_string();
            f.terminal_since = Some(Instant::now() - Duration::from_secs(2));
        }
        connect_watchdog_tick();
        assert_eq!(
            connection_status().lock().unwrap().as_str(),
            terminal,
            "<5s terminal state must NOT fade"
        );
        assert!(
            connection_failure_detail().lock().unwrap().is_some(),
            "detail slot must persist with the status"
        );
        // 复位全局态（防泄漏进其他测试）。
        connection_status().lock().unwrap().clear();
        connection_failure_detail().lock().unwrap().take();
        let mut f = connect_terminal_fade().lock().unwrap();
        f.last_status.clear();
        f.terminal_since = None;
    }

    /// 提示彻底消失；再点无副作用（幂等）。
    #[tokio::test]
    async fn test_r113_manual_clear_clears_both_slots() {
        let _serial = crate::server_media::test_serial().lock().await;
        *connection_status().lock().unwrap() = "Handshake FAILED\n对方离线：…".to_string();
        *connection_failure_detail().lock().unwrap() = Some("detail".to_string());
        connection_status_clear();
        assert!(
            connection_status().lock().unwrap().is_empty(),
            "manual ✕ must clear the status"
        );
        assert!(
            connection_failure_detail().lock().unwrap().is_none(),
            "manual ✕ must clear the detail slot too"
        );
        connection_status_clear();
        assert!(connection_status().lock().unwrap().is_empty(), "idempotent");
    }

    /// 剥离 + waiting_approval 双语串）/ 成功终态 / 失败终态 / 空串全部
    /// 归类正确（终态判定 = 非空 ∧ 非 busy，locale 无关）。
    #[test]
    fn r113_is_connect_status_terminal_matrix() {
        use crate::policy::is_connect_status_busy;
        // busy 前缀各态 → 非终态（进行态不消退、不显示 ✕）。
        for s in [
            "Discovering: my-pc.example.com ...",
            "Resolving: HD-62EC5BC9 (relay 8.133.174.128:7000) ...",
            "Connecting: 192.168.1.79:59990 ...",
            "Handshaking: ...",
            "[shell] Connecting: 192.168.1.79 ...",
        ] {
            assert!(is_connect_status_busy(s), "should be busy: {s:?}");
            assert!(!is_connect_status_terminal(s), "busy is NOT terminal: {s:?}");
        }
        // waiting_approval 双语串（写入时语言本地化；判定语言无关）。
        let zh = crate::i18n::tr_lang(crate::i18n::Lang::Zh, "connect.status.waiting_approval");
        let en = crate::i18n::tr_lang(crate::i18n::Lang::En, "connect.status.waiting_approval");
        assert!(!zh.is_empty() && !en.is_empty());
        assert!(!is_connect_status_terminal(zh), "zh waiting_approval is busy");
        assert!(!is_connect_status_terminal(en), "en waiting_approval is busy");
        // 成功终态（含 [shell] 前缀）→ 终态。
        for s in [
            "Connected to bob@192.168.1.79 (transport: TCP)",
            "[shell] Connected to bob@192.168.1.79:59990 (transport: TCP)",
        ] {
            assert!(!is_connect_status_busy(s), "should NOT be busy: {s:?}");
            assert!(is_connect_status_terminal(s), "success is terminal: {s:?}");
        }
        for s in [
            "Handshake FAILED\n对方审批超时：…",
            "[shell] Handshake FAILED\n对方离线：…",
            "TCP connect FAILED: 192.168.1.79\n对方离线：…",
            "等待对方审批超时（长时间无响应）——按钮已恢复，请重试",
        ] {
            assert!(!is_connect_status_busy(s), "should NOT be busy: {s:?}");
            assert!(is_connect_status_terminal(s), "failure is terminal: {s:?}");
        }
        // 空串 → 非终态（无状态=渲染侧本就不渲染，非消退目标）。
        assert!(!is_connect_status_terminal(""), "empty is NOT terminal");
    }

    /// 不消退）/ <5s 不清 / ≥5s 清 / 消退后串变空 → 次帧空串边界不重复
    /// 触发（防每帧连发清空）。
    #[test]
    fn r113_terminal_fade_check_threshold() {
        let t0 = Instant::now();
        let timeout = CONNECT_TERMINAL_FADE_TIMEOUT;
        let mut st = ConnectTerminalFadeState::default();
        let ok = "Connected to bob@192.168.1.79 (transport: TCP)";
        // 首帧观察终态 → 记起点，同帧不消退（避免连接刚完成即被清）。
        assert!(!connect_terminal_fade_check(ok, &mut st, t0, timeout));
        assert!(st.terminal_since.is_some(), "terminal start must be recorded");
        // <5s → 不消退。
        assert!(!connect_terminal_fade_check(ok, &mut st, t0 + Duration::from_secs(4), timeout));
        assert!(st.terminal_since.is_some(), "start must persist below threshold");
        // ≥5s → 消退触发（返回 true），起点复位。
        assert!(connect_terminal_fade_check(ok, &mut st, t0 + Duration::from_secs(5), timeout));
        assert!(st.terminal_since.is_none(), "start must reset after firing");
        // 调用方清空后串 = 空 → 次帧 episode 边界，不重复触发。
        assert!(!connect_terminal_fade_check("", &mut st, t0 + Duration::from_secs(6), timeout));
        assert!(st.terminal_since.is_none());
    }

    /// 终态起点（「busy 写入视为清时间戳」；旧起点不泄漏进新 episode）；
    /// busy 期任意时长都不消退（busy 归看门狗管）；新尝试的终态从**新
    /// 起点**重新计满 5s。
    #[test]
    fn r113_terminal_fade_busy_write_clears_since() {
        let t0 = Instant::now();
        let timeout = CONNECT_TERMINAL_FADE_TIMEOUT;
        let mut st = ConnectTerminalFadeState::default();
        let failed = "Handshake FAILED\n对方离线：…";
        // 旧终态已计时 2s（未满 5s）。
        assert!(!connect_terminal_fade_check(failed, &mut st, t0, timeout));
        assert!(!connect_terminal_fade_check(failed, &mut st, t0 + Duration::from_secs(2), timeout));
        assert!(st.terminal_since.is_some());
        // 新尝试 → 「Connecting: …」（busy 前缀）覆盖 → 清起点，不消退。
        let busy = "Connecting: 192.168.77.79:59990 ...";
        assert!(!connect_terminal_fade_check(busy, &mut st, t0 + Duration::from_secs(3), timeout));
        assert!(st.terminal_since.is_none(), "busy write must clear terminal since");
        // busy 期跨旧起点 +6s 也绝不消退（busy 行为零变化）。
        assert!(!connect_terminal_fade_check("Handshaking: ...", &mut st, t0 + Duration::from_secs(6), timeout));
        assert!(st.terminal_since.is_none());
        // 新尝试成功 → 新终态从新起点起算，旧起点不生效（+4s 不清）。
        let ok2 = "Connected to carol@192.168.77.79 (transport: TCP)";
        let t_new = t0 + Duration::from_secs(10);
        assert!(!connect_terminal_fade_check(ok2, &mut st, t_new, timeout));
        assert!(!connect_terminal_fade_check(ok2, &mut st, t_new + Duration::from_secs(4), timeout));
        // 新起点 +5s → 才消退。
        assert!(connect_terminal_fade_check(ok2, &mut st, t_new + Duration::from_secs(5), timeout));
    }
}

// ════════════════════════════════════════════════════════════════
