#[cfg(test)]
mod r114_tests {
    use super::*;

    /// Collapsed（收起态迷你条：「全屏 + 展开工具栏」两钮）；新窗构造
    /// 「默认展开」口径由本测推翻钉死。
    #[test]
    fn test_r157_default_state_is_collapsed() {
        assert_eq!(ToolbarState::default(), ToolbarState::Collapsed);
        // 三态互斥完备（Debug/PartialEq 派生一致性）。
        assert_ne!(ToolbarState::Expanded, ToolbarState::Collapsed);
        assert_ne!(ToolbarState::Collapsed, ToolbarState::Hidden);
        assert_ne!(ToolbarState::Hidden, ToolbarState::Expanded);
    }

    #[test]
    fn test_r114_state_machine_legal_transitions() {
        // Expanded → Collapsed / Hidden（条右端 ▁ / 🙈）。
        assert_eq!(
            toolbar_state_next(ToolbarState::Expanded, ToolbarEvent::Collapse),
            ToolbarState::Collapsed
        );
        assert_eq!(
            toolbar_state_next(ToolbarState::Expanded, ToolbarEvent::Hide),
            ToolbarState::Hidden
        );
        // （矩阵完备性，UI 不渲染该控件但转移合法）。
        assert_eq!(
            toolbar_state_next(ToolbarState::Collapsed, ToolbarEvent::HandleClick),
            ToolbarState::Expanded
        );
        assert_eq!(
            toolbar_state_next(ToolbarState::Collapsed, ToolbarEvent::Hide),
            ToolbarState::Hidden
        );
        // Hidden → Expanded（仅 📌恢复常驻；悬停类事件绝不改态）。
        assert_eq!(
            toolbar_state_next(ToolbarState::Hidden, ToolbarEvent::Restore),
            ToolbarState::Expanded
        );
    }

    /// 关键 no-op 点名：Hidden 悬停/离开不误切常驻；Expanded 无把手/顶边语义）。
    #[test]
    fn test_r114_state_machine_noop_matrix() {
        let states = [
            ToolbarState::Expanded,
            ToolbarState::Collapsed,
            ToolbarState::Hidden,
        ];
        let events = [
            ToolbarEvent::Collapse,
            ToolbarEvent::Hide,
            ToolbarEvent::Restore,
            ToolbarEvent::HandleClick,
            ToolbarEvent::TopEdgeHover,
            ToolbarEvent::HotzoneLeave,
        ];
        let mut changed = 0;
        for cur in states {
            for ev in events {
                if toolbar_state_next(cur, ev) != cur {
                    changed += 1;
                }
            }
        }
        assert_eq!(changed, 5, "exactly the 5 legal transitions must change state");
        // 点名 no-op（行为回归钉死）：
        assert_eq!(
            toolbar_state_next(ToolbarState::Hidden, ToolbarEvent::TopEdgeHover),
            ToolbarState::Hidden,
            "hover must not promote Hidden to persistent"
        );
        assert_eq!(
            toolbar_state_next(ToolbarState::Hidden, ToolbarEvent::HotzoneLeave),
            ToolbarState::Hidden
        );
        assert_eq!(
            toolbar_state_next(ToolbarState::Expanded, ToolbarEvent::HandleClick),
            ToolbarState::Expanded
        );
        assert_eq!(
            toolbar_state_next(ToolbarState::Expanded, ToolbarEvent::TopEdgeHover),
            ToolbarState::Expanded
        );
        assert_eq!(
            toolbar_state_next(ToolbarState::Collapsed, ToolbarEvent::Collapse),
            ToolbarState::Collapsed
        );
        assert_eq!(
            toolbar_state_next(ToolbarState::Hidden, ToolbarEvent::Collapse),
            ToolbarState::Hidden
        );
    }

    /// 内点命中，上下左右越界不命中，无指针未命中，顶边偏移（offset_y）整体
    /// 平移，尺寸钉死（两钮口径）。
    #[test]
    fn test_r114_handle_hit_geometry() {
        let w = 960.0;
        let handle = toolbar_collapsed_rect(w, 0.0);
        // 尺寸钉死 = 「全屏 + 展开工具栏」两钮 + 内边距口径。
        assert_eq!(
            handle.size(),
            egui::vec2(TOOLBAR_COLLAPSED_W, TOOLBAR_COLLAPSED_H)
        );
        // 中心点 + 内部点命中。
        assert!(toolbar_rect_hit(Some(handle.center()), handle));
        assert!(toolbar_rect_hit(
            Some(egui::pos2(handle.center().x, handle.min.y + 1.0)),
            handle
        ));
        // 上/下/左/右越界不命中。
        assert!(!toolbar_rect_hit(
            Some(egui::pos2(handle.center().x, handle.min.y - 1.0)),
            handle
        ));
        assert!(!toolbar_rect_hit(
            Some(egui::pos2(handle.center().x, handle.max.y + 1.0)),
            handle
        ));
        assert!(!toolbar_rect_hit(
            Some(egui::pos2(handle.min.x - 1.0, handle.center().y)),
            handle
        ));
        assert!(!toolbar_rect_hit(
            Some(egui::pos2(handle.max.x + 1.0, handle.center().y)),
            handle
        ));
        // 无指针 = 未命中。
        assert!(!toolbar_rect_hit(None, handle));
        // 迷你条顶部中央（窗宽 960 → 中心 x=480）+ 状态条偏移整体下移。
        assert!((handle.center().x - 480.0).abs() < f32::EPSILON);
        let offset = toolbar_collapsed_rect(w, 32.0);
        assert!((offset.min.y - (32.0 + TOOLBAR_COLLAPSED_Y)).abs() < f32::EPSILON);
        assert!(!toolbar_rect_hit(Some(egui::pos2(480.0, 10.0)), offset));
        assert!(toolbar_rect_hit(Some(egui::pos2(480.0, offset.center().y)), offset));
    }

    /// 命中浮现；无指针/窗外/条体下方/状态条区内不浮现（offset 整体平移）。
    #[test]
    fn test_r114_hidden_emerge_hot_zones() {
        let w = 960.0;
        // 无指针 → 隐藏。
        assert!(!toolbar_hidden_emerge(None, w, 0.0));
        // ① 窗顶边缘窄带（y=4 < 8px）。
        assert!(toolbar_hidden_emerge(Some(egui::pos2(300.0, 4.0)), w, 0.0));
        // ② 条体（y=30 < 40px：指针已在条上 → 防抖保持显示）。
        assert!(toolbar_hidden_emerge(Some(egui::pos2(300.0, 30.0)), w, 0.0));
        // ③ 右上角固定入口（24px 见方内）。
        assert!(toolbar_hidden_emerge(Some(egui::pos2(w - 10.0, 10.0)), w, 0.0));
        // 不浮现：条体下方 / 窗外右侧 / 窗外左侧。
        assert!(!toolbar_hidden_emerge(Some(egui::pos2(300.0, 60.0)), w, 0.0));
        assert!(!toolbar_hidden_emerge(Some(egui::pos2(w + 10.0, 4.0)), w, 0.0));
        assert!(!toolbar_hidden_emerge(Some(egui::pos2(-1.0, 4.0)), w, 0.0));
        // offset（状态条占顶部 30px）：热区整体下移，状态条区内（y<offset）不浮现。
        assert!(toolbar_hidden_emerge(Some(egui::pos2(300.0, 34.0)), w, 30.0));
        assert!(!toolbar_hidden_emerge(Some(egui::pos2(300.0, 29.0)), w, 30.0));
        assert!(!toolbar_hidden_emerge(Some(egui::pos2(300.0, 30.0 + 60.0)), w, 30.0));
    }

    /// （两主题观感随主题，常量集中可调）。
    #[test]
    fn test_r114_bar_fill_alpha() {
        let theme = theme::Theme::DARK;
        let base = toolbar_bar_fill(&theme, TOOLBAR_BASE_ALPHA);
        let hover = toolbar_bar_fill(&theme, TOOLBAR_HOVER_ALPHA);
        assert_eq!(base.to_srgba_unmultiplied()[3], TOOLBAR_BASE_ALPHA);
        assert_eq!(hover.to_srgba_unmultiplied()[3], TOOLBAR_HOVER_ALPHA);
        // RGB 取自主题底色（Color32 存储往返 ±1 舍入容差内）。
        let [r, g, b, _] = theme.bg.to_srgba_unmultiplied();
        let [fr, fg, fb, _] = base.to_srgba_unmultiplied();
        assert!((fr as i32 - r as i32).abs() <= 1);
        assert!((fg as i32 - g as i32).abs() <= 1);
        assert!((fb as i32 - b as i32).abs() <= 1);
    }
}

