#[cfg(test)]
mod r114b_tests {
    use super::*;

    /// （bounds.min.y = offset_y）不进；零尺寸窗/条大于窗回落 bounds.min。
    #[test]
    fn test_r114b_clamp_pos_matrix() {
        let bounds = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(960.0, 540.0));
        let size = egui::vec2(300.0, 40.0);
        // 窗内：原位不动。
        assert_eq!(
            toolbar_clamp_pos(egui::pos2(100.0, 80.0), size, bounds),
            egui::pos2(100.0, 80.0)
        );
        // 越界四向：左/右/上/下 各收回对应边界。
        assert_eq!(
            toolbar_clamp_pos(egui::pos2(-50.0, 80.0), size, bounds),
            egui::pos2(0.0, 80.0)
        );
        assert_eq!(
            toolbar_clamp_pos(egui::pos2(900.0, 80.0), size, bounds),
            egui::pos2(660.0, 80.0)
        );
        assert_eq!(
            toolbar_clamp_pos(egui::pos2(100.0, -20.0), size, bounds),
            egui::pos2(100.0, 0.0)
        );
        assert_eq!(
            toolbar_clamp_pos(egui::pos2(100.0, 500.0), size, bounds),
            egui::pos2(100.0, 500.0)
        );
        // 角落越界：两轴同时收回。
        assert_eq!(
            toolbar_clamp_pos(egui::pos2(-5.0, 999.0), size, bounds),
            egui::pos2(0.0, 500.0)
        );
        // 状态条占顶 32px（bounds.min.y = 32）：条体不进入状态条区。
        let b32 = egui::Rect::from_min_max(egui::pos2(0.0, 32.0), egui::pos2(960.0, 540.0));
        assert_eq!(
            toolbar_clamp_pos(egui::pos2(10.0, 10.0), size, b32),
            egui::pos2(10.0, 32.0)
        );
        assert_eq!(
            toolbar_clamp_pos(egui::pos2(10.0, 539.0), size, b32),
            egui::pos2(10.0, 500.0)
        );
        // 零尺寸窗：回落 (0, 0)，不越界不 panic。
        let zero = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(0.0, 0.0));
        assert_eq!(
            toolbar_clamp_pos(egui::pos2(120.0, 90.0), size, zero),
            egui::pos2(0.0, 0.0)
        );
        // 条宽超窗宽（内容溢出）：x 钉左缘，y 正常夹取。
        let wide = egui::vec2(1200.0, 40.0);
        assert_eq!(
            toolbar_clamp_pos(egui::pos2(80.0, 10.0), wide, bounds),
            egui::pos2(0.0, 10.0)
        );
    }

    /// 重置（idle 回 <3s）→ 178。
    #[test]
    fn test_r114b_idle_alpha_levels() {
        assert_eq!(TOOLBAR_IDLE_DIM_SECS, 3.0);
        assert!(TOOLBAR_ALPHA_IDLE < TOOLBAR_BASE_ALPHA);
        assert!(TOOLBAR_BASE_ALPHA < TOOLBAR_HOVER_ALPHA);
        // 悬停：恒 230（空闲时长无关）。
        assert_eq!(toolbar_idle_alpha(true, 0.0), TOOLBAR_HOVER_ALPHA);
        assert_eq!(toolbar_idle_alpha(true, 3.0), TOOLBAR_HOVER_ALPHA);
        assert_eq!(toolbar_idle_alpha(true, 1000.0), TOOLBAR_HOVER_ALPHA);
        // 不悬停：<3s 不降（静止档）。
        assert_eq!(toolbar_idle_alpha(false, 0.0), TOOLBAR_BASE_ALPHA);
        assert_eq!(toolbar_idle_alpha(false, 2.9), TOOLBAR_BASE_ALPHA);
        // 不悬停：≥3s 降透明（边界恰 3.0 = 降）。
        assert_eq!(toolbar_idle_alpha(false, 3.0), TOOLBAR_ALPHA_IDLE);
        assert_eq!(toolbar_idle_alpha(false, 5.5), TOOLBAR_ALPHA_IDLE);
        // 交互重置：idle 回落到 <3s → 静止档（不自动收缩/隐藏=alpha 之外无副作用）。
        assert_eq!(toolbar_idle_alpha(false, 0.5), TOOLBAR_BASE_ALPHA);
    }

    /// 夹取在窗内、尺寸恒定；指针落于拖后条体 = 命中（不转发远端）。
    #[test]
    fn test_r114b_dragged_rect_links_occlusion() {
        let bounds = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(960.0, 540.0));
        let size = egui::vec2(420.0, 40.0);
        let anchor = egui::pos2(0.0, 0.0);
        // 零位移：留在左上。
        let r0 = toolbar_dragged_rect(anchor, egui::vec2(0.0, 0.0), size, bounds);
        assert_eq!(r0.min, anchor);
        assert_eq!(r0.size(), size);
        // 正常位移：矩形 = 锚点+位移（occlusion 随动），尺寸不变。
        let r1 = toolbar_dragged_rect(anchor, egui::vec2(120.0, 60.0), size, bounds);
        assert_eq!(r1.min, egui::pos2(120.0, 60.0));
        assert_eq!(r1.size(), size);
        assert!(toolbar_rect_hit(Some(r1.center()), r1));
        // 右越界：x 夹到右缘；指针在夹取后条体内仍命中。
        let r2 = toolbar_dragged_rect(anchor, egui::vec2(5000.0, 10.0), size, bounds);
        assert_eq!(r2.min.x, 960.0 - 420.0);
        assert!(toolbar_rect_hit(Some(r2.max - egui::vec2(1.0, 1.0)), r2));
        // 上/下越界：y 各夹到对应边界。
        let r3 = toolbar_dragged_rect(anchor, egui::vec2(10.0, -50.0), size, bounds);
        assert_eq!(r3.min.y, 0.0);
        let r4 = toolbar_dragged_rect(anchor, egui::vec2(10.0, 999.0), size, bounds);
        assert_eq!(r4.min.y, 540.0 - 40.0);
        // 状态条占顶 32px（bounds.min.y = 32）：y 下界 = 32。
        let b32 = egui::Rect::from_min_max(egui::pos2(0.0, 32.0), egui::pos2(960.0, 540.0));
        let r5 = toolbar_dragged_rect(egui::pos2(0.0, 32.0), egui::vec2(5.0, -100.0), size, b32);
        assert_eq!(r5.min.y, 32.0);
        assert_eq!(r5.min.x, 5.0);
    }

    /// 锚点+累计位移 ⇒ 无「边界粘滞」（触壁收回后单步即可脱壁，区别于
    /// 「夹取值+逐帧增量」会粘滞的口径）。
    #[test]
    fn test_r114b_drag_sequence_stays_in_bounds() {
        let bounds = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(800.0, 500.0));
        let size = egui::vec2(300.0, 40.0);
        let anchor = egui::pos2(0.0, 0.0);
        let steps = [
            egui::vec2(100.0, 20.0),   // 窗内正常移动
            egui::vec2(900.0, 40.0),   // 右越界 → x 夹 500
            egui::vec2(-600.0, 100.0), // 单步拉回（粘滞口径会错算到 x=0）
            egui::vec2(200.0, -300.0), // x 再触右壁、y 越上界 → 夹 (500, 0)
            egui::vec2(-300.0, 50.0),  // 收回窗内
        ];
        let mut delta = egui::Vec2::ZERO;
        for s in steps {
            delta += s;
            let r = toolbar_dragged_rect(anchor, delta, size, bounds);
            assert!(r.min.x >= bounds.min.x, "step {delta}: x 越出窗左");
            assert!(r.min.y >= bounds.min.y, "step {delta}: y 越出窗上");
            assert!(r.max.x <= bounds.max.x, "step {delta}: x 越出窗右");
            assert!(r.max.y <= bounds.max.y, "step {delta}: y 越出窗下");
        }
        // 逐步钉死（含无粘滞判别步）。
        assert_eq!(
            toolbar_dragged_rect(anchor, egui::vec2(100.0, 20.0), size, bounds).min,
            egui::pos2(100.0, 20.0)
        );
        assert_eq!(
            toolbar_dragged_rect(anchor, egui::vec2(1000.0, 60.0), size, bounds).min,
            egui::pos2(500.0, 60.0)
        );
        // 关键判别：x 曾触壁 500，单步 -600 → 直接 400（非粘滞的 0）。
        assert_eq!(
            toolbar_dragged_rect(anchor, egui::vec2(400.0, 160.0), size, bounds).min,
            egui::pos2(400.0, 160.0)
        );
        assert_eq!(
            toolbar_dragged_rect(anchor, egui::vec2(600.0, -140.0), size, bounds).min,
            egui::pos2(500.0, 0.0)
        );
        // 终点（delta 累计 = (300, -90)）。
        assert_eq!(
            toolbar_dragged_rect(anchor, egui::vec2(300.0, -90.0), size, bounds).min,
            egui::pos2(300.0, 0.0)
        );
    }
}

// ════════════════════════════════════════════════════════════════
// （纯函数族：宽决策 / 把手交互判定 / 把手矩形 / i18n 配对 / badge 门控）
// ════════════════════════════════════════════════════════════════
#[cfg(test)]
mod r120_tests {
    use super::*;

    /// 自适应宽：未实测→全宽过渡帧；实测 < 屏宽→内容宽；实测 ≥ 屏宽→全宽
    /// 回退（超窄窗内容溢出，右端按钮恒可达）。
    #[test]
    fn r120_bar_width_decision() {
        let screen = 960.0;
        // 未实测（0 = 尚未测量 / 1.0 边界含）→ 全宽过渡帧。
        assert_eq!(toolbar_bar_width(0.0, screen), screen);
        assert_eq!(toolbar_bar_width(1.0, screen), screen);
        // 实测内容宽 < 屏宽 → 内容宽（默认态即生效，全宽死锁解除）。
        assert_eq!(toolbar_bar_width(420.0, screen), 420.0);
        assert_eq!(toolbar_bar_width(screen - 1.0, screen), screen - 1.0);
        // 实测内容宽 == 屏宽（边界）→ 全宽回退（内容贴满）。
        assert_eq!(toolbar_bar_width(screen, screen), screen);
        // 实测内容宽 > 屏宽（超窄窗内容溢出）→ 全宽回退。
        assert_eq!(toolbar_bar_width(1200.0, screen), screen);
        // 次帧收敛口径：过渡帧全宽 → 若实测收敛为内容宽（< 屏宽）即取内容宽
        // （模拟「首帧全宽过渡、次帧内容宽」两帧序列）。
        let f1 = toolbar_bar_width(0.0, screen); // 全宽过渡
        assert_eq!(f1, screen);
        let f2 = toolbar_bar_width(420.0, screen); // 次帧实测内容宽
        assert_eq!(f2, 420.0);
    }

    /// 实测换算逐帧闭环）：
    /// - 初始窗 960（内容 970 溢出）→ 全宽回退 960（右端按钮可达，设计回退）；
    /// - 最大化 1920 → **内容宽 970**（用户期望形态：最大化 = 内容宽，
    ///   修前 = 恒全宽「宽度最大」）；
    /// - 还原 960 → 回退 960；再最大化 → 970：宽度恒为 (内容宽, 窗宽) 的
    ///   纯函数，往返 3 次同态同值 = 零回跳（无振荡/无逐帧漂移）。
    #[test]
    fn r132_7_maximize_roundtrip_no_springback() {
        const M: f32 = 12.0; // 条体内边距两侧和（与渲染层 Margin::symmetric(6,2) 同源）
        const L3: f32 = 250.0; // 左段自然宽（grip + 徽标组）
        const R3: f32 = 700.0; // 右段自然宽（按钮组）
        let content_w = M + L3 + TOOLBAR_GROUP_GAP + R3; // = 970

        /// 一帧闭环：决策宽（输入 = 上一帧实测）+ 本帧实测换算。
        /// 返回 (本帧决策宽, 本帧实测内容宽)。
        fn frame(prev_measured: f32, window_w: f32) -> (f32, f32) {
            let bar_w = toolbar_bar_width(prev_measured, window_w);
            // 渲染层同一口径：左段末游标 = L3（左缘起）；右段自条体右缘
            // （bar_w - M）起右→左布 R3 → 末游标 = bar_w - M - R3。
            let measured = crate::hover_hint::toolbar_content_width(
                bar_w,
                TOOLBAR_GROUP_GAP,
                L3,
                bar_w - M - R3,
            );
            (bar_w, measured)
        }

        // 帧 0：新窗未实测（ZERO）→ 全宽过渡帧。
        let (w0, m0) = frame(0.0, 960.0);
        assert_eq!(w0, 960.0); // 过渡帧全宽（次帧收敛设计）
        assert!((m0 - content_w).abs() < 1e-3, "m0={m0}");
        // 帧 1（窗 960，内容 970 溢出）→ 全宽回退 960（设计回退，右端可达）。
        let (w1, m1) = frame(m0, 960.0);
        assert_eq!(w1, 960.0);
        // 最大化 → 1920：决策 = 内容宽 970（修前此态 = 恒全宽 = 用户所见）。
        let (w2, m2) = frame(m1, 1920.0);
        assert!((w2 - content_w).abs() < 1e-3, "最大化后条宽须=内容宽: {w2}");
        // 还原 → 960：回退 960；再最大化 → 970；还原 → 960（往返 3 次）。
        let (w3, m3) = frame(m2, 960.0);
        assert_eq!(w3, 960.0);
        let (w4, m4) = frame(m3, 1920.0);
        assert!((w4 - content_w).abs() < 1e-3, "往返#1 最大化: {w4}");
        let (w5, m5) = frame(m4, 960.0);
        assert_eq!(w5, 960.0);
        let (w6, m6) = frame(m5, 1920.0);
        assert!((w6 - content_w).abs() < 1e-3, "往返#2 最大化: {w6}");
        let (w7, m7) = frame(m6, 960.0);
        assert_eq!(w7, 960.0);
        // 零回跳判据：同窗宽下宽度逐帧恒定（收敛后无振荡）；实测内容宽恒
        // = 自然宽（与条体当前宽无关 = 回跳的结构性不可能）。
        for _ in 0..3 {
            let (ws, ms) = frame(m7, 960.0);
            assert_eq!(ws, 960.0, "同态宽度漂移");
            assert!((ms - content_w).abs() < 1e-3, "实测宽漂移: {ms}");
        }
        assert!((frame(m7, 1920.0).0 - content_w).abs() < 1e-3);
    }

    /// 恰 = 「全屏」+「展开工具栏」，顺序固定；两键 zh/en 成对非空（渲染层
    /// 交互矩阵/把手拖动矩形两测随单把手形态移除（净 −2，见 CHANGELOG）。
    #[test]
    fn test_r157_collapsed_buttons_composition() {
        let keys = toolbar_collapsed_buttons();
        // 且仅两钮：全屏钮 + 展开钮（顺序=渲染序）。
        assert_eq!(
            keys,
            ["session.toolbar.fullscreen", "session.toolbar.expand"]
        );
        let find = |key: &str| -> Option<(&str, &str, &str)> {
            i18n::ALL
                .iter()
                .flat_map(|t| t.iter())
                .find(|e| e.0 == key)
                .copied()
        };
        for k in keys {
            let e = find(k).unwrap_or_else(|| panic!("i18n key 必须存在: {k}"));
            assert!(!e.1.is_empty(), "{k} zh 不得为空");
            assert!(!e.2.is_empty(), "{k} en 不得为空");
        }
        // 展开钮语义钉死：zh 恰为「展开工具栏」（可辨识口径）。
        assert_eq!(find("session.toolbar.expand").unwrap().1, "展开工具栏");
        assert!(find("session.toolbar.handle").is_none());
    }

    /// alpha 落用户建议 0.70~0.85 区间（178..=217）；②半透明阶梯 = 条体
    /// （230）< 悬停控件（不透明 255，点击辨识档）；③控件底色 RGB 与
    /// 零漂移）。
    #[test]
    fn test_r165_toolbar_widget_alpha_ladder() {
        use widgets::{TOOLBAR_WIDGET_ALPHA, toolbar_widget_fill};
        // ①区间。
        assert_eq!(TOOLBAR_WIDGET_ALPHA, 200);
        assert!((178..=217).contains(&TOOLBAR_WIDGET_ALPHA));
        // ②阶梯序（半透明统一、悬停恢复更高不透明度）。
        assert!(TOOLBAR_BASE_ALPHA < TOOLBAR_WIDGET_ALPHA);
        assert!(TOOLBAR_WIDGET_ALPHA < TOOLBAR_HOVER_ALPHA);
        assert_eq!(TOOLBAR_HOVER_ALPHA, 230);
        // ③RGB 同源 + alpha 透传（双主题）。
        for theme in [theme::Theme::LIGHT, theme::Theme::DARK] {
            let f = toolbar_widget_fill(&theme, TOOLBAR_WIDGET_ALPHA);
            let [r, g, b, _] = theme.bg_strong.to_srgba_unmultiplied();
            assert_eq!(
                f,
                egui::Color32::from_rgba_unmultiplied(r, g, b, TOOLBAR_WIDGET_ALPHA)
            );
        }
    }

    /// 同口径：单把手键 session.toolbar.handle 零消费已删除（不得残留）。
    /// （clip.badge.upload_hint）zh/en 成对非空。
    #[test]
    fn r120_i18n_toolbar_keys_paired() {
        let find = |key: &str| -> Option<(&str, &str, &str)> {
            i18n::ALL
                .iter()
                .flat_map(|t| t.iter())
                .find(|e| e.0 == key)
                .copied()
        };
        for k in [
            "session.toolbar.caps_lock",
            "session.toolbar.kp_multiply",
            "session.toolbar.kp_decimal",
            "session.toolbar.handle",
        ] {
        }
        for k in [
            "session.toolbar.collapse",
            "session.toolbar.expand",
            "session.toolbar.hide",
            "session.toolbar.restore",
            "session.toolbar.drag",
            "session.toolbar.special_keys",
            "clip.badge.upload_hint",
        ] {
            let e = find(k).unwrap_or_else(|| panic!("i18n key 必须存在: {k}"));
            assert!(!e.1.is_empty(), "{k} zh 不得为空");
            assert!(!e.2.is_empty(), "{k} en 不得为空");
        }
        // 栏」两钮口径；expand zh 恰为「展开工具栏」。
        let collapse = find("session.toolbar.collapse").unwrap();
        assert!(collapse.1.contains("点击"), "collapse zh 必须含「点击」: {}", collapse.1);
        assert!(
            collapse.1.contains("展开工具栏"),
            "collapse zh 必须含「展开工具栏」: {}",
            collapse.1
        );
        let expand = find("session.toolbar.expand").unwrap();
        assert_eq!(expand.1, "展开工具栏", "expand zh 恰为「展开工具栏」");
    }

    /// 严格对齐（聚焦 + 有分辨率 + Desktop + 非锁屏 + 本机板文件数 > 0）；
    /// 任一条件不满足即不显（防「提示了却粘不动」的误导形态）。
    #[test]
    fn r120_clip_badge_visible_matrix() {
        // 全满足 → 显。
        assert!(clip_badge_visible(true, 1920, 1080, true, false, Some(3)));
        // 失焦 → 不显。
        assert!(!clip_badge_visible(false, 1920, 1080, true, false, Some(3)));
        // 无分辨率（base_w=0 / base_h=0）→ 不显。
        assert!(!clip_badge_visible(true, 0, 1080, true, false, Some(3)));
        assert!(!clip_badge_visible(true, 1920, 0, true, false, Some(3)));
        // 非 Desktop（Shell 终端语义，badge 会误导）→ 不显。
        assert!(!clip_badge_visible(true, 1920, 1080, false, false, Some(3)));
        // 锁屏（键盘本意暂停，不叠加）→ 不显。
        assert!(!clip_badge_visible(true, 1920, 1080, true, true, Some(3)));
        // 本机板无文件（None / Some(0)）→ 不显。
        assert!(!clip_badge_visible(true, 1920, 1080, true, false, None));
        assert!(!clip_badge_visible(true, 1920, 1080, true, false, Some(0)));
        // 边界：n=1 → 显。
        assert!(clip_badge_visible(true, 1, 1, true, false, Some(1)));
    }
}

