#[cfg(test)]
mod r133_4_tests {
    use super::*;

    /// （Area→set_min/max_size→Frame(6,2)→horizontal→〔左段〕→
    /// with_layout(RTR)〔右段〕→ RTR 子 ui 末游标捕获），真实 egui 0.28.1
    /// 帧上钉死：
    /// ① 可见帧 RTR 闭包必执行、末游标捕获必发生（`Option` 语义与生产
    ///    `r132_rtr_end_x` 同形）= 「回写必发生」回归锁；
    /// ② 修复后取法实测值 = 内容自然宽（两决策宽〔960/1500〕同值 = 与条宽
    /// ③ 旧取法（外层 LTR ui `cursor().max.x`）= +inf（egui placer LTR
    ///    游标不变式：添加方向侧恒无限）→ 旧换算式恒钳 1.0 = 未实测哨兵
    ///    → 决策恒全宽 = G1「宽度钉死最大化」根因缺陷实证钉死（防回潮）；
    /// ④ 端到端：修复后决策 = 内容宽（< 窗宽，用户期望形态）；旧链路决策
    ///    = 全宽（症状复现锚）。
    #[test]
    fn r133_4_probe_writeback_chain() {
        /// + 1 稳态帧），返回 (修复后实测, 旧取法实测, 左段末游标sp修正,
        /// RTR末游标捕获 Option, 外层LTR末游标)。
        fn probe(bar_w: f32) -> (f32, f32, f32, Option<f32>, f32) {
            let ctx = egui::Context::default();
            let mut out: (f32, f32, f32, Option<f32>, f32) =
                (f32::NAN, f32::NAN, f32::NAN, None, f32::NAN);
            for _ in 0..2 {
                let mut raw = egui::RawInput::default();
                raw.screen_rect = Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(1920.0, 1080.0),
                ));
                let _ = ctx.run(raw, |ctx| {
                    egui::Area::new(egui::Id::new("r133_4_probe"))
                        .order(egui::Order::Foreground)
                        .anchor(egui::Align2::LEFT_TOP, [0.0, 0.0])
                        .show(ctx, |ui| {
                            ui.set_min_size(egui::vec2(bar_w, 32.0));
                            ui.set_max_size(egui::vec2(bar_w, 32.0));
                            egui::Frame::none()
                                .inner_margin(egui::Margin::symmetric(6.0, 2.0))
                                .show(ui, |ui| {
                                    ui.horizontal(|ui| {
                                        // 左段（形态等价：grip 标签）。
                                        ui.add(egui::Label::new("≡"));
                                        let left_end_x = ui.cursor().min.x;
                                        // 右段（形态等价：36×32 按钮 ×2，RTR）
                                        // ——RTR 子 ui 末游标闭包内捕获
                                        // （生产 `r132_rtr_end_x` 同形）。
                                        let mut rtr_end_opt: Option<f32> = None;
                                        ui.with_layout(
                                            egui::Layout::right_to_left(egui::Align::Center),
                                            |ui| {
                                                ui.add(egui::Button::new("▁")
                                                    .min_size(egui::vec2(36.0, 32.0)));
                                                ui.add(egui::Button::new("🙈")
                                                    .min_size(egui::vec2(36.0, 32.0)));
                                                rtr_end_opt = Some(ui.cursor().max.x);
                                            },
                                        );
                                        let outer_end_x = ui.cursor().max.x;
                                        let sp = ui.spacing().item_spacing.x;
                                        let l3 = left_end_x - sp;
                                        let rtr_end = rtr_end_opt.unwrap_or(f32::NAN);
                                        // 修复后取法（生产 :16262-16274 同式）。
                                        let meas_new = crate::hover_hint::toolbar_content_width(
                                            bar_w, TOOLBAR_GROUP_GAP, l3, rtr_end + sp,
                                        );
                                        // 旧取法（G1 缺陷：外层 LTR 游标）。
                                        let meas_old = crate::hover_hint::toolbar_content_width(
                                            bar_w, TOOLBAR_GROUP_GAP, l3, outer_end_x + sp,
                                        );
                                        out = (meas_new, meas_old, l3, rtr_end_opt, outer_end_x);
                                    });
                                });
                        });
                });
            }
            out
        }

        // 两决策宽形态（宽窗 960 / 更宽 1500）各复刻一遍。
        let (mn1, mo1, l3a, ro1, oe1) = probe(960.0);
        let (mn2, mo2, l3b, ro2, oe2) = probe(1500.0);

        // ① 可见帧回写必发生（RTR 闭包执行 + 末游标捕获 = Some 且有限）。
        assert!(ro1.is_some_and(|v| v.is_finite()), "RTR 末游标捕获必发生: {ro1:?}");
        assert!(ro2.is_some_and(|v| v.is_finite()), "RTR 末游标捕获必发生: {ro2:?}");
        // ② 修复后实测 = 内容自然宽：有限、>1.0（非未实测哨兵）、两宽同值
        //    （与条宽无关 = 零回跳结构前提）、> 左段宽（含右段，非退化）。
        assert!(mn1.is_finite() && mn1 > 1.0, "修复后实测须有限 >1.0: {mn1}");
        assert_eq!(mn1, mn2, "实测须与决策宽无关（两宽同值）: {mn1} vs {mn2}");
        assert!(mn1 > l3a, "实测须含右段（> 左段宽）: {mn1} vs {l3a}");
        assert_eq!(l3a, l3b, "左段末游标两宽一致（内容不变）");
        // ③ 旧取法缺陷实证：外层 LTR 游标 = +inf → 旧换算恒钳 1.0。
        assert!(oe1.is_infinite() && oe1 > 0.0, "外层 LTR 游标 max.x 须为 +inf: {oe1}");
        assert_eq!(oe1, oe2);
        assert_eq!(mo1, 1.0, "旧取法实测恒 1.0（未实测哨兵 = G1 根因）: {mo1}");
        assert_eq!(mo2, 1.0);
        // ④ 端到端决策：修复后 = 内容宽（用户期望）；旧链路 = 永久全宽。
        let win_w = 1920.0;
        assert_eq!(
            toolbar_bar_width(mn1, win_w),
            mn1,
            "修复后决策 = 内容宽（< 窗宽）"
        );
        assert_eq!(
            toolbar_bar_width(mo1, win_w),
            win_w,
            "旧链路决策 = 全宽（用户所见症状复现锚）"
        );
    }

    /// （修前：全比较 false 静默落 else——同输出但属未钉死输入类）；有限
    /// 输入行为零回归（与 r120_bar_width_decision 同矩阵）。
    #[test]
    fn r133_4_bar_width_nan_hardening() {
        let s = 2230.0;
        assert_eq!(toolbar_bar_width(f32::NAN, s), s, "NaN → 全宽过渡帧（显式分支）");
        assert_eq!(toolbar_bar_width(f32::INFINITY, s), s, "+inf → 全宽（溢出回退同值）");
        assert_eq!(toolbar_bar_width(f32::NEG_INFINITY, s), s, "-inf → 全宽过渡帧");
        // 有限输入零回归（r120 矩阵抽核）。
        assert_eq!(toolbar_bar_width(0.0, s), s);
        assert_eq!(toolbar_bar_width(1.0, s), s);
        assert_eq!(toolbar_bar_width(970.0, s), 970.0);
        assert_eq!(toolbar_bar_width(s, s), s);
        assert_eq!(toolbar_bar_width(5000.0, s), s);
    }

    /// **决策同态钉死**——对全部输入类，归一化值的决策输出 ≡ 旧实现
    /// （`unwrap_or(1.0)` 直传 + 旧分支逻辑，内联复刻）的决策输出
    /// （行为保持加固 = 只清状态不改变视觉行为）。
    #[test]
    fn r133_4_measured_store_decision_isomorphic() {
        // 非有限输入旧行为 = 全比较 false → else 全宽）。
        fn old_decision(measured: Option<f32>, win_w: f32) -> f32 {
            let m = measured.unwrap_or(1.0);
            if m.is_finite() {
                if m <= 1.0 {
                    win_w
                } else if m < win_w {
                    m
                } else {
                    win_w
                }
            } else {
                win_w
            }
        }
        let cases: [Option<f32>; 8] = [
            None,
            Some(f32::NAN),
            Some(f32::INFINITY),
            Some(f32::NEG_INFINITY),
            Some(0.5),
            Some(1.0),
            Some(1.0001),
            Some(970.42),
        ];
        for m in cases {
            let stored = toolbar_measured_store(m);
            assert!(stored.is_finite() && stored >= 1.0, "存储值须有限 ≥1.0: {m:?} → {stored}");
            for win_w in [500.0, 960.0, 2230.0] {
                assert_eq!(
                    toolbar_bar_width(stored, win_w),
                    old_decision(m, win_w),
                    "决策同态: {m:?} win={win_w}"
                );
            }
        }
        // 值类映射（钉死）。
        assert_eq!(toolbar_measured_store(None), 1.0);
        assert_eq!(toolbar_measured_store(Some(f32::NAN)), 1.0);
        assert_eq!(toolbar_measured_store(Some(0.5)), 1.0);
        assert_eq!(toolbar_measured_store(Some(1.0)), 1.0);
        assert_eq!(toolbar_measured_store(Some(1.0001)), 1.0001);
        assert_eq!(toolbar_measured_store(Some(970.42)), 970.42);
    }

    /// （有限一位小数 / nan / none）+ 数值精度形态全钉。
    #[test]
    fn r133_4_trace_line_format_pinned() {
        let (m, d) = toolbar_width_trace_lines(Some(970.0), 970.0, 1920.0);
        let (m, d) = toolbar_width_trace_lines(Some(f32::NAN), 1920.0, 1920.0);
        let (m, _) = toolbar_width_trace_lines(None, 960.0, 960.0);
        // 小数精度锚（一位小数四舍五入形态）。
        let (m, d) = toolbar_width_trace_lines(Some(969.86), 42.14, 2230.0);
    }

    /// （headless 渲染初验——生产形态逐字复刻：Area + Frame margin(6,2) +
    /// `ui.horizontal` 行 + RTR 段 `with_layout(right_to_left(Center))`，
    /// 真实 `toolbar_button` 邻 `egui::ComboBox`，padding override 同式；
    /// 应用风格 button_padding (8,4)〔theme.rs:280〕/ item_spacing (8,6) /
    /// Button 字号 18〔Theme::LIGHT.button_size〕）。
    ///
    /// 机制（egui 0.28.1 源码 + 本用例两帧复现实证）：`ComboBox::show_ui`
    /// 内部把按钮再包一层 `ui.horizontal`（初高 = `interact_size.y` = 18px）；
    /// 父布局（本条行/RTR 段）cross 轴 = `Align::Center` → **稳态帧**该
    /// 18px 子行被**居中**进 32px 行带（ui.rs `allocate_ui_with_layout_dyn`
    /// → `justify_and_align`）→ 按钮框整体下沉 (32−18)/2 = 7px（首帧 Area
    /// `sizing_pass` 把子布局 cross 轴 Center→Min 降级 = 暂不显 → 逐帧形态
    /// 不一致）。修复 = 包一层 TOP 对齐**整带** `allocate_ui_with_layout`
    /// （desired = 当前可用全带 → 外层居中退化为恒等）把子行锚到带顶。
    ///
    /// 双场景钉死：① `pin=false`（修前形态：裸 `show_ui`）——高已 32 但稳态
    /// 帧仍下沉 >1px = 复现用户所见「基线偏移」（钉修复必要性与机制）；
    /// ② `pin=true`（生产形态：TOP 带钉）——按钮框顶/底缘与邻 32px 钮逐帧
    /// 零错位，文本 galley y 中心 ≤1px。
    #[test]
    fn r133_4_combo_box_baseline_aligned() {
        /// 跑两帧：返回 (右段邻钮 rect, ComboBox 按钮框 rect, 末帧 shapes)。
        /// `pin` = 是否走生产 TOP 带钉形态。帧 1 = Area sizing pass（首帧
        /// size 未知，子布局 cross 轴被降级 Min）；帧 2 = 稳态帧（断言对象
        /// ——用户实际所见形态）。
        fn run(pin: bool) -> (egui::Rect, egui::Rect, Vec<egui::epaint::ClippedShape>) {
            let ctx = egui::Context::default();
            let mut st = egui::Style::default();
            st.spacing.button_padding = egui::vec2(8.0, 4.0);
            st.spacing.item_spacing = egui::vec2(8.0, 6.0);
            st.text_styles.insert(
                egui::TextStyle::Button,
                egui::FontId::new(18.0, egui::FontFamily::Proportional),
            );
            ctx.set_style(st);

            let mut btn = egui::Rect::NOTHING;
            let mut combo = egui::Rect::NOTHING;
            let mut shapes: Vec<egui::epaint::ClippedShape> = Vec::new();
            for _ in 0..2 {
                let mut raw = egui::RawInput::default();
                raw.screen_rect = Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(1920.0, 1080.0),
                ));
                shapes = ctx.run(raw, |ctx| {
                    egui::Area::new(egui::Id::new("r133_4_combo"))
                        .order(egui::Order::Foreground)
                        .anchor(egui::Align2::LEFT_TOP, [0.0, 0.0])
                        .show(ctx, |ui| {
                            ui.set_min_size(egui::vec2(600.0, 40.0));
                            ui.set_max_size(egui::vec2(600.0, 40.0));
                            egui::Frame::none()
                                .inner_margin(egui::Margin::symmetric(6.0, 2.0))
                                .show(ui, |ui| {
                                    ui.horizontal(|ui| {
                                        // 左段：邻钮（生产左段同形态）。
                                        crate::widgets::toolbar_button(
                                            ui,
                                            &crate::theme::Theme::LIGHT,
                                            "▁",
                                            "t",
                                        );
                                        // 右段（生产 lib.rs RTR 段同式）。
                                        ui.with_layout(
                                            egui::Layout::right_to_left(egui::Align::Center),
                                            |ui| {
                                                btn = crate::widgets::toolbar_button(
                                                    ui,
                                                    &crate::theme::Theme::LIGHT,
                                                    "✖",
                                                    "t",
                                                )
                                                .rect;
                                                // 生产 padding override 同式。
                                                let sel_text = "🖥 显示器 A".to_string();
                                                let saved_pad = ui.spacing().button_padding;
                                                let text_h = ui.ctx().fonts(|f| {
                                                    f.layout(
                                                        sel_text.to_string(),
                                                        egui::TextStyle::Button
                                                            .resolve(ui.style()),
                                                        egui::Color32::WHITE,
                                                        f32::INFINITY,
                                                    )
                                                    .size()
                                                    .y
                                                });
                                                ui.spacing_mut()
                                                    .button_padding = egui::vec2(
                                                        saved_pad.x,
                                                        (16.0 - text_h / 2.0).max(saved_pad.y),
                                                    );
                                                let mut sel = 0usize;
                                                if pin {
                                                    // 生产形态：TOP 对齐整带钉位。
                                                    // （带高仍 = 全带；垂直口径零变化，详见生产段
                                                    let _ = ui.allocate_ui_with_layout(
                                                        egui::vec2(
                                                            R135_3_DISPLAY_COMBO_W,
                                                            ui.available_size_before_wrap().y,
                                                        ),
                                                        egui::Layout::left_to_right(egui::Align::TOP),
                                                        |ui| {
                                                            combo = egui::ComboBox::from_id_source(
                                                                "r133_4_combo_sel",
                                                            )
                                                            .selected_text(&sel_text)
                                                            .width(170.0)
                                                            .show_ui(ui, |ui| {
                                                                ui.selectable_value(
                                                                    &mut sel,
                                                                    0,
                                                                    "显示器 A 1920×1080 [主屏]",
                                                                );
                                                            })
                                                            .response.rect;
                                                        },
                                                    );
                                                } else {
                                                    // 修前形态：裸 show_ui（机制复现锚）。
                                                    combo = egui::ComboBox::from_id_source("r133_4_combo_sel")
                                                        .selected_text(&sel_text)
                                                        .width(170.0)
                                                        .show_ui(ui, |ui| {
                                                            ui.selectable_value(
                                                                &mut sel,
                                                                0,
                                                                "显示器 A 1920×1080 [主屏]",
                                                            );
                                                        })
                                                        .response.rect;
                                                }
                                                ui.spacing_mut()
                                                    .button_padding = saved_pad;
                                            },
                                        );
                                    });
                                });
                        });
                })
                .shapes;
            }
            (btn, combo, shapes)
        }

        // ① 修前形态（裸 show_ui）：高已 32（padding override 生效），但稳态
        //    帧按钮框仍下沉 >1px = 复现用户所见「基线偏移」——钉死修复的
        //    必要性与机制（若 egui 升级改变该行为，本断言先红提示复核）。
        let (btn_off, combo_off, _off_shapes) = run(false);
        assert!(
            (combo_off.height() - 32.0).abs() < 1e-3,
            "修前形态高亦 32（padding override 生效）: {}",
            combo_off.height()
        );
        assert!(
            combo_off.min.y > btn_off.min.y + 1.0,
            "修前形态须复现基线偏移（combo min.y {} vs btn min.y {}）——TOP 带钉为修复点",
            combo_off.min.y,
            btn_off.min.y
        );

        // ② 生产形态（TOP 带钉）：像素级对齐。
        let (btn, combo, shapes) = run(true);
        // (a) 高度钉死：邻钮 32 = ComboBox 32。
        assert!(
            (btn.height() - 32.0).abs() < 1e-3,
            "邻钮高须 32: {}",
            btn.height()
        );
        assert!(
            (combo.height() - 32.0).abs() < 1e-3,
            "ComboBox 按钮高须恰 32: {}",
            combo.height()
        );
        // (b) 顶/底边同 y（框缘零错位，逐帧同 y 而非仅首帧）。
        assert!(
            (combo.min.y - btn.min.y).abs() <= 0.5,
            "顶边对齐: {} vs {}",
            combo.min.y,
            btn.min.y
        );
        assert!(
            (combo.max.y - btn.max.y).abs() <= 0.5,
            "底边对齐: {} vs {}",
            combo.max.y,
            btn.max.y
        );
        // (c) 文本 galley y 中心对齐（像素级 ≤1px = 基线对齐）。
        let text_center = |shapes: &[egui::epaint::ClippedShape], text: &str| -> Option<f32> {
            shapes.iter().find_map(|cs| match &cs.shape {
                egui::Shape::Text(t) if t.galley.job.text == text => {
                    Some(t.pos.y + t.galley.rect.height() / 2.0)
                }
                _ => None,
            })
        };
        let c_btn = text_center(&shapes, "▁").expect("邻钮文本须在帧");
        let c_combo = text_center(&shapes, "🖥 显示器 A").expect("ComboBox 文本须在帧");
        assert!(
            (c_btn - c_combo).abs() <= 1.0,
                "文本基线 y 中心须 ≤1px 对齐: {c_btn} vs {c_combo}"
            );
    }
}

#[cfg(test)]
mod r134_5_tests {
    use super::*;

    /// 口径 `sid=`，与服务端 viewer # 行 grep 锚点共用）② 本地变化沿推行
    #[test]
    fn r134_5_client_caps_lines_format_pinned() {
        assert_eq!(
            r134_5_client_caps_initial_line(3, true),
        );
        assert_eq!(
            r134_5_client_caps_initial_line(0, false),
        );
        assert_eq!(
            r134_5_client_caps_local_push_line(2, true),
        );
        assert_eq!(
            r134_5_client_caps_local_push_line(0, false),
        );
        for line in [
            r133_5_caps_initial_line(3, true),
            r134_5_client_caps_initial_line(3, true),
        ] {
            assert!(line.contains("peer caps state initial ←"), "{line}");
        }
    }

    /// ① set_sink 调用点携 reason 实参（三态齐备：attach=FocusGained /
    ///    窗存活=FocusLost / 末窗=SessionEnd）② 钩子聚合块每帧 drain 命中环
    ///    出 INFO 行 ③ 客户端 CapsState 接收臂首帧走初值行 + initial_seen 旗
    ///    ④ 客户端输入发送任务 caps tick 推行出本地变化沿行。
    #[test]
    fn r134_5_ui_wiring_check() {
        let src = include_str!("lib.rs");
        // ① set_sink reason 实参接线（生产唯一调用点）
        assert!(
            src.contains("hook.set_sink(sink_tx, sink_reason);"),
            "set_sink 调用点缺 reason 实参（DEBUG 原因行失联）"
        );
        assert!(
            src.contains("kbd_hook::SinkReason::FocusGained")
                && src.contains("kbd_hook::SinkReason::FocusLost")
                && src.contains("kbd_hook::SinkReason::SessionEnd"),
            "sink reason 三态未全接线（detach 原因判定缺臂）"
        );
        // ② 命中环 drain 接线（钩子聚合块内）
        assert!(
            src.contains("for evt in hook.drain_hit_events() {")
                && src.contains("tracing::info!(\"{}\", kbd_hook::format_hook_hit_line(&evt));"),
            "命中观察环 drain/INFO 行接线缺位（白名单命中逐击不可见）"
        );
        // ③ 客户端接收臂初值行三分（initial_seen 旗 + 初值行函数消费）
        assert!(
            src.contains("let mut r134_5_caps_initial_seen = false;")
                && src.contains("r134_5_client_caps_initial_line(session_id, caps)"),
        );
        // ④ 客户端推行变化沿行
        assert!(
            src.contains("r134_5_client_caps_local_push_line(session_id, caps)"),
            "客户端本端 caps 推行缺 INFO 行（失焦直按观测段缺失）"
        );
        // 服务端侧两行在位（核查结论：服务端不缺——防本岗误改服务端口径）
        assert!(
            src.contains("r133_5_caps_initial_line(session_id, caps)"),
        );
        assert!(
            "服务端本地推行变化沿行缺失（核查结论 = 服务端在位，若此处 RED = 回归）"
        );
    }
}

#[cfg(test)]
mod r133_5_tests {
    use super::*;

    #[test]
    fn r133_5_caps_initial_line_format_pinned() {
        assert_eq!(
            r133_5_caps_initial_line(3, true),
        );
        assert_eq!(
            r133_5_caps_initial_line(0, false),
        );
    }

    /// （Button 1:1 `into_layout_job` + 2×button_padding），钉死：
    /// ① 自然宽本参差（3 字 tab > 2 字 tab = 修前态，钉修复必要性）
    /// ② 统一宽传参后 6 pill 矩形宽全相等（双主题 × 2 帧）。宽测量 =
    /// Button 1:1 路径（`append_to` + `fonts.layout_job`）+ 2×button_padding。
    #[test]
    fn r133_5_navbar_tabs_uniform_width() {
        for theme in [Theme::LIGHT, Theme::DARK] {
            let ctx = egui::Context::default();
            for _ in 0..2 {
                let mut raw = egui::RawInput::default();
                raw.screen_rect = Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(1920.0, 1080.0),
                ));
                let _ = ctx.run(raw, |ctx| {
                    egui::TopBottomPanel::top("r133_5_nav").show(ctx, |ui| {
                        ui.horizontal(|ui| {
                            // i18n 实际值（zh）：session.tab.* + tunnel.tab。
                            let labels = [
                                "🏠 仪表盘",
                                "🌐 域名",
                                "🖥 设备",
                                "🔗 连接",
                                "🖥️ 服务器",
                                "⚙ 设置",
                            ];
                            let mut natural = Vec::new();
                            for l in &labels {
                                let mut job = egui::text::LayoutJob::default();
                                egui::RichText::new(l.to_string())
                                    .size(theme.button_size)
                                    .append_to(
                                        &mut job,
                                        ui.style(),
                                        egui::FontSelection::Style(egui::TextStyle::Button),
                                        ui.layout().vertical_align(),
                                    );
                                natural.push(ui.ctx().fonts(|f| f.layout_job(job).size().x));
                            }
                            assert!(
                                natural.iter().cloned().fold(f32::INFINITY, f32::min)
                                    < natural.iter().cloned().fold(0.0, f32::max),
                                "自然宽本应参差（3 字 tab 宽于 2 字 tab）: {natural:?}"
                            );
                            let pill_w = natural.iter().cloned().fold(0.0, f32::max)
                                + 2.0 * ui.spacing().button_padding.x;
                            let widths: Vec<f32> = labels
                                .iter()
                                .enumerate()
                                .map(|(i, l)| {
                                    selectable_pill(ui, &theme, l, i == 0, pill_w)
                                        .rect
                                        .width()
                                })
                                .collect();
                            assert!(
                                widths.iter().all(|w| (*w - pill_w).abs() < 0.01),
                                "6 tab pill 宽须全等于统一宽 {pill_w}: {widths:?}"
                            );
                        });
                    });
                });
            }
        }
    }
}

// ════════════════════════════════════════════════════════════════
// 坐标变化/强制重发点（置 None）必发；既有 60fps 节流+合并语义零回归
// ════════════════════════════════════════════════════════════════
#[cfg(test)]
mod r117_tests {
    use super::*;

    /// 同坐标连续 push 仅一次入队：首帧外发后，稳态同坐标 push 全部被
    /// 去重吞掉（pending_move 也不覆盖）——即使强制节流窗口过期，flush
    /// 也产不出任何事件（旧实现 = 每帧无条件覆盖 → 每 16ms 重发一次）。
    #[test]
    fn r117_same_coord_repush_no_requeue() {
        let (tx, mut rx) =
            tokio::sync::mpsc::unbounded_channel::<Vec<WireInputEvent>>();
        let mut q = InputCaptureQueue::new();
        q.push_move(5, 5);
        assert!(q.flush_if_due(&tx)); // 首帧（last_flush 初始已过期）→ 即发
        let b = rx.try_recv().unwrap();
        assert_eq!(b.len(), 1);
        assert!(matches!(
            &b[0],
            WireInputEvent {
                kind: InputKind::MouseMove,
                x: 5,
                y: 5,
                ..
            }
        ));
        // 稳态：同坐标连续两帧 push（旧实现 = 每帧无条件覆盖 pending）
        q.push_move(5, 5);
        q.push_move(5, 5);
        // 去重命中 → 零入队（pending_move 亦未覆盖）
        assert!(q.pending_move.is_none());
        assert!(!q.has_pending());
        // 即使强制节流窗口过期，也无事件可发
        q.last_flush = std::time::Instant::now() - INPUT_MOVE_INTERVAL;
        assert!(!q.flush_if_due(&tx));
        assert!(rx.try_recv().is_err());
    }

    /// 坐标变化通过：新坐标 ≠ 锚点 → 入队 + 锚点同帧更新，节流过期后外发。
    #[test]
    fn r117_coord_change_passes() {
        let (tx, mut rx) =
            tokio::sync::mpsc::unbounded_channel::<Vec<WireInputEvent>>();
        let mut q = InputCaptureQueue::new();
        q.push_move(5, 5);
        assert!(q.flush_if_due(&tx));
        rx.try_recv().unwrap();
        // 坐标变化 → 通过（入队 + 锚点更新）
        q.push_move(7, 7);
        assert_eq!(q.pending_move, Some((7, 7)));
        assert_eq!(q.last_sent_move, Some((7, 7)));
        q.last_flush = std::time::Instant::now() - INPUT_MOVE_INTERVAL;
        assert!(q.flush_if_due(&tx));
        let b = rx.try_recv().unwrap();
        assert_eq!(b.len(), 1);
        assert!(matches!(
            &b[0],
            WireInputEvent {
                kind: InputKind::MouseMove,
                x: 7,
                y: 7,
                ..
            }
        ));
    }

    /// 强制重发点（置 None）：会话（重新）建立 / 焦点重新获得 / 分辨率变化
    /// 把锚点置 None 后，同坐标也重发（远端光标基线已随会话/本地活动重置，
    /// 必须重锚回本机指针）。
    #[test]
    fn r117_invalidate_forces_resend_same_coord() {
        let (tx, mut rx) =
            tokio::sync::mpsc::unbounded_channel::<Vec<WireInputEvent>>();
        let mut q = InputCaptureQueue::new();
        q.push_move(5, 5);
        assert!(q.flush_if_due(&tx));
        rx.try_recv().unwrap();
        // 稳态：同坐标去重
        q.push_move(5, 5);
        assert!(q.pending_move.is_none());
        // 强制重发点 → 锚点置 None
        q.invalidate_move_dedup();
        assert!(q.last_sent_move.is_none());
        // 同坐标 (5,5) 无条件入队
        q.push_move(5, 5);
        assert_eq!(q.pending_move, Some((5, 5)));
        q.last_flush = std::time::Instant::now() - INPUT_MOVE_INTERVAL;
        assert!(q.flush_if_due(&tx));
        let b = rx.try_recv().unwrap();
        assert_eq!(b.len(), 1);
        assert!(matches!(
            &b[0],
            WireInputEvent {
                kind: InputKind::MouseMove,
                x: 5,
                y: 5,
                ..
            }
        ));
        // 重发后回到稳态去重
        q.push_move(5, 5);
        assert!(!q.has_pending());
    }

    /// 节流与去重组合语义（既有 60fps 节流 + 合并零回归）：16ms 内两帧
    /// 不同坐标 = 后者覆盖 pending（锚点随覆盖刷新），节流过期后**一次**
    /// 外发且只含最新坐标——中间帧坐标被合并吞掉（既有合并语义不变）。
    #[test]
    fn r117_throttle_coalescing_with_dedup() {
        let (tx, mut rx) =
            tokio::sync::mpsc::unbounded_channel::<Vec<WireInputEvent>>();
        let mut q = InputCaptureQueue::new();
        // m9 小修（本批，自申报同族扩展）：本例两处「<16ms 不外发」断言与
        // 点名 2 例同机制（16ms 墙钟节流窗依赖语句间墙钟间隔），同根因一
        // 并转虚拟时钟确定性时间态。
        q.use_virtual_clock();
        // 帧 1：(1,1) 无锚点 → 即发
        q.push_move(1, 1);
        assert!(q.flush_if_due(&tx));
        rx.try_recv().unwrap();
        // 帧 2（虚拟时钟未前进 <16ms）：(2,2) ≠ 锚点 → 覆盖 pending；节流中不外发
        q.push_move(2, 2);
        assert!(q.has_pending());
        assert!(!q.flush_if_due(&tx));
        // 帧 3（仍 <16ms）：(3,3) ≠ 锚点 (2,2) → 后者覆盖 pending
        q.push_move(3, 3);
        assert_eq!(q.pending_move, Some((3, 3)));
        assert!(q.flush_if_due(&tx) == false); // 节流未过期 → 仍不外发
        // 节流窗口过期 → 一次外发，且只含最新 (3,3)
        // m9 小修（本批）：虚拟时钟前进恰 16ms = 节流窗确定性过期。
        q.advance_virtual(INPUT_MOVE_INTERVAL);
        assert!(q.flush_if_due(&tx));
        let b = rx.try_recv().unwrap();
        assert_eq!(b.len(), 1);
        assert!(matches!(
            &b[0],
            WireInputEvent {
                kind: InputKind::MouseMove,
                x: 3,
                y: 3,
                ..
            }
        ));
        // 外发后稳态同坐标去重（零二次流量）
        q.push_move(3, 3);
        assert!(!q.has_pending());
    }

    /// 去重下点击 flush 顺序不变式：指针未动（去重命中）+ 点击 = 立即
    /// flush 且批次仅含点击（无移动前导）；指针移动 + 点击 = 移动仍排批次
    /// 最前（「点击前的位置必须已生效」既有顺序语义保留）。
    #[test]
    fn r117_click_flush_ordering_under_dedup() {
        let (tx, mut rx) =
            tokio::sync::mpsc::unbounded_channel::<Vec<WireInputEvent>>();
        let mut q = InputCaptureQueue::new();
        q.push_move(9, 9);
        assert!(q.flush_if_due(&tx)); // (9,9) 已发
        rx.try_recv().unwrap();
        // 指针未动（去重命中）+ 点击 → 立即 flush，批次 = 仅点击
        q.push_move(9, 9);
        q.push(WireInputEvent::mouse_button(hid_button::LEFT, 9, 9));
        assert!(q.flush_if_due(&tx));
        let b = rx.try_recv().unwrap();
        assert_eq!(b.len(), 1);
        assert!(matches!(
            &b[0],
            WireInputEvent {
                kind: InputKind::MouseButton,
                ..
            }
        ));
        // 指针移动 + 点击 → 移动在前、点击在后（顺序不变式保留）
        q.push_move(11, 11);
        q.push(WireInputEvent::mouse_button(hid_button::LEFT, 11, 11));
        assert!(q.flush_if_due(&tx));
        let b = rx.try_recv().unwrap();
        assert_eq!(b.len(), 2);
        assert!(matches!(
            &b[0],
            WireInputEvent {
                kind: InputKind::MouseMove,
                x: 11,
                y: 11,
                ..
            }
        ));
        assert!(matches!(
            &b[1],
            WireInputEvent {
                kind: InputKind::MouseButton,
                ..
            }
        ));
    }
}

// ════════════════════════════════════════════════════════════════
// 定值钉死 + 8ms 网格虚拟时钟 flush 行为 + 本地段观测行/量测纯函数
// 格式钉死 + PM 附加①②行格式钉死
// ════════════════════════════════════════════════════════════════
#[cfg(test)]
mod r137_7_tests {
    use super::*;

    /// 节流窗定值钉死：16ms→8ms（9ms 本地段口径的主导可控项收口点；
    /// 去重零 wire 均系于本值）。
    #[test]
    fn r137_7_input_move_interval_8ms_pinned() {
        assert_eq!(
            INPUT_MOVE_INTERVAL,
            std::time::Duration::from_millis(8),
        );
        // 预算常量同源钉死（9ms 口径 = 帧间隔上界 + 入队等待 + 2ms 发送预算）。
        assert_eq!(R137_7_LOCAL_SEG_BUDGET_MS, 9);
        assert_eq!(R137_7_SEND_TASK_BUDGET_MS, 2);
    }

    /// 8ms 网格 flush 行为（虚拟时钟确定性时间态）：新坐标 7ms 时点仍在
    /// 节流窗内不外发、恰 8ms 到期即发（`<` 严格小于判定 = 恰 8ms due）。
    /// ≤125Hz 鼠标（事件间隔 ≥8ms）每事件各随其帧外发 = 节流不绑定的
    #[test]
    fn r137_7_move_flush_8ms_grid_virtual() {
        let (tx, mut rx) =
            tokio::sync::mpsc::unbounded_channel::<Vec<WireInputEvent>>();
        let mut q = InputCaptureQueue::new();
        q.use_virtual_clock();
        q.push_move(1, 1);
        assert!(q.flush_if_due(&tx), "首移动立即发送（last_flush 初始过期）");
        rx.try_recv().unwrap();
        // 新坐标 ≠ 锚点 → 入队；7ms < 8ms → 节流不外发。
        q.push_move(2, 2);
        q.advance_virtual(std::time::Duration::from_millis(7));
        assert!(!q.flush_if_due(&tx), "7ms 仍在 8ms 窗内 = 节流");
        assert!(q.has_pending());
        // 恰 8ms（累计 7+1）→ 窗到期 = 外发且只含最新坐标。
        q.advance_virtual(std::time::Duration::from_millis(1));
        assert!(q.flush_if_due(&tx), "恰 8ms = 节流窗 due");
        let b = rx.try_recv().unwrap();
        assert_eq!(b.len(), 1);
        assert!(matches!(
            &b[0],
            WireInputEvent {
                kind: InputKind::MouseMove,
                x: 2,
                y: 2,
                ..
            }
        ));
    }

    /// bound ≤ budget，含恰 9ms 边界格）。
    #[test]
    fn r137_7_local_seg_line_format() {
        // bound = gap + q + 2ms 发送预算：4+2+2 = 8 ≤ 9 → ok=1。
        assert_eq!(
            r137_7_local_seg_line(7, 4, 2),
        );
        // 8+2+2 = 12 > 9 → ok=0。
        assert_eq!(
            r137_7_local_seg_line(7, 8, 2),
        );
        // 恰 9ms 边界：bound = 9 ≤ 9 → ok=1（「给 9 毫秒」= ≤9 达成）。
        assert_eq!(
            r137_7_local_seg_line(1, 7, 0),
        );
    }

    /// srv-in 行移动尾段格式钉死（PM 附加①：x/y 坐标 + move_guard 判定
    /// 三态 + 无观测 `-` + 非移动事件空串〔原行逐字节不变〕）。
    #[test]
    fn r137_7_srv_in_move_extra_format() {
        use kirin_desk_input::injector::MoveGuardVerdict as G;
        assert_eq!(r137_7_srv_in_move_extra(None, None), "");
        // 移动事件 + 无守卫观测（注入器不可用 / dst(0,0) 早退）：wire 坐标 g=-。
        assert_eq!(r137_7_srv_in_move_extra(Some((5, 6)), None), " x=5 y=6 g=-");
        // 三态判定字面钉死。
        assert_eq!(
            r137_7_srv_in_move_extra(Some((5, 6)), Some(G::Inject)),
            " x=5 y=6 g=inject"
        );
        assert_eq!(
            r137_7_srv_in_move_extra(Some((5, 6)), Some(G::DroppedDedup)),
            " x=5 y=6 g=drop_dedup"
        );
        assert_eq!(
            r137_7_srv_in_move_extra(Some((5, 6)), Some(G::DroppedSuppressed)),
            " x=5 y=6 g=drop_suppress"
        );
    }

    /// 本地段上界纯函数矩阵（gap + q + 2ms 发送预算；saturating 防溢出）。
    #[test]
    fn r137_7_local_seg_bound_matrix() {
        assert_eq!(r137_7_local_seg_bound_ms(0, 0), 2, "零帧间隔零入队 = 仅发送预算");
        assert_eq!(r137_7_local_seg_bound_ms(4, 2), 8, "4+2+2 = 8");
        assert_eq!(r137_7_local_seg_bound_ms(7, 0), 9, "恰 9ms 边界（≤9 达成）");
        assert_eq!(r137_7_local_seg_bound_ms(8, 2), 12, "8+2+2 = 12 = 超预算 3ms（ok=0 侧）");
        assert_eq!(
            r137_7_local_seg_bound_ms(u64::MAX, 1),
            u64::MAX,
            "饱和加法不溢出"
        );
    }
}

// ════════════════════════════════════════════════════════════════
// 自愈强制重发全退役）：本地活动 → 注入挂起且零拉回注入（客户端侧
// 稳态零 wire）/ 本地静止超时 → 注入恢复（客户端下一次移动按绝对
// 坐标自然就位）/ 客户端移动 → 绝对坐标正常注入 / 去重零回归；
// 防回潮断言 = 任何路径不得产生「向客户端锚点」的校正注入
// （抑制窗挂起/恢复 + 转换观测）见 input/src/injector.rs r141_3_v2_*
// ════════════════════════════════════════════════════════════════
#[cfg(test)]
mod r141_3_tests {
    use super::*;

    /// v2-① 本地活动 → 注入挂起且**零拉回注入**（客户端侧）：客户端指针
    /// 稳态（去重锚点已建）后，长时静止（远超旧自愈 500ms 周期——对应对
    /// 被控端本地活动重锚基线后的等待期）重复同坐标 push 必须**全部**
    /// 被去重：零 wire、零强制重发（旧矩阵的「自愈到期判定 → 强制重发」
    /// 拉回行为不得回潮——拉回把远端光标拽回客户端锚点 = 用户观测的
    /// 「跳变」直接源，已按裁定整体移除）。
    #[test]
    fn r141_3_v2_steady_state_zero_yankback() {
        let (tx, mut rx) =
            tokio::sync::mpsc::unbounded_channel::<Vec<WireInputEvent>>();
        let mut q = InputCaptureQueue::new();
        q.use_virtual_clock();
        // 客户端指针静止 (100,100)：首移动外发，建去重锚点。
        q.push_move(100, 100);
        assert!(q.flush_if_due(&tx));
        assert_eq!(rx.try_recv().unwrap().len(), 1);
        // 长时静止（≥500ms × 20 = 10s，远超旧自愈 500ms 周期）：
        // 重复同坐标 push = 全去重，队列恒空。
        for _ in 0..20 {
            q.advance_virtual(std::time::Duration::from_millis(500));
            q.push_move(100, 100);
            assert!(!q.has_pending(), "稳态同坐标必须去重（零 wire、零拉回）");
        }
        // 零 wire 防回潮：通道无任何批次（若拉回回潮，此处将出现强制
        // 重发批次）。
        assert!(
            rx.try_recv().is_err(),
            "长稳态零外发（任何向客户端锚点的校正注入不得存在）"
        );
        // flush 路径亦无可发（无待发批次）。
        q.advance_virtual(std::time::Duration::from_millis(64));
        assert!(!q.flush_if_due(&tx));
        assert!(rx.try_recv().is_err());
    }

    /// v2-② 本地静止超时 → 注入恢复 = 客户端移动按**绝对坐标**正常注入：
    /// 静止期后客户端指针变化 → 该移动入队并随 flush 外发，wire 坐标 =
    /// 客户端绝对坐标（自然就位；无向旧锚点的校正、无拉回延迟）。
    #[test]
    fn r141_3_v2_client_move_absolute_injection() {
        let (tx, mut rx) =
            tokio::sync::mpsc::unbounded_channel::<Vec<WireInputEvent>>();
        let mut q = InputCaptureQueue::new();
        q.use_virtual_clock();
        q.push_move(100, 100);
        assert!(q.flush_if_due(&tx));
        rx.try_recv().unwrap();
        // 长时静止（越过旧自愈周期 = 防回潮基线）。
        q.advance_virtual(std::time::Duration::from_millis(600));
        // 客户端移动 (320,200)：绝对坐标原样入队、外发。
        q.push_move(320, 200);
        assert!(q.has_pending());
        assert!(q.flush_if_due(&tx));
        let b = rx.try_recv().unwrap();
        assert_eq!(b.len(), 1);
        assert!(
            matches!(
                &b[0],
                WireInputEvent {
                    kind: InputKind::MouseMove,
                    x: 320,
                    y: 200,
                    ..
                }
            ),
            "wire 坐标 = 客户端绝对坐标（自然就位，无校正）"
        );
        // 回稳态：不得再外发旧锚点 (100,100)（拉回方向不存在）。
        q.push_move(320, 200);
        assert!(!q.has_pending());
        assert!(rx.try_recv().is_err());
    }

    #[test]
    fn r141_3_v2_dedup_zero_regression() {
        let (tx, mut rx) =
            tokio::sync::mpsc::unbounded_channel::<Vec<WireInputEvent>>();
        let mut q = InputCaptureQueue::new();
        q.use_virtual_clock();
        q.push_move(7, 8);
        assert!(q.flush_if_due(&tx));
        rx.try_recv().unwrap();
        // 同坐标 → 去重（零 wire）。
        q.push_move(7, 8);
        assert!(!q.has_pending());
        q.push_move(7, 9);
        assert!(q.has_pending());
        q.advance_virtual(std::time::Duration::from_millis(8));
        assert!(q.flush_if_due(&tx));
        let b = rx.try_recv().unwrap();
        assert_eq!(b.len(), 1);
        assert!(
            matches!(
                &b[0],
                WireInputEvent {
                    kind: InputKind::MouseMove,
                    x: 7,
                    y: 9,
                    ..
                }
            )
        );
    }

    /// `invalidate_move_dedup`（会话（重新）建立 / 焦点重新获得 / 分辨率
    #[test]
    fn r141_3_v2_invalidate_forced_resend_point_preserved() {
        let (tx, mut rx) =
            tokio::sync::mpsc::unbounded_channel::<Vec<WireInputEvent>>();
        let mut q = InputCaptureQueue::new();
        q.use_virtual_clock();
        q.push_move(50, 60);
        assert!(q.flush_if_due(&tx));
        rx.try_recv().unwrap();
        // 失效前同坐标 push = 去重。
        q.push_move(50, 60);
        assert!(!q.has_pending());
        q.invalidate_move_dedup();
        q.push_move(50, 60);
        assert_eq!(q.pending_move, Some((50, 60)));
        q.advance_virtual(std::time::Duration::from_millis(8));
        assert!(q.flush_if_due(&tx));
        let b = rx.try_recv().unwrap();
        assert_eq!(b.len(), 1);
    }

    /// v2-⑤ 防回潮断言（任何路径不得产生「向客户端锚点」的校正注入）：
    /// self-heal 观测行函数 / 行字面）源码零残留——拼接构造防自命中
    #[test]
    fn r141_3_v2_yankback_symbols_gone() {
        let src =
            std::fs::read_to_string(env!("CARGO_MANIFEST_DIR").to_string() + "/src/lib.rs")
                .expect("读 lib.rs");
        for sym in [
            ["self", "_heal_due"],
            ["force_re", "send_move"],
            ["move_self_", "heal_due"],
            ["MOVE_SELF_", "HEAL_MS"],
            ["last_move_", "sent_at"],
            ["r137_7_self_", "heal_line"],
        ] {
            let needle = sym.concat();
        }
    }

    /// （被控端注入守卫产生，服务端 Input 臂输出）。
    #[test]
    fn r141_3_local_priority_line_format() {
        assert_eq!(
            r141_3_local_priority_line(3, "suspended", 120, 80),
        );
        assert_eq!(
            r141_3_local_priority_line(7, "resumed", 320, 200),
        );
    }
}

// ════════════════════════════════════════════════════════════════
// ════════════════════════════════════════════════════════════════
#[cfg(test)]
mod r74g_tests {
    use super::*;
    use kirin_desk_core::crypto::aead::AeadCipher;
    use kirin_desk_core::crypto::handshake::SecureChannel;
    use std::time::Duration;

    /// 测试基建：本地 TCP 回环 + dummy 密钥 SecureChannel 对（每消息随机
    /// nonce → 同密钥双向收发可用；只关心帧边界/看门狗时序，不关心密钥
    /// 正确性——与 server_media r673/r74g 测试同口径）。
    async fn loopback_pair() -> (
        SecureChannelReceiver,
        Arc<tokio::sync::Mutex<SecureChannelSender>>,
    ) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let client_sock = tokio::net::TcpStream::connect(addr).await.unwrap();
        let (server_sock, _) = listener.accept().await.unwrap();
        let mk = |stream: tokio::net::TcpStream| SecureChannel {
            stream,
            cipher: AeadCipher::new(&[0u8; 32]),
            peer_id: "r74g".to_string(),
            peer_domain: String::new(),
            peer_device_type: "desktop".to_string(),
            selected_codec: String::new(),
        };
        let (c_reader, _c_writer) = mk(client_sock).into_split();
        let (_s_reader, s_writer) = mk(server_sock).into_split();
        (
            SecureChannelReceiver::new(c_reader),
            Arc::new(tokio::sync::Mutex::new(SecureChannelSender::new(s_writer))),
        )
    }

    fn small_video_pkt(seq: u64) -> EncodedPacket {
        EncodedPacket {
            ts: Timestamp::now(),
            kind: PacketKind::Video,
            data: seq.to_be_bytes().to_vec(),
            is_key: false,
        }
    }

    /// 加速回归）。断言触发时刻 ∈ [300ms, 1s]（不早不迟）。
    #[tokio::test]
    async fn r74g_watchdog_fires_after_injected_threshold() {
        let (mut rx, _sender) = loopback_pair().await;
        assert!(rx.last_recv_any().is_none(), "首收前无入包时间戳");
        let start = std::time::Instant::now();
        let res = recv_tagged_with_watchdog(&mut rx, Duration::from_millis(300)).await;
        let elapsed = start.elapsed();
        assert!(
            matches!(res, Err(RecvWatchdogError::IdleTimeout)),
            "应 IdleTimeout，实际 {res:?}"
        );
        assert!(elapsed >= Duration::from_millis(300), "触发过早: {elapsed:?}");
        assert!(elapsed <= Duration::from_millis(1000), "触发过迟: {elapsed:?}");
    }

    /// 300ms——保持生产 10s 与 3s 心跳 3:1 余量比；帧流 30ms/帧——10×
    /// 对应生产 300ms/帧≈3.3fps 最低帧率；3s 真实 = 30s 模拟）：全程零
    /// 误杀；帧流**停止**后看门狗按注入阈值再触发（空档感知恢复）。
    #[tokio::test]
    async fn r74g_sustained_flow_no_false_kill_then_idle_fires() {
        let (mut rx, sender) = loopback_pair().await;
        let watchdog = Duration::from_millis(300); // 注入（生产 10s）
        let frame_iv = Duration::from_millis(30); // 10× 加速（生产等效 300ms/帧）
        let run = Duration::from_secs(3); // 30s 模拟

        // 发送侧：持续帧流 3s（sender 本体留在测试作用域——流停 ≠ 断链，
        // 泵任务结束不触发 EOF，才能单独验证「流停后的空闲看门狗」）。
        let sender_pump = sender.clone();
        let pump = tokio::spawn(async move {
            let until = std::time::Instant::now() + run;
            let mut seq = 0u64;
            while std::time::Instant::now() < until {
                if sender_pump
                    .lock()
                    .await
                    .send_packets(&[small_video_pkt(seq)])
                    .await
                    .is_err()
                {
                    break;
                }
                seq += 1;
                tokio::time::sleep(frame_iv).await;
            }
        });

        // 接收侧：看门狗全程运行——持续帧流期间绝不得 IdleTimeout（误杀）。
        // 窗口取 run-350ms：与泵任务结束留足余量（泵起/接收起有数十 ms
        // 偏斜），避免「流已停但仍在流窗断言内」的边界竞态。
        let t0 = std::time::Instant::now();
        let flow_until = run - Duration::from_millis(350);
        let mut got = 0u32;
        while t0.elapsed() < flow_until {
            match recv_tagged_with_watchdog(&mut rx, watchdog).await {
                Ok((ChannelTag::Video, _h, _p)) => got += 1,
                Ok((tag, _h, _p)) => panic!("帧流期不应出现其他 tag: {tag:?}"),
                Err(RecvWatchdogError::IdleTimeout) => panic!(
                    "持续帧流被误杀（{got} 包 @ {:?}）",
                    t0.elapsed()
                ),
                Err(RecvWatchdogError::RecvError(e)) => {
                    panic!("帧流期读错（sender 未断）: {e}")
                }
            }
        }
        assert!(
            got >= 40,
            "30ms/帧 × 2.65s 应收约 88 包，实际 {got}——帧流异常"
        );
        pump.await.unwrap();

        // 排干飞行中残余帧（泵结束晚于接收窗口，尾部 ~10 帧在 TCP 缓冲）。
        loop {
            match tokio::time::timeout(Duration::from_millis(50), rx.recv_tagged()).await {
                Ok(Ok((ChannelTag::Video, _, _))) => continue,
                Ok(Ok((tag, _, _))) => panic!("排干期出现非视频包: {tag:?}"),
                Ok(Err(e)) => panic!("排干期读错: {e}"),
                Err(_) => break, // 50ms 无新包 = 排干完毕
            }
        }
        let last = rx.last_recv_any().expect("排干后必有最后入包时间戳");

        // 帧流停止（sender 保留）→ 空档看门狗按注入阈值再触发：
        // 触发时刻 = 最后入包 + watchdog（10s±1s 语义的注入阈值版）。
        let res2 = recv_tagged_with_watchdog(&mut rx, watchdog).await;
        assert!(
            matches!(res2, Err(RecvWatchdogError::IdleTimeout)),
            "流停后应 IdleTimeout，实际 {res2:?}"
        );
        let since_last = last.elapsed();
        assert!(
            since_last >= watchdog - Duration::from_millis(20)
                && since_last <= watchdog + Duration::from_millis(700),
            "流停后触发时刻偏离注入阈值（距最后入包）: {since_last:?}"
        );
    }
}

// ════════════════════════════════════════════════════════════════
