#[cfg(test)]
mod r137_1_tests {
    use super::*;
    use kirin_desk_core::crypto::handshake::{PROTO_VER_LEGACY, PROTOCOL_VERSION};

    /// 判定矩阵：`None`（未通告）= fail-closed OFF；`Some(true)` = 对端 ON
    /// 放行；`Some(false)` = 对端 OFF 拒绝（安全红线⑤，不静默放行）。
    #[test]
    fn r137_1_peer_clipboard_gate_matrix() {
        assert!(!r137_1_peer_clipboard_gate(None), "未通告 = fail-closed OFF");
        assert!(r137_1_peer_clipboard_gate(Some(true)), "对端 ON = 放行");
        assert!(!r137_1_peer_clipboard_gate(Some(false)), "对端 OFF = 拒绝");
    }

    /// 行格式零改仅态值域改）。
    #[test]
    fn r137_1_peer_gate_state_str_values() {
        assert_eq!(r137_1_peer_gate_state_str(Some(true)), "peer_on");
        assert_eq!(r137_1_peer_gate_state_str(Some(false)), "peer_off");
        assert_eq!(r137_1_peer_gate_state_str(None), "peer_unknown_fail_closed");
    }

    #[test]
    fn r137_1_line_formats_pinned() {
        assert_eq!(
            r137_1_ctl_consent_send_line(9, true, false),
        );
        assert_eq!(
            r137_1_ctl_consent_recv_line(9, true, false),
        );
        assert_eq!(
            r137_1_file_consent_send_line(false, true),
        );
        assert_eq!(
            r137_1_file_consent_recv_line(false, true),
        );
    }

    /// per-会话槽 set/get/clear 回环（会话判死统一出口清槽防跨会话陈旧值；
    /// 不同会话 ID 隔离）。
    #[test]
    fn r137_1_slot_roundtrip() {
        peer_consent_clear(0xA1);
        assert_eq!(peer_consent_get(0xA1), None, "初值 = 未通告");
        peer_consent_set(0xA1, true, false);
        assert_eq!(peer_consent_get(0xA1), Some((true, false)));
        peer_consent_set(0xA1, false, true);
        assert_eq!(peer_consent_get(0xA1), Some((false, true)), "覆写语义");
        assert_eq!(peer_consent_get(0xB2), None, "不同会话槽隔离");
        peer_consent_clear(0xA1);
        assert_eq!(peer_consent_get(0xA1), None, "清槽 = 未通告");
    }

    /// v3 对端 → 首 `on_tick` 发 `FileOp::PeerConsent` 帧（载荷 = 构造
    /// 零重发；legacy-0 对端 = 零发送（`send_frame` 版本门控单点，
    /// fail-closed——legacy 端收不到 = 其侧对端态未知 = 对端 fail-closed）。
    #[tokio::test]
    async fn r137_1_file_session_announce_loopback() {
        // v3 对照组：帧发出 + 载荷 = consent 快照。
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        let mut ft = FileSession::new_shell(
            tx,
            PROTOCOL_VERSION,
            server_file_panel_state(),
            "r137_1-salt".into(),
            std::env::temp_dir().join(format!("kirin_r137_1_store_{}", std::process::id())),
            std::env::temp_dir().join(format!("kirin_r137_1_dl_{}", std::process::id())),
            DEFAULT_MAX_FILE_SIZE,
            None,
            SessionQuota::new(0, 0),
            FsPolicy::headless(&[], &[]),
            None,
            FsRouter::new(),
        )
        // with_consent_switches(file_transfer, clipboard)。
        .with_consent_switches(true, false)
        .with_announce_peer_consent();
        ft.on_tick().await;
        let bytes = rx.try_recv().expect("v3 对端应收到通告帧");
        let frame = FileTransferFrame::decode(&bytes).unwrap();
        assert_eq!(frame.op, FileOp::PeerConsent);
        let payload: PeerConsentPayload = bincode::deserialize(&frame.data).unwrap();
        assert_eq!(
            payload,
            PeerConsentPayload {
                clipboard_allowed: false,
                file_transfer_allowed: true,
            }
        );
        // 一次性（零重发）。
        ft.on_tick().await;
        assert!(rx.try_recv().is_err(), "通告帧一次性，不得重发");

        // legacy-0 实验组：零发送（版本门控 fail-closed）。
        let (tx0, mut rx0) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        let mut ft0 = FileSession::new_shell(
            tx0,
            PROTO_VER_LEGACY,
            server_file_panel_state(),
            "r137_1-salt".into(),
            std::env::temp_dir().join(format!("kirin_r137_1_store_{}", std::process::id())),
            std::env::temp_dir().join(format!("kirin_r137_1_dl_{}", std::process::id())),
            DEFAULT_MAX_FILE_SIZE,
            None,
            SessionQuota::new(0, 0),
            FsPolicy::headless(&[], &[]),
            None,
            FsRouter::new(),
        )
        .with_consent_switches(true, true)
        .with_announce_peer_consent();
        ft0.on_tick().await;
        assert!(rx0.try_recv().is_err(), "legacy-0 对端通告帧必须零发送");
    }
}


#[cfg(test)]
mod r74d_tests {
    use super::*;
    use chrono::Utc;

    fn sample_device(nickname: &str, domain: &str, device_type: &str) -> SavedDevice {
        SavedDevice {
            // IP 模式展示路径（若落 Unknown 会因 64 位 id 触发 ID 路由回退）。
            id: "a".repeat(64),
            nickname: nickname.into(),
            remark: String::new(),
            challenge: String::new(),
            ipv6: "240e:1234:5678:9::1".into(),
            port: 61000,
            pubkey: "c2VjcmV0".into(),
            device_type: device_type.into(),
            last_seen: Utc::now(),
            domain: domain.into(),
            sort_order: 0,
            mode: DeviceConnMode::Ip,
            os_type: String::new(),
        }
    }

    #[test]
    fn truncate_chars_short_unchanged() {
        assert_eq!(truncate_chars("abc", 5), ("abc".to_string(), false));
        assert_eq!(truncate_chars("abcdef", 6), ("abcdef".to_string(), false));
    }

    #[test]
    fn truncate_chars_long_cut_with_ellipsis() {
        let (s, cut) = truncate_chars("abcdef", 4);
        assert_eq!(s, "abc…");
        assert!(cut);
        assert_eq!(s.chars().count(), 4);
    }

    #[test]
    fn truncate_chars_cjk_char_safe() {
        // CJK 按 char（非字节）截断，不破坏字符边界。
        let (s, cut) = truncate_chars("麒麟桌面测试", 3);
        assert_eq!(s, "麒麟…");
        assert!(cut);
        assert_eq!(truncate_chars("", 5), (String::new(), false));
        // max=0 → 空串 + 截断标记（非空输入）。
        assert_eq!(truncate_chars("x", 0), (String::new(), true));
    }

    #[test]
    fn device_row_domain_device_server_kind() {
        let d = sample_device("办公机", "office.example.com", "server");
        let r = device_row(&d);
        assert_eq!(r.name, "办公机");
        assert_eq!(r.name_tip, "办公机");
        assert_eq!(r.addr, "office.example.com");
        assert_eq!(r.addr_full, "office.example.com");
        assert!(r.kind_server);
        assert!(!r.last_seen.is_empty());
    }

    #[test]
    fn device_row_ipv6_fallback_and_id_name() {
        let d = sample_device("", "", "desktop");
        let r = device_row(&d);
        // 昵称空 → 回退设备 ID（64 位 → 截断至 DEVICE_NAME_MAX_CHARS）。
        let expect_name: String = "a".repeat(DEVICE_NAME_MAX_CHARS - 1);
        assert_eq!(r.name, format!("{expect_name}…"));
        assert_eq!(r.addr, "[240e:1234:5678:9::1]:61000");
        assert!(!r.kind_server);
        assert_eq!(r.name_tip, "a".repeat(64));
    }

    #[test]
    fn device_row_truncates_long_addr_and_remark_tip() {
        let mut d = sample_device("n", &"x".repeat(50), "desktop");
        d.remark = "财务".into();
        let r = device_row(&d);
        // 长地址截断（末字符省略号；长度 = 上限）。
        assert!(r.addr.ends_with('…'));
        assert_eq!(r.addr.chars().count(), DEVICE_ADDR_MAX_CHARS);
        assert_eq!(r.addr_full, "x".repeat(50));
        // 即展示名 → 悬浮提示不重复拼接；昵称「n」仅留存储/表单面。
        assert_eq!(r.name, "财务");
        assert_eq!(r.name_tip, "财务");
        assert!(!r.name_tip.contains("…"));
    }

    #[test]
    fn device_row_constants_sane() {
        // 截断上限须大于 1（max-1 取前缀逻辑边界）。
        assert!(DEVICE_NAME_MAX_CHARS > 1);
        assert!(DEVICE_ADDR_MAX_CHARS > 1);
    }
}


#[cfg(test)]
mod r86u_tests {
    use super::*;
    use chrono::Utc;

    fn device_with(id: &str, nickname: &str, remark: &str) -> SavedDevice {
        SavedDevice {
            id: id.to_string(),
            nickname: nickname.into(),
            remark: remark.into(),
            challenge: String::new(),
            ipv6: "240e:1234:5678:9::1".into(),
            port: 61000,
            pubkey: "c2VjcmV0".into(),
            device_type: "desktop".into(),
            last_seen: Utc::now(),
            domain: String::new(),
            sort_order: 0,
            mode: DeviceConnMode::Id,
            os_type: String::new(),
        }
    }

    /// ② 展示口径（可测纯逻辑部分）：`device_display_name` 更严判据三分支。
    #[test]
    fn r86u_display_name_criterion() {
        let id = "b".repeat(79);
        // nickname 非空且 != id → 昵称（trim 后）。
        assert_eq!(
            device_display_name(&device_with(&id, " Office PC ", "")),
            "Office PC"
        );
        // nickname == id（自动保存口径，历史上恒如此）→ 回落（无备注 → id）。
        assert_eq!(device_display_name(&device_with(&id, &id, "")), id);
        // nickname 空 → 回落（无备注 → id）。
        assert_eq!(device_display_name(&device_with(&id, "", "")), id);
        // nickname 空 + 备注非空 → 备注名优先于设备 ID（用户定案）。
        assert_eq!(
            device_display_name(&device_with(&id, "", " 办公室机器 ")),
            "办公室机器"
        );
        // nickname == id + 备注非空 → 备注名优先于设备 ID（用户原话场景）。
        assert_eq!(
            device_display_name(&device_with(&id, &id, "办公室机器")),
            "办公室机器"
        );
    }

    /// ② 展示口径：`device_row` 集成（名称回落/备注优先 + 悬浮提示不重复）。
    #[test]
    fn r86u_device_row_remark_priority_and_id_fallback() {
        let id = "c".repeat(79);
        // nickname == id + 备注 → 名称 = 备注；悬浮提示不重复拼「备注（备注）」。
        let r = device_row(&device_with(&id, &id, "办公室机器"));
        assert_eq!(r.name, "办公室机器");
        assert_eq!(r.name_tip, "办公室机器");
        // 随口径反转更新）；备注名即展示名 → 悬浮提示不重复拼接（既有
        let r2 = device_row(&device_with(&id, "财务机", "办公室机器"));
        assert_eq!(r2.name, "办公室机器");
        assert_eq!(r2.name_tip, "办公室机器");
        // nickname 空/==id 且无备注 → 设备 ID（79 字符 → 截断至上限 + 省略号）。
        let r3 = device_row(&device_with(&id, &id, ""));
        assert!(r3.name.ends_with('…'));
        assert_eq!(r3.name.chars().count(), DEVICE_NAME_MAX_CHARS);
        assert!(r3.name.starts_with(&"c".repeat(5)));
    }
}


#[cfg(test)]
mod r137_10_tests {
    use super::*;
    use chrono::Utc;

    fn dev10(id: &str, nickname: &str, remark: &str, mode: DeviceConnMode) -> SavedDevice {
        SavedDevice {
            id: id.to_string(),
            nickname: nickname.into(),
            remark: remark.into(),
            challenge: String::new(),
            ipv6: "240e:1234:5678:9::2".into(),
            port: 61001,
            pubkey: "c2VjcmV0".into(),
            device_type: "desktop".into(),
            last_seen: Utc::now(),
            domain: String::new(),
            sort_order: 0,
            mode,
            os_type: String::new(),
        }
    }

    /// remark>nickname>id；用户第五轮第 14 项「备注名没有正常优先展示」
    /// = 断点 a 形态：nickname 槽被机器形态预填值占据压制备注名）。
    #[test]
    fn r137_10_display_name_remark_priority_matrix() {
        let id = "d".repeat(79);
        // ① 有效 nickname（!= id）+ 备注非空 → **备注名**（本卡反转点）。
        assert_eq!(
            device_display_name(&dev10(&id, "xk31fengmai", "机房一号机", DeviceConnMode::Id)),
            "机房一号机"
        );
        // ② 有效 nickname + 备注纯空白 → 昵称（空白备注 = 未设置）。
        assert_eq!(
            device_display_name(&dev10(&id, "xk31fengmai", "   ", DeviceConnMode::Id)),
            "xk31fengmai"
        );
        // ③ 备注首尾空白 → trim 后展示。
        assert_eq!(
            device_display_name(&dev10(&id, "xk31fengmai", " 机房一号机 ", DeviceConnMode::Id)),
            "机房一号机"
        );
        // ④ 有效 nickname + 备注空 → 昵称（既有回退零回归）。
        assert_eq!(
            device_display_name(&dev10(&id, "xk31fengmai", "", DeviceConnMode::Id)),
            "xk31fengmai"
        );
        // ⑤ nickname == id（自动保存残留）+ 备注非空 → 备注名。
        assert_eq!(
            device_display_name(&dev10(&id, &id, "机房一号机", DeviceConnMode::Id)),
            "机房一号机"
        );
        // ⑥ 双空 → 设备 ID（最终回退零回归）。
        assert_eq!(device_display_name(&dev10(&id, "", "", DeviceConnMode::Id)), id);
        // ⑦ IP 模式凭据形态（nickname == id = server_id 握手凭据，值零触碰）
        //    + 备注非空 → 展示备注名（仅读取展示，凭据发送链零变化）。
        assert_eq!(
            device_display_name(&dev10("srv-cred-01", "srv-cred-01", "凭据机备注", DeviceConnMode::Ip)),
            "凭据机备注"
        );
    }

    /// ①+同步：连接下拉 `id_history_entries` 与设备页同一口径（收敛调
    /// `device_display_name` 后两处逐位一致；无可用名称 → 短 ID 标签回退
    /// 保留——79 字符指纹不整串入下拉）。
    #[test]
    fn r137_10_id_history_remark_priority_in_sync() {
        let fp: String = "e".repeat(64);
        // 三条目同 last_seen（排序键同值 = 输入序稳定；本测试按 id 查断言）。
        let t0 = Utc::now();
        let dev_rmk = {
            let mut d = dev10(&fp, "xk31fengmai", "机房一号机", DeviceConnMode::Id);
            d.last_seen = t0;
            d
        };
        let fp2: String = "f".repeat(64);
        let dev_nick = {
            let mut d = dev10(&fp2, "peer-nick", "", DeviceConnMode::Id);
            d.last_seen = t0;
            d
        };
        let fp3: String = "a1".repeat(32);
        let dev_bare = {
            let mut d = dev10(&fp3, "", "", DeviceConnMode::Id);
            d.last_seen = t0;
            d
        };
        let history = id_history_entries(&[dev_rmk, dev_nick, dev_bare], &[]);
        assert_eq!(history.len(), 3);
        // 备注名条目 → 下拉 label = 备注名（与设备页 device_row 同口径）。
        let e_rmk = history.iter().find(|h| h.device_id == fp).unwrap();
        assert_eq!(e_rmk.label, "机房一号机");
        // 无备注 → 昵称（零回归）。
        let e_nick = history.iter().find(|h| h.device_id == fp2).unwrap();
        assert_eq!(e_nick.label, "peer-nick");
        // 双空 → 短 ID 标签（前 8 hex + …，整串指纹不入下拉 = 既有回退保留）。
        let e_bare = history.iter().find(|h| h.device_id == fp3).unwrap();
        assert_eq!(e_bare.label, short_id_label(&fp3));
        assert!(e_bare.label.ends_with('…'));
    }

    /// headless 生产渲染 smoke：设备页 `show_devices` 以 CJK 备注名/机器形态
    /// 昵称/79 字符 ID 三类合成条目实跑一帧（egui 陷阱家族防回潮——行高/
    /// 截断/ScrollArea 无 INFINITY 溢出；无输入 → 零按钮副作用）。
    #[test]
    fn r137_10_device_page_headless_render_smoke() {
        let mut app = KirinDeskApp::default();
        let fp: String = "9".repeat(64);
        let mut d1 = dev10(&fp, "xk31fengmai", "机房一号机", DeviceConnMode::Id);
        d1.device_type = "server".into(); // 服务端徽标臂
        let d2 = dev10("HD-46AA6109", "peer-nick", "", DeviceConnMode::Id);
        let d3 = dev10(&"b7".repeat(32), "", "", DeviceConnMode::Id); // 裸 ID 截断臂
        app.devices = vec![d1, d2, d3];

        let ctx = egui::Context::default();
        let mut raw = egui::RawInput::default();
        raw.screen_rect = Some(egui::Rect::from_min_size(
            egui::Pos2::ZERO,
            egui::vec2(520.0, 420.0),
        ));
        let mut cursor_end: Option<f32> = None;
        let _ = ctx.run(raw, |ctx| {
            let theme = &crate::theme::Theme::LIGHT;
            egui::Area::new(egui::Id::new("r137_10_devices_probe"))
                .order(egui::Order::Foreground)
                .anchor(egui::Align2::LEFT_TOP, [0.0, 0.0])
                .show(ctx, |ui| {
                    ui.set_min_size(egui::vec2(520.0, 420.0));
                    app.show_devices(ui, theme);
                    cursor_end = Some(ui.cursor().min.y);
                });
        });
        let end = cursor_end.expect("probe 帧完成");
        assert!(
            end.is_finite() && end <= 420.0 + 1e-3,
            "设备页三行渲染后光标纵坐标有限且不越屏（零 INFINITY/溢出）: {end}"
        );
    }

    /// 六面板——名称槽宽度 = **`device_row()`/旧口径实际输出字符串的 char
    /// 数 × 12px**（数据源 = 钉死串，非装饰）；徽标 = 服务端蓝/桌面灰定色块。
    /// 定量断言：① 备注条目修后名称槽宽（5 char）< 修前（11 char）= 备注名
    /// 取代机器形态昵称入展示位；② 无备注条目修前=修后（零回归）；③ 裸 ID
    /// 条目修前=修后=24 char 截断（零回归）；④ 徽标两臂在位且定色。
    #[test]
    fn r137_10_device_row_remark_priority_probe_screenshot() {
        const W: u32 = 400;
        const H: u32 = 96;
        const CHAR_W: u32 = 12;
        const NAME_X: u32 = 12;
        const ROW_Y: u32 = 30;
        const ROW_H: u32 = 24;
        const BG: [u8; 4] = [248, 249, 250, 255];
        const NAME_FG: [u8; 4] = [32, 33, 35, 255];
        const BADGE_SRV: [u8; 4] = [64, 120, 200, 255]; // Info 蓝（服务端）
        const BADGE_DSK: [u8; 4] = [150, 155, 165, 255]; // Neutral 灰（桌面）
        const ADDR_FG: [u8; 4] = [90, 94, 102, 255];
        const BADGE_W: u32 = 48;
        const BADGE_H: u32 = 18;

        fn old_display_name(d: &SavedDevice) -> String {
            let nick = d.nickname.trim();
            if !nick.is_empty() && nick != d.id {
                nick.to_string()
            } else if !d.remark.trim().is_empty() {
                d.remark.trim().to_string()
            } else {
                d.id.clone()
            }
        }

        let fp: String = "9".repeat(64);
        let d_rmk = dev10(&fp, "xk31fengmai", "机房一号机", DeviceConnMode::Id); // 服务端
        let d_nick = dev10("HD-46AA6109", "peer-nick", "", DeviceConnMode::Id);
        let fp3: String = "b7".repeat(32);
        let d_bare = dev10(&fp3, "", "", DeviceConnMode::Id);

        // 生产口径（修后）：device_row 纯函数直出。
        let new_names: Vec<String> =
            vec![d_rmk.clone(), d_nick.clone(), d_bare.clone()]
                .iter()
                .map(|d| device_row(d).name)
                .collect();
        // 旧口径（修前）：同名截断规则复刻（truncate_chars 共用）。
        let old_names: Vec<String> = [
            (old_display_name(&d_rmk), true),
            (old_display_name(&d_nick), true),
            (old_display_name(&d_bare), true),
        ]
        .iter()
        .map(|(s, _)| truncate_chars(s, DEVICE_NAME_MAX_CHARS).0)
        .collect();

        // 数据源钉死断言（探针画布 = 这些串的宽度函数）。
        assert_eq!(new_names[0], "机房一号机", "修后 = 备注名（本卡反转点）");
        assert_eq!(old_names[0], "xk31fengmai", "修前 = 机器形态昵称（用户所见）");
        assert_eq!(new_names[1], "peer-nick", "无备注 = 昵称零回归");
        assert_eq!(old_names[1], "peer-nick");
        assert_eq!(new_names[2].chars().count(), DEVICE_NAME_MAX_CHARS, "裸 ID 截断 24 char");
        assert_eq!(new_names[2], old_names[2], "裸 ID 修前=修后");

        fn panel(name: &str, kind_server: bool, addr: &str) -> image::RgbaImage {
            let mut img = image::RgbaImage::new(W, H);
            for py in 0..H {
                for px in 0..W {
                    img.put_pixel(px, py, image::Rgba(BG));
                }
            }
            // 名称槽（strong 文本复刻 = 定色横条，宽 = char 数 × CHAR_W）。
            let nw = name.chars().count() as u32 * CHAR_W;
            for dy in 0..ROW_H {
                for dx in 0..nw {
                    img.put_pixel(NAME_X + dx, ROW_Y + dy, image::Rgba(NAME_FG));
                }
            }
            // 类型徽标（定色块：服务端蓝 / 桌面灰）。
            let bx = NAME_X + nw + 8;
            let by = ROW_Y + (ROW_H - BADGE_H) / 2;
            let badge_c = if kind_server {
                image::Rgba(BADGE_SRV)
            } else {
                image::Rgba(BADGE_DSK)
            };
            for dy in 0..BADGE_H {
                for dx in 0..BADGE_W {
                    img.put_pixel(bx + dx, by + dy, badge_c);
                }
            }
            // 地址槽（mono 弱色条，定宽示意）。
            let ax = bx + BADGE_W + 8;
            for dy in 0..(ROW_H / 2) {
                for dx in 0..(addr.chars().count() as u32).min(20) * 7 {
                    img.put_pixel(ax + dx, ROW_Y + ROW_H / 2 + dy, image::Rgba(ADDR_FG));
                }
            }
            img
        }

        fn name_width(img: &image::RgbaImage) -> u32 {
            let y = ROW_Y + ROW_H / 2;
            let mut w = 0u32;
            while (NAME_X + w) < W && *img.get_pixel(NAME_X + w, y) != image::Rgba(BG) {
                w += 1;
            }
            w
        }

        let pa = panel(&old_names[0], true, "x"); // A 修前：备注条目（名称=昵称）
        let pb = panel(&new_names[0], true, "x"); // B 修后：备注条目（名称=备注）
        let pc = panel(&old_names[1], false, "y"); // C 修前：无备注
        let pd = panel(&new_names[1], false, "y"); // D 修后：无备注
        let pe = panel(&old_names[2], true, "z"); // E 修前：裸 ID
        let pf = panel(&new_names[2], true, "z"); // F 修后：裸 ID

        // ① 备注条目：修后名称槽宽 < 修前（备注名取代机器形态昵称入展示位）。
        let wa = name_width(&pa);
        let wb = name_width(&pb);
        assert_eq!(wa, "xk31fengmai".chars().count() as u32 * CHAR_W, "A 名称槽 = 昵称宽");
        assert_eq!(wb, "机房一号机".chars().count() as u32 * CHAR_W, "B 名称槽 = 备注宽");
        assert!(wb < wa, "修后展示位 = 备注名（窄于机器形态昵称）: {wb} < {wa}");
        // ② 无备注条目：修前 = 修后（零回归）。
        assert_eq!(name_width(&pc), name_width(&pd), "C/D 零回归");
        // ③ 裸 ID：修前 = 修后 = 24 char 截断（零回归）。
        assert_eq!(
            name_width(&pe),
            name_width(&pf),
            "E/F 裸 ID 截断零回归"
        );
        assert_eq!(name_width(&pe), DEVICE_NAME_MAX_CHARS as u32 * CHAR_W, "E/F = 24 char");
        // ④ 徽标两臂定色在位（A 服务端蓝 / C 桌面灰；B/D 同臂零变化）。
        fn badge_px(img: &image::RgbaImage, name_w: u32) -> image::Rgba<u8> {
            *img.get_pixel(NAME_X + name_w + 8 + BADGE_W / 2, ROW_Y + (ROW_H - BADGE_H) / 2 + 4)
        }
        assert_eq!(badge_px(&pa, wa), image::Rgba(BADGE_SRV), "A 徽标 = 服务端");
        assert_eq!(badge_px(&pc, name_width(&pc)), image::Rgba(BADGE_DSK), "C 徽标 = 桌面");
        assert_eq!(badge_px(&pb, wb), image::Rgba(BADGE_SRV), "B 徽标零变化");

        // 六面板 3×2 合成（上排修前 A/C/E，下排修后 B/D/F）→ docs 不入库。
        let mut out_img = image::RgbaImage::from_pixel(
            W * 3 + 16,
            H * 2 + 12,
            image::Rgba([30, 30, 34, 255]),
        );
        for (i, p) in [pa, pc, pe, pb, pd, pf].iter().enumerate() {
            let (cx, cy) = ((i % 3) as u32 * (W + 8), (i / 3) as u32 * (H + 12));
            image::GenericImage::copy_from(&mut out_img, p, cx, cy).expect("panel 不越界");
        }
        let out = std::path::Path::new("E:/projects_rd/docs/r137_10_device_row_remark_sandbox.png");
        out_img.save(out).expect("probe PNG 落盘");
        assert!(out.is_file(), "probe PNG 已生成");
    }

    /// 枚举，大小写敏感精确匹配）→ 对应 `devices.os.*` 键；空串（旧对端
    /// 未通告）/未知值（含大小写不符、带版本后缀等）→ None（不猜）。
    #[test]
    fn r137_10b_os_badge_key_matrix() {
        assert_eq!(os_type_badge_key("windows-11"), Some("devices.os.windows_11"));
        assert_eq!(os_type_badge_key("windows-10"), Some("devices.os.windows_10"));
        assert_eq!(os_type_badge_key("windows"), Some("devices.os.windows"));
        assert_eq!(os_type_badge_key("macos"), Some("devices.os.macos"));
        assert_eq!(os_type_badge_key("linux"), Some("devices.os.linux"));
        // 空（旧对端未通告）/ 未知值（不猜，回退角色徽标由上层决策）。
        assert_eq!(os_type_badge_key(""), None);
        assert_eq!(os_type_badge_key("windows-95"), None);
        assert_eq!(os_type_badge_key("win11"), None);
        assert_eq!(os_type_badge_key("Windows 11"), None);
        assert_eq!(os_type_badge_key("WINDOWS-11"), None);
        assert_eq!(os_type_badge_key("macos-14"), None);
        assert_eq!(os_type_badge_key("Linux"), None);
    }

    /// → (Info, devices.os.* 键)，OS 类型优先于角色；空/未知 → 回退角色
    /// 徽标（server = Info / desktop = Neutral，与 10b 前渲染口径逐位
    /// 一致 = 旧对端观感零变化）。
    #[test]
    fn r137_10b_device_type_badge_fallback_matrix() {
        for os in ["windows-11", "windows-10", "windows", "macos", "linux"] {
            for kind_server in [true, false] {
                assert_eq!(
                    device_type_badge(os, kind_server),
                    (BadgeKind::Info, os_type_badge_key(os).unwrap()),
                    "已知 OS 优先于角色徽标: os={os} kind_server={kind_server}"
                );
            }
        }
        assert_eq!(
            device_type_badge("", true),
            (BadgeKind::Info, "devices.kind.server"),
            "空 + server → 角色徽标（旧对端观感零变化）"
        );
        assert_eq!(
            device_type_badge("", false),
            (BadgeKind::Neutral, "devices.kind.desktop"),
            "空 + desktop → 角色徽标（旧对端观感零变化）"
        );
        for unknown in ["windows-95", "Linux", "macos-14"] {
            assert_eq!(
                device_type_badge(unknown, true),
                (BadgeKind::Info, "devices.kind.server"),
                "未知值不猜，回退角色: {unknown}"
            );
            assert_eq!(
                device_type_badge(unknown, false),
                (BadgeKind::Neutral, "devices.kind.desktop"),
                "未知值不猜，回退角色: {unknown}"
            );
        }
    }

    /// （`  (Windows 11)`，与基础段同 2 空格分隔口径）；空/未知 → 无类型
    /// 段（与 10b 前基础串逐位相等 = 零变化）。标签表达式与渲染处同源
    /// （`os_type_badge_key` + 运行时 `tr` + format），此处复刻表达式对
    /// `id_history_entries` 真实输出断言（OS 品牌名 zh/en 同形，语言态
    /// 无关）。
    #[test]
    fn r137_10b_id_history_dropdown_label_two_states() {
        crate::i18n::set_lang(crate::i18n::Lang::Zh);
        let fp = |i: u8| "c".repeat(62) + &format!("{i:02x}");
        let mk = |id: &str, os: &str| {
            let mut d = dev10(id, "", "", DeviceConnMode::Id);
            d.os_type = os.to_string();
            d
        };
        let devices = vec![
            mk(&fp(1), "windows-11"),
            mk(&fp(2), ""),
            mk(&fp(3), "freebsd-14"),
        ];
        let entries = id_history_entries(&devices, &[]);
        assert_eq!(entries.len(), 3, "三条 ID 模式记录全量入下拉");
        let by_os = |os: &str| entries.iter().find(|e| e.os_type == os).unwrap();
        // 与渲染处同一表达式（lib.rs ID 模式历史下拉循环）。
        let label_of = |h: &IdHistoryEntry| {
            let base = format!("{}  ({})", h.label, short_id_label(&h.device_id));
            match os_type_badge_key(&h.os_type) {
                Some(key) => format!("{base}  ({})", crate::i18n::tr(key)),
                None => base,
            }
        };
        let l_known = label_of(by_os("windows-11"));
        assert!(
            l_known.ends_with("  (Windows 11)"),
            "已知 OS 追加类型段: {l_known}"
        );
        for os in ["", "freebsd-14"] {
            let e = by_os(os);
            let l = label_of(e);
            assert_eq!(
                l,
                format!("{}  ({})", e.label, short_id_label(&e.device_id)),
                "空/未知值无类型段 = 10b 前基础串（零变化）: {l}"
            );
        }
    }

    /// （① server + 已通告 windows-11 = OS 徽标态；② server + 空 =
    /// 旧对端回退角色徽标态；③ server + 未知值 windows-95 = 未知回退
    /// 角色徽标态）实跑 `show_devices` 一帧（egui 陷阱家族防回潮——新增
    /// 动态键 `tr` 路径零 panic、行高/截断/ScrollArea 无 INFINITY 溢出）。
    #[test]
    fn r137_10b_device_page_two_state_headless_render() {
        let mut app = KirinDeskApp::default();
        let fp: String = "9".repeat(64);
        let mut d1 = dev10(&fp, "os-known", "", DeviceConnMode::Id);
        d1.device_type = "server".into();
        d1.os_type = "windows-11".into();
        let mut d2 = dev10("HD-46AA6109", "os-empty", "", DeviceConnMode::Id);
        d2.device_type = "server".into();
        // d2.os_type 保持空（dev10 默认）= 旧对端未通告。
        let mut d3 = dev10(&"b7".repeat(32), "os-unknown", "", DeviceConnMode::Id);
        d3.device_type = "server".into();
        d3.os_type = "windows-95".into();
        app.devices = vec![d1, d2, d3];

        let ctx = egui::Context::default();
        let mut raw = egui::RawInput::default();
        raw.screen_rect = Some(egui::Rect::from_min_size(
            egui::Pos2::ZERO,
            egui::vec2(520.0, 420.0),
        ));
        let mut cursor_end: Option<f32> = None;
        let _ = ctx.run(raw, |ctx| {
            let theme = &crate::theme::Theme::LIGHT;
            egui::Area::new(egui::Id::new("r137_10b_devices_probe"))
                .order(egui::Order::Foreground)
                .anchor(egui::Align2::LEFT_TOP, [0.0, 0.0])
                .show(ctx, |ui| {
                    ui.set_min_size(egui::vec2(520.0, 420.0));
                    app.show_devices(ui, theme);
                    cursor_end = Some(ui.cursor().min.y);
                });
        });
        let end = cursor_end.expect("probe 帧完成");
        assert!(
            end.is_finite() && end <= 420.0 + 1e-3,
            "双态（OS 徽标/回退角色徽标）三行渲染后光标有限且不越屏: {end}"
        );
    }

    /// 先例）：四面板——A 已通告 windows-11（Info 蓝 + "Windows 11"）、
    /// B 空 + server（Info 蓝 + "服务端"）、C 空 + desktop（Neutral 灰 +
    /// "桌面"）、D 未知值 + server（= B 同色同宽，回退不猜）。数据源 =
    /// `device_type_badge` 纯函数真实输出（键映射 zh 文案定色块）；定量
    /// 断言：① A Info + 10 char ② B Info + 3 char ③ C Neutral + 2 char
    /// ④ (D 色, D 宽) == (B 色, B 宽)。PNG → docs（不入库）。
    #[test]
    fn r137_10b_device_row_os_badge_probe_screenshot() {
        const W: u32 = 400;
        const H: u32 = 96;
        const CHAR_W: u32 = 12;
        const NAME_X: u32 = 12;
        const ROW_Y: u32 = 30;
        const ROW_H: u32 = 24;
        const BG: [u8; 4] = [248, 249, 250, 255];
        const NAME_FG: [u8; 4] = [32, 33, 35, 255];
        const BADGE_INFO: [u8; 4] = [64, 120, 200, 255]; // Info 蓝
        const BADGE_NEUTRAL: [u8; 4] = [150, 155, 165, 255]; // Neutral 灰
        const ADDR_FG: [u8; 4] = [90, 94, 102, 255];
        const BADGE_H: u32 = 18;

        // 数据源 = 生产纯函数真实输出（四态）。
        let fp: String = "9".repeat(64);
        let mk = |os: &str, device_type: &str| {
            let mut d = dev10(&fp, "os-probe", "", DeviceConnMode::Id);
            d.os_type = os.to_string();
            d.device_type = device_type.to_string();
            d
        };
        let cases = [
            mk("windows-11", "server"), // A：已知 OS（Info 优先于角色）
            mk("", "server"), // B：空 + server（回退角色）
            mk("", "desktop"), // C：空 + desktop（回退角色）
            mk("windows-95", "server"), // D：未知值 + server（回退，不猜）
        ];
        let badges: Vec<(BadgeKind, &'static str)> =
            cases.iter().map(|d| device_type_badge(&d.os_type, d.device_type == "server")).collect();
        // 键钉死断言（徽标语义 = 纯函数决策，画布只是其复刻）。
        assert_eq!(badges[0], (BadgeKind::Info, "devices.os.windows_11"));
        assert_eq!(badges[1], (BadgeKind::Info, "devices.kind.server"));
        assert_eq!(badges[2], (BadgeKind::Neutral, "devices.kind.desktop"));
        assert_eq!(badges[3], (BadgeKind::Info, "devices.kind.server"), "未知值不猜");

        fn badge_label(key: &'static str) -> String {
            match key {
                "devices.os.windows_11" => "Windows 11".to_string(),
                "devices.os.windows_10" => "Windows 10".to_string(),
                "devices.os.windows" => "Windows".to_string(),
                "devices.os.macos" => "macOS".to_string(),
                "devices.os.linux" => "Linux".to_string(),
                "devices.kind.server" => "服务端".to_string(),
                _ => "桌面".to_string(),
            }
        }
        fn kind_color(kind: BadgeKind) -> image::Rgba<u8> {
            match kind {
                BadgeKind::Info => image::Rgba(BADGE_INFO),
                _ => image::Rgba(BADGE_NEUTRAL),
            }
        }

        const NAME: &str = "设备甲"; // 统一名称槽（36px），徽标位 X 恒定
        assert_eq!(NAME.chars().count(), 3, "名称槽宽钉死 3 char");
        let badge_x = NAME_X + NAME.chars().count() as u32 * CHAR_W + 8;

        let panel = |badge_kind: BadgeKind, label: &str| -> image::RgbaImage {
            let mut img = image::RgbaImage::new(W, H);
            for py in 0..H {
                for px in 0..W {
                    img.put_pixel(px, py, image::Rgba(BG));
                }
            }
            // 名称槽（定色横条，宽 = char 数 × CHAR_W）。
            let nw = NAME.chars().count() as u32 * CHAR_W;
            for dy in 0..ROW_H {
                for dx in 0..nw {
                    img.put_pixel(NAME_X + dx, ROW_Y + dy, image::Rgba(NAME_FG));
                }
            }
            // 类型徽标（定色块，宽 = 文案 char 数 × CHAR_W）。
            let by = ROW_Y + (ROW_H - BADGE_H) / 2;
            let bw = label.chars().count() as u32 * CHAR_W;
            for dy in 0..BADGE_H {
                for dx in 0..bw {
                    img.put_pixel(badge_x + dx, by + dy, kind_color(badge_kind));
                }
            }
            // 地址槽（mono 弱色条，定宽示意，防面板留白歧义）。
            for dy in 0..(ROW_H / 2) {
                for dx in 0..84u32 {
                    img.put_pixel(badge_x + bw + 8 + dx, ROW_Y + ROW_H / 2 + dy, image::Rgba(ADDR_FG));
                }
            }
            img
        };

        let panels: Vec<image::RgbaImage> = badges
            .iter()
            .map(|(k, key)| panel(*k, &badge_label(key)))
            .collect();

        // 定量测量（徽标起点色 + 填充宽；`badge_x`/`mid_y` 运行时值 →
        // 闭包形，fn item 不收动态环境）。
        let mid_y = ROW_Y + (ROW_H - BADGE_H) / 2 + 4;
        let badge_color = |img: &image::RgbaImage| *img.get_pixel(badge_x + 4, mid_y);
        let badge_width = |img: &image::RgbaImage| {
            let mut w = 0u32;
            while (badge_x + w) < W && *img.get_pixel(badge_x + w, mid_y) != image::Rgba(BG) {
                w += 1;
            }
            w
        };

        // ① A：Info 蓝 + "Windows 11"（10 char）。
        assert_eq!(badge_color(&panels[0]), image::Rgba(BADGE_INFO), "A = Info 蓝");
        assert_eq!(
            badge_width(&panels[0]),
            "Windows 11".chars().count() as u32 * CHAR_W,
            "A 徽标宽 = OS 文案宽"
        );
        // ② B：Info 蓝 + "服务端"（3 char）= 旧对端回退角色。
        assert_eq!(badge_color(&panels[1]), image::Rgba(BADGE_INFO), "B = Info 蓝（server 角色）");
        assert_eq!(badge_width(&panels[1]), 3 * CHAR_W, "B 徽标宽 = 角色文案宽");
        // ③ C：Neutral 灰 + "桌面"（2 char）。
        assert_eq!(
            badge_color(&panels[2]),
            image::Rgba(BADGE_NEUTRAL),
            "C = Neutral 灰（desktop 角色）"
        );
        assert_eq!(badge_width(&panels[2]), 2 * CHAR_W, "C 徽标宽 = 角色文案宽");
        // ④ D：未知值回退 = B 同色同宽（不猜 OS）。
        assert_eq!(
            (badge_color(&panels[3]), badge_width(&panels[3])),
            (badge_color(&panels[1]), badge_width(&panels[1])),
            "D（未知值）== B（空）= 同一角色回退"
        );

        // 2×2 合成 → docs（不入库）。
        let mut out_img =
            image::RgbaImage::from_pixel(W * 2 + 8, H * 2 + 8, image::Rgba([30, 30, 34, 255]));
        for (i, p) in panels.iter().enumerate() {
            let (cx, cy) = ((i % 2) as u32 * (W + 8), (i / 2) as u32 * (H + 8));
            image::GenericImage::copy_from(&mut out_img, p, cx, cy).expect("panel 不越界");
        }
        let out = std::path::Path::new("E:/projects_rd/docs/r137_10b_device_row_os_badge_sandbox.png");
        out_img.save(out).expect("probe PNG 落盘");
        assert!(out.is_file(), "probe PNG 已生成");
    }
}

