#[cfg(test)]
mod r92e1_engine_tests {
    use super::*;
    use kirin_desk_core::crypto::handshake::{PROTO_VER_LEGACY, PROTOCOL_VERSION};
    use std::io::Write as _;

    /// shell 通道会话（同 r92s2_tests 口径：quota 0/0 不限 + 无 GUI 弹窗）。
    fn shell_session(
        sink: tokio::sync::mpsc::UnboundedSender<Vec<u8>>,
        peer_proto_ver: u32,
    ) -> FileSession {
        FileSession::new_shell(
            sink,
            peer_proto_ver,
            server_file_panel_state(),
            "r92e1-salt".into(),
            std::env::temp_dir().join(format!("kirin_r92e1_store_{}", std::process::id())),
            std::env::temp_dir().join(format!("kirin_r92e1_dl_{}", std::process::id())),
            DEFAULT_MAX_FILE_SIZE,
            None,
            SessionQuota::new(0, 0),
            FsPolicy::headless(&[], &[]),
            None,
            FsRouter::new(),
        )
    }

    fn tmp_file(tag: &str, content: &str) -> PathBuf {
        let p = std::env::temp_dir().join(format!(
            "kirin_r92e1_{tag}_{}.txt",
            std::process::id()
        ));
        let mut f = std::fs::File::create(&p).unwrap();
        f.write_all(content.as_bytes()).unwrap();
        p
    }

    /// take_fs_response 生产接线（D2 移交必核①，`#[cfg(test)]` 已摘）：
    /// Fs 命令 → `Admitted`（req_id 关联）→ 响应帧 → drain `take_fs_response`
    /// → `Response` 事件（一次性消费）。
    #[tokio::test]
    async fn test_r92e1_fs_event_take_production_wire() {
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        let mut ft = shell_session(tx, PROTOCOL_VERSION);
        let (etx, mut erx) =
            tokio::sync::mpsc::unbounded_channel::<file_manager::FsEvent>();
        ft = ft.with_fs_event_tx(etx);

        // 发起 List → Admitted 事件（req_id ↔ op 关联）。
        ft.handle_command(FileCommand::Fs {
            op: FsOp::List {
                path: "d".into(),
                offset: 0,
                limit: 500,
            },
        })
        .await;
        let req = match erx.try_recv() {
            Ok(file_manager::FsEvent::Admitted { req_id, op }) => {
                assert_eq!(
                    op,
                    FsOp::List {
                        path: "d".into(),
                        offset: 0,
                        limit: 500
                    }
                );
                req_id
            }
            other => panic!("应得 Admitted，实际 {other:?}"),
        };
        // 响应未投递：take = None（停放保留）。
        assert!(ft.take_fs_response(req).is_none(), "未投递 = None");

        // 注入响应帧（req_id 置于 transfer_id，既有帧格式零改动）。
        let payload = FsResponsePayload {
            ok: true,
            err: FsErrCode::Ok,
            payload: bincode::serialize(&FsListPayload {
                entries: vec![],
                has_more: false,
                root_display: "d".into(),
            })
            .unwrap(),
        };
        ft.handle_frame(FileTransferFrame {
            transfer_id: req as u64,
            op: FileOp::FsResponse,
            seq: 0,
            total_blocks: 0,
            data: bincode::serialize(&payload).unwrap(),
            sha256: [0u8; 32],
        })
        .await;
        // drain（会话任务循环每轮同款逻辑）= Some(Ok)。
        let ids: Vec<u32> = ft.fs_pending.keys().copied().collect();
        assert_eq!(ids, vec![req], "响应已停放");
        let res = ft.take_fs_response(req).unwrap();
        assert!(res.as_ref().unwrap().ok);
        // 一次性消费：再取 = None（停放已清）。
        assert!(ft.take_fs_response(req).is_none(), "一次性消费");
        // 迟到重复响应 = 静默丢弃（不 panic、不报错，§1.2 防状态漂移）。
        ft.handle_frame(FileTransferFrame {
            transfer_id: req as u64,
            op: FileOp::FsResponse,
            seq: 0,
            total_blocks: 0,
            data: bincode::serialize(&payload).unwrap(),
            sha256: [0u8; 32],
        })
        .await;
        assert!(ft.fs_pending.is_empty(), "迟到响应不入停放表");
        // 正向 wire 断言：FsRequest 帧确已上线（req_id 置于 transfer_id）。
        let bytes = rx.try_recv().expect("v3 对端 FsRequest 帧应已上线");
        let sent = FileTransferFrame::decode(&bytes).unwrap();
        assert_eq!(sent.op, FileOp::FsRequest);
        assert_eq!(sent.transfer_id, req as u64);
    }

    /// K4 v2 客户端发送点（shell ⬆ 载体，D2/S-2 移交 E1）：
    /// `SendToRemote` → `OfferV2` 帧上线（`target_dir` = 远端栏当前目录，
    /// `overwrite=false` 恒成立 = 无静默覆盖）。
    #[tokio::test]
    async fn test_r92e1_send_to_remote_offer_v2_wire() {
        let path = tmp_file("up_v2", "hello");
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        let mut ft = shell_session(tx, PROTOCOL_VERSION);
        ft.handle_mgr_command(file_manager::FileMgrCommand::SendToRemote {
            path: path.clone(),
            target_dir: "docs".into(),
        })
        .await;
        let bytes = tokio::time::timeout(
            std::time::Duration::from_secs(2),
            rx.recv(),
        )
        .await
        .expect("2s 内应得 Offer 帧")
        .expect("sink 未闭");
        let frame = FileTransferFrame::decode(&bytes).unwrap();
        assert_eq!(frame.op, FileOp::OfferV2, "上传 = OfferV2 载体");
        let meta: FileOfferV2Meta = bincode::deserialize(&frame.data).unwrap();
        assert_eq!(
            meta.name,
            format!("kirin_r92e1_up_v2_{}.txt", std::process::id())
        );
        assert_eq!(meta.size, 5);
        assert_eq!(meta.target_dir, "docs", "落点 = 远端栏当前目录");
        assert!(!meta.overwrite, "overwrite=false 恒成立（无静默覆盖）");
        let _ = std::fs::remove_file(&path);
    }

    /// legacy-0 对端 = OfferV2 **零发送**（`send_frame` 单点版本门，
    /// fail-closed，禁探测法 D-3）——sink 零字节 wire 级断言。
    #[tokio::test]
    async fn test_r92e1_send_to_remote_legacy0_zero_wire() {
        let path = tmp_file("up_v2_l0", "hello");
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        let mut ft = shell_session(tx, PROTO_VER_LEGACY);
        ft.handle_mgr_command(file_manager::FileMgrCommand::SendToRemote {
            path: path.clone(),
            target_dir: "docs".into(),
        })
        .await;
        assert!(
            rx.try_recv().is_err(),
            "legacy-0 对端文件帧必须零发送（fail-closed）"
        );
        let _ = std::fs::remove_file(&path);
    }

    /// v1 回归护栏：`FileCommand::SendFile`（拖拽臂既有路径）= 普通
    /// `Offer` 帧（`cmd_send_file_inner` 重构零行为变化）。
    #[tokio::test]
    async fn test_r92e1_send_file_v1_offer_unchanged() {
        let path = tmp_file("up_v1", "abcde");
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        let mut ft = shell_session(tx, PROTOCOL_VERSION);
        ft.handle_command(FileCommand::SendFile {
            path: path.clone(),
        })
        .await;
        let bytes = tokio::time::timeout(
            std::time::Duration::from_secs(2),
            rx.recv(),
        )
        .await
        .expect("2s 内应得 Offer 帧")
        .expect("sink 未闭");
        let frame = FileTransferFrame::decode(&bytes).unwrap();
        assert_eq!(frame.op, FileOp::Offer, "v1 路径 = 普通 Offer");
        let meta: FileOfferMeta = bincode::deserialize(&frame.data).unwrap();
        assert_eq!(meta.size, 5);
        let _ = std::fs::remove_file(&path);
    }
}

