    /// （UI 无覆盖入口，同名自动改名同 v1 口径）。v1 回归护栏 = 既有
    /// `test_r92e1_send_file_v1_offer_unchanged` 零变化。
    #[tokio::test]
    async fn test_r137_2_send_file_v2_offer_v2_target_pinned() {
        let path = std::env::temp_dir().join(format!(
            "kirin_r137_2_up_{}.txt",
            std::process::id()
        ));
        {
            let mut f = std::fs::File::create(&path).unwrap();
            f.write_all(b"abcde").unwrap();
        }
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        let mut ft = r137_2_shell_session(tx);
        ft.handle_command(FileCommand::SendFileV2 {
            path: path.clone(),
            target_dir: "up/proj".into(),
        })
        .await;
        let bytes = tokio::time::timeout(
            std::time::Duration::from_secs(2),
            rx.recv(),
        )
        .await
        .expect("2s 内应得 OfferV2 帧")
        .expect("sink 未闭");
        let frame = FileTransferFrame::decode(&bytes).unwrap();
        assert_eq!(frame.op, FileOp::OfferV2, "SendFileV2 = OfferV2 既有帧");
        let meta: FileOfferV2Meta = bincode::deserialize(&frame.data).unwrap();
        assert_eq!(meta.target_dir, "up/proj", "target_dir 透传（root 相对）");
        assert!(!meta.overwrite, "overwrite=false 恒成立");
        assert_eq!(meta.size, 5);
        let _ = std::fs::remove_file(&path);
    }

    /// 生产接线锚（防回潮）：粘贴派发臂消费**逐帧 FM 目标快照**（同 peer
