// ════════════════════════════════════════════════════════════════
// ① 注册表置/清位单点幂等矩阵（session_id 精确配对/重连并存零误清/
//    空 entry 即移除 = 注册表有界）；
// ② 双臂判定核三态矩阵（开关 on/off × 关系在/缺位——开关关 = 恒放行
//    = 基线逐位一致；缺位 = 放行 = 老对端互通降级钉死）；
// ③ 归一化键对称（指纹/短码形态两端同 canonical）；
// ④ 拒绝码常量 + 双臂生产接线锚（admission 臂/发起端臂/guard 置清位/
//    设置开关落盘——防静默移除回归护栏，r137_2/r167 wiring_check 先例）；
// ⑤ i18n 成对逐字（全局成对单测自动覆盖 + 本 mod 定向断言）。
// ════════════════════════════════════════════════════════════════
#[cfg(test)]
mod r169_tests {
    use super::*;

    /// 会话（重连并存）单清零误伤；全清后 entry 移除（有界）；重复置位
    /// 同 session id 幂等（HashSet 语义）。
    #[test]
    fn r169_registry_set_clear_lifecycle() {
        // 键空间隔离：用本测试专属 peer 键（真实设备 ID 形态），防并行
        let peer = "r169t:aa:bb:cc:dd:ee:ff:00:11";
        let peer2 = "r169t:11:22:33:44:55:66:77:88";
        assert!(!r169_am_i_controlling(peer), "前置：无控制关系");
        assert!(!r169_am_i_controlled_by(peer), "前置：无受控关系");

        let g1 = r169_mark_controlling(peer, 9001, None);
        assert!(r169_am_i_controlling(peer));
        assert!(!r169_am_i_controlled_by(peer), "方向隔离：controlled_by 独立");

        // 同向第二会话（重连并存形态 #2）→ 仍命中；清 #2 不误清 #1。
        let g2 = r169_mark_controlling(peer, 9002, None);
        assert!(r169_am_i_controlling(peer));
        drop(g2);
        assert!(r169_am_i_controlling(peer), "并存期清单会话不误清另一会话");
        drop(g1);
        assert!(
            !r169_am_i_controlling(peer),
            "全会话清位后关系解除（guard drop 单点清位）"
        );

        // 反方向独立：他控我置位/清位。
        let g2 = r169_mark_controlled_by(peer, 9003);
        assert!(r169_am_i_controlled_by(peer));
        assert!(!r169_am_i_controlling(peer), "两方向互不串扰");
        drop(g2);
        assert!(!r169_am_i_controlled_by(peer));

        // 空 entry 移除（有界）：置/清后注册表无残留键。
        let g3 = r169_mark_controlling(peer2, 9004, None);
        drop(g3);
        let slot = r169_mutual_slot();
        let map = slot.lock().unwrap();
        assert!(
            !map.contains_key(normalize_device_id_input(peer2).as_str()),
            "空 entry 即移除：注册表有界 = 活跃会话数"
        );
    }

    /// 自测对照臂）；开关开 × 关系缺位放行（老对端互通降级 = 未建立控制
    /// 关系不拦截）；开关开 × 关系在位拦截（fail-closed）。
    #[test]
    fn r169_decision_cores_three_state_matrix() {
        // 被叫端兜底臂。
        assert!(!r169_callee_should_reject(false, true), "开关关：恒放行");
        assert!(!r169_callee_should_reject(false, false));
        assert!(!r169_callee_should_reject(true, false), "关系缺位：放行（互通底线）");
        assert!(r169_callee_should_reject(true, true), "fail-closed 拒绝");
        // 发起端预检臂。
        assert!(!r169_initiator_should_block(false, true), "开关关：恒放行");
        assert!(!r169_initiator_should_block(false, false));
        assert!(!r169_initiator_should_block(true, false), "关系缺位：放行");
        assert!(r169_initiator_should_block(true, true), "拒发 + 显式提示");
    }

    /// canonical（置位侧用带分隔大写形态、查询侧用紧凑小写形态 → 仍命中）；
    /// 缺位 peer 恒 false（老对端零通告 = 维持现状可用）。
    #[test]
    fn r169_key_normalization_symmetry() {
        let raw_fingerprint: String = vec!["A1B2"; 16].join(":"); // 64 hex 带分隔
        let compact: String = "a1b2".repeat(16); // 64 hex 紧凑小写
        let g = r169_mark_controlling(&raw_fingerprint, 9101, None);
        assert!(
            r169_am_i_controlling(&compact),
            "指纹形态归一对称（大小写/冒号差异同 canonical）"
        );
        drop(g);
        assert!(!r169_am_i_controlling(&compact));
        // 缺位 peer：恒 false（互通降级钉死）。
        assert!(!r169_am_i_controlling("r169t:never:registered"));
        assert!(!r169_am_i_controlled_by("r169t:never:registered"));
    }

    /// ①伪造 client_id + 注册表内公钥 → 拒（修前 id 单键放行）；②真实
    /// client_id（id 臂命中）+ 陌生公钥 → 拒（id 臂独立执法）；③开关关 →
    /// 恒放行；④无公钥记录（`None` 登记 = 旧路径）→ 公钥臂恒不命中 =
    /// 行为与现状逐位一致；公钥随会话 guard drop 清位（禁跨会话残留）；
    /// 归一（trim）对称；空串公钥恒不命中。
    #[test]
    fn r184_dual_key_callee_match_matrix() {
        // 键空间隔离：本测专属 peer/公钥（进程内单例槽 + 全表值扫描纪律）。
        let peer = "r184t:aa:bb:cc:dd:ee:ff:01:02";
        let key = "Q184dGVzdC1rZXktZm9yZ2VkLWlkLWFybQ==";
        let stranger_key = "Q184c3RyYW5nZXIta2V5LXVucmVnaXN0ZXJlZA==";

        // 前置：无控制关系两臂皆不命中。
        assert!(!r169_am_i_controlling(peer), "前置：无控制关系");
        assert!(!r169_am_i_controlling_by_key(key), "前置：公钥臂不命中");

        // 登记在控关系（对端已验证公钥 = 握手成功处 trusted_key 同源值）。
        let g = r169_mark_controlling(peer, 18401, Some(key));
        assert!(r169_am_i_controlling(peer), "id 臂既有行为不变");
        assert!(r169_am_i_controlling_by_key(key), "公钥臂命中（登记值）");
        assert!(
            r169_am_i_controlling_by_key(&format!("  {key}  ")),
            "公钥归一（trim）对称：置/查两侧同 canonical"
        );
        assert!(!r169_am_i_controlling_by_key(stranger_key), "陌生公钥不命中");
        assert!(!r169_am_i_controlling_by_key(""), "空公钥恒不命中");

        // ① 伪造 client_id（id 臂缺位）+ 注册表内公钥 → 拒（修前放行）。
        let forged_id_hit = r169_am_i_controlling("r184t:ff:aa:kk:ee:dd:ii:dd");
        let forged_combined = forged_id_hit || r169_am_i_controlling_by_key(key);
        assert!(
            r169_callee_should_reject(true, forged_combined),
        );
        // ② 真实 client_id（id 臂命中）+ 陌生公钥 → 拒（id 臂独立执法）。
        let real_combined =
            r169_am_i_controlling(peer) || r169_am_i_controlling_by_key(stranger_key);
        assert!(r169_callee_should_reject(true, real_combined), "id 臂命中 = 拒");
        // ③ 开关关 → 恒放行（既有三态矩阵不变，双键只是关系判定输入）。
        assert!(!r169_callee_should_reject(false, forged_combined), "开关关：恒放行");

        // guard drop = 会话清位含公钥集（controlling 侧归零即失效）。
        drop(g);
        assert!(!r169_am_i_controlling(peer));
        assert!(!r169_am_i_controlling_by_key(key), "公钥随会话终结清位（零残留）");

        // ④ 无公钥记录旧路径（`None` 登记）：公钥臂恒不命中 = 旧行为逐位
        // 一致；id 臂独立执法不受影响。
        let g0 = r169_mark_controlling(peer, 18402, None);
        assert!(r169_am_i_controlling(peer), "id 臂既有行为");
        assert!(
            !r169_am_i_controlling_by_key(key),
            "None 登记 = 公钥臂恒不命中（旧条目兼容基线）"
        );
        assert!(
            r169_callee_should_reject(true, r169_am_i_controlling(peer)),
            "旧路径 id 臂照常拒绝"
        );
        drop(g0);
        assert!(!r169_am_i_controlling(peer));
        assert!(!r169_am_i_controlling_by_key(key), "清位后零残留");
    }

    /// HandshakeReject 通道复用，零枚举/字段/版本变化——老客户端未知码
    /// fail-safe 原始错误串呈现）。
    #[test]
    fn r169_reject_code_constant() {
        assert_eq!(REJECT_CODE_MUTUAL_CONTROL, "mutual_control_denied");
        // 既有码族零漂移（抽二钉值）。
        assert_eq!(REJECT_CODE_APPROVAL_DECLINED, "approval_declined");
        assert_eq!(REJECT_CODE_UNATTENDED_UNKNOWN, "unattended_unknown");
    }

    /// 臂 / 发起端预检臂 / 置清位两点 / 设置开关落盘 / i18n 键消费在位。
    #[test]
    fn r169_wiring_check() {
        let lib_src =
            std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/src/lib.rs"))
                .expect("read self");
        // 被叫端兜底臂（admission 内：审批分支前置）。
        assert!(
            lib_src.contains("admission rejected: mutual-control forbidden"),
            "admission 兜底拒绝锚行在位"
        );
        assert!(
            lib_src.contains("send_handshake_reject(\n                        &mut stream,\n                        REJECT_CODE_MUTUAL_CONTROL,"),
            "结构化拒绝码发送在位"
        );
        assert!(
            lib_src.contains("reason=mutual_control_denied"),
            "审计 reason 串在位（fail-closed 禁静默）"
        );
        assert!(
            lib_src.contains("reason=mutual_control_denied match={r169_match}"),
            "审计 match=key_id/key_pub 标注在位（伪造 id 定案证据）"
        );
        // 发起端预检臂（ID 模式入口）。
        assert!(
            lib_src.contains("r169_initiator_should_block(cfg.tunnel.forbid_mutual_control"),
            "发起端预检臂接线在位"
        );
        assert!(
            lib_src.contains("connect.error.mutual_control_blocked"),
            "发起端显式提示 i18n 消费在位"
        );
        // 置/清位两点。
        assert!(
            lib_src.contains(
                "r169_mark_controlling(&peer_id, session_id, peer_verified_key.as_deref())"
            ),
        );
        assert!(
            lib_src.contains("r169_mark_controlled_by(&peer_id_ft, session_id)"),
            "受控端置位单点（服务端桌面连接级任务）在位"
        );
        assert!(
            lib_src.contains("mutual-control relation released"),
            "guard drop 清位锚行在位（会话终态单点）"
        );
        // 设置开关落盘 + 显示。
        assert!(
            lib_src.contains("cfg.tunnel.forbid_mutual_control = self.forbid_mutual_control"),
            "设置保存落盘在位"
        );
        assert!(
            lib_src.contains("self.forbid_mutual_control = cfg.tunnel.forbid_mutual_control"),
            "设置初值显示在位"
        );
        // policy 映射（新码 → i18n）。
        let policy_src =
            std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/src/policy.rs"))
                .expect("read policy");
        assert!(
            policy_src.contains("REJECT_CODE_MUTUAL_CONTROL =>"),
            "拒绝码→文案映射臂在位"
        );
        // i18n 成对（zh/en 非空）定向断言。
        for key in [
            "connect.error.mutual_control_denied",
            "connect.error.mutual_control_blocked",
            "settings.mutual.title",
            "settings.mutual.toggle",
            "settings.mutual.toggle_hint",
            "settings.mutual.rejected_toast",
        ] {
            let hits: Vec<_> = crate::i18n::ALL
                .iter()
                .flat_map(|t| t.iter())
                .filter(|(k, _, _)| *k == key)
                .collect();
            assert_eq!(hits.len(), 1, "键 {key} 恰定义一次");
            let (_, zh, en) = hits[0];
            assert!(!zh.is_empty() && !en.is_empty(), "键 {key} zh/en 成对非空");
        }
    }
}

//    UI 侧纯函数族测试归 file_panel.rs 测试模块）──
#[cfg(test)]
mod r92e2_engine_tests {
    use super::*;
    use kirin_desk_core::crypto::handshake::PROTOCOL_VERSION;
    use std::io::Write as _;

    fn r92e2_dir(tag: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!(
            "kirin_r92e2_{tag}_{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    /// shell 通道会话（同 r92e1_engine_tests 口径；store 落本用例私有目录）。
    fn e2_shell_session(
        dir: &Path,
        panel: &'static Mutex<FilePanelState>,
        quota: SessionQuota,
    ) -> FileSession {
        let (sink_tx, _sink_rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        FileSession::new_shell(
            sink_tx,
            PROTOCOL_VERSION,
            panel,
            "r92e2-salt".into(),
            dir.join("transfers_client.json"),
            dir.join("dl"),
            DEFAULT_MAX_FILE_SIZE,
            None,
            quota,
            FsPolicy::headless(&[], &[]),
            None,
            FsRouter::new(),
        )
    }

    /// ✕ 放弃（设计 v1.4 §4.2 G2 / 框图 2）= 删 store 条目 + 删 `.part`
    ///（**零 wire 帧**）；在途任务 = fail-closed no-op（纵深防御守卫）；
    /// 未知 tid = no-op（无 panic/无副作用）。
    #[tokio::test]
    async fn test_r92e2_discard_resume_store_and_part() {
        let dir = r92e2_dir("discard");
        let store_path = dir.join("transfers_client.json");
        let part = dir.join("big.txt.part");
        std::fs::write(&part, b"partial-data").unwrap();
        let tid: u64 = 0x92e2_0001;
        let seeded = TransferStore {
            transfers: vec![StoredTransfer {
                transfer_id: tid,
                name: "big.txt".into(),
                size: 200_000,
                direction: "send".into(),
                next_seq: 1,
                sha256: Some([0u8; 32]),
                part_path: Some(part.to_string_lossy().to_string()),
            }],
        };
        seeded.save_to(&store_path).unwrap();

        let mut ft = e2_shell_session(&dir, server_file_panel_state(), SessionQuota::new(0, 0));

        // 在途守卫：真实发送任务在途（Offer 已发零响应）→ 放弃 = no-op
        //（任务态 + store 条目均保留；UI 侧去重已排除在途，此为纵深防御）。
        let src = dir.join("inflight.bin");
        let mut f = std::fs::File::create(&src).unwrap();
        f.write_all(b"0000000089").unwrap();
        drop(f);
        let inflight_tid = derive_transfer_id("inflight.bin", 10, "r92e2-salt");
        ft.cmd_send_file(src.clone()).await;
        assert!(ft.senders.contains_key(&inflight_tid), "前置：任务在途");
        ft.handle_command(FileCommand::DiscardResume {
            transfer_id: inflight_tid,
        })
        .await;
        assert!(
            ft.senders.contains_key(&inflight_tid),
            "在途任务必须零触碰"
        );
        assert!(
            TransferStore::load_from(&store_path)
                .unwrap()
                .transfers
                .iter()
                .any(|t| t.transfer_id == inflight_tid),
            "在途守卫 = store 条目保留"
        );
        // 收尾在途任务（防残留污染后续断言；Cancel 走既有清理链零 wire 改动）。
        ft.handle_command(FileCommand::Cancel {
            transfer_id: inflight_tid,
        })
        .await;

        // 正语义：断点条目（0 < next_seq < total）→ store 删 + `.part` 删。
        ft.handle_command(FileCommand::DiscardResume { transfer_id: tid })
            .await;
        let after = TransferStore::load_from(&store_path).unwrap_or_default();
        assert!(
            after.transfers.iter().all(|t| t.transfer_id != tid),
            "store 条目必须删除"
        );
        assert!(!part.exists(), "`.part` 文件必须删除");

        // 未知 tid = no-op。
        ft.handle_command(FileCommand::DiscardResume {
            transfer_id: tid + 1,
        })
        .await;
        let _ = std::fs::remove_file(&src);
    }

    /// 配额条数据源（设计 §5 / 框图 2 头行）：on_tick（1s 粒度）发布已用
    /// 快照 → 全局面板 `quota_used`（上限 UI 侧自同一 config 源读取——core
    /// `SessionQuota` max 为私有字段 = core 零改动红线下唯一通路）。
    #[tokio::test]
    async fn test_r92e2_quota_used_published_to_panel() {
        let dir = r92e2_dir("quota");
        let panel: &'static Mutex<FilePanelState> =
            Box::leak(Box::new(Mutex::new(FilePanelState::new())));
        let mut ft = e2_shell_session(&dir, panel, SessionQuota::new(100, 5));
        ft.on_tick().await;
        let p = panel.lock().unwrap();
        assert_eq!(
            p.quota_used,
            Some((0, 0)),
            "tick 后已用快照必须发布（初始全 0）"
        );
    }
}

// ════════════════════════════════════════════════════════════════
// ════════════════════════════════════════════════════════════════
#[cfg(test)]
mod r91e_server_clip_tests {
    use super::*;

    /// 测试辅助：内存假板（文本 + CF_HDROP 文件清单双读 + 读板计数）。
    struct FakeE1Board {
        text: Option<String>,
        file_board: Option<clipboard::OsFileBoard>,
        get_text_calls: usize,
        get_file_calls: usize,
    }

    impl FakeE1Board {
        fn new() -> Self {
            Self {
                text: None,
                file_board: None,
                get_text_calls: 0,
                get_file_calls: 0,
            }
        }
    }

    impl clipboard::ClipboardIo for FakeE1Board {
        fn get_text(&mut self) -> Option<String> {
            self.get_text_calls += 1;
            self.text.clone()
        }
        fn set_text(&mut self, text: &str) -> bool {
            self.text = Some(text.to_string());
            true
        }
        fn get_file_meta(&mut self) -> Option<clipboard::OsFileBoard> {
            self.get_file_calls += 1;
            self.file_board.clone()
        }
    }

    /// 测试辅助：文件清单条目（abs_path + size + is_dir）。
    fn e1_board(entries: Vec<(&str, u64, bool)>) -> clipboard::OsFileBoard {
        clipboard::OsFileBoard {
            entries: entries
                .into_iter()
                .map(|(abs_path, size, is_dir)| clipboard::OsFileEntry {
                    abs_path: abs_path.to_string(),
                    size,
                    is_dir,
                })
                .collect(),
        }
    }

    /// 测试辅助：FILEMETA 帧序列 → FileClipMeta 逆运算（同时钉死 §2.1
    /// 旧端安全形态：flags 恒 = 0x04，零 START/零 END 位）。
    fn e1_reassemble_filemeta(pkts: &[EncodedPacket]) -> clipboard::FileClipMeta {
        assert!(!pkts.is_empty());
        let mut parts: Vec<(u8, u8, Vec<u8>)> = Vec::new();
        for p in pkts {
            assert_eq!(p.kind, PacketKind::Clipboard);
            assert_eq!(
                p.data[0],
                clipboard::CLIP_FLAG_FILEMETA,
                "FILEMETA 帧 flags 恒 = 0x04（零 START/零 END，§2.1 唯一旧端安全形态）"
            );
            let frag: clipboard::FileClipMetaFragment =
                bincode::deserialize(&p.data[1..]).expect("fragment bincode");
            parts.push((frag.seq, frag.total, frag.payload));
        }
        parts.sort_by_key(|(seq, _, _)| *seq);
        assert_eq!(parts.len() as u8, parts[0].1, "seq 必须 1..=total 无缺无重");
        let mut joined = Vec::new();
        for (_, _, payload) in &parts {
            joined.extend_from_slice(payload);
        }
        bincode::deserialize(&joined).expect("FileClipMeta bincode")
    }

    /// 与设备 ID 同值 → 仅设备 ID（避免双显同值）。
    #[test]
    fn e1_target_label_matrix() {
        assert_eq!(
            dashboard_target_label("办公PC", "G7KJ2MNQ4X"),
            "办公PC (G7KJ2MNQ4X)"
        );
        assert_eq!(dashboard_target_label("", "192.168.1.7"), "192.168.1.7");
        assert_eq!(dashboard_target_label("   ", "192.168.1.7"), "192.168.1.7");
        assert_eq!(dashboard_target_label("same-id", "same-id"), "same-id");
        assert_eq!(dashboard_target_label("  padded  ", "x"), "padded (x)");
    }

    // claim 3 时序/多连接独立性）随目标注册表族移除——被测函数已删（grep
    // 矩阵在案）；claim 槽语义单测 `r90b_claim_server_file_tx_first_wins_
    // and_takeover` 与标签单测 `e1_target_label_matrix` 在位（保留面回归）。

    /// ∧ 本轮询生命周期未发过」触发一次；无 viewer / 剪贴板可用 / 已发过
    /// → 静默（零刷屏，静默降级语义零变化）。
    #[test]
    fn e1_headless_notice_due_matrix() {
        // 无 viewer（门控关）→ 静默（无人预期该能力，不产生日志噪声）。
        assert!(!server_clip_headless_notice_due(false, false, false));
        // 剪贴板可用（非 headless）→ 不触发。
        assert!(!server_clip_headless_notice_due(true, true, false));
        // headless + 有 viewer + 未发过 → 触发。
        assert!(server_clip_headless_notice_due(true, false, false));
        // 已发过 → once 语义（生命周期内至多一次）。
        assert!(!server_clip_headless_notice_due(true, false, true));
        assert!(!server_clip_headless_notice_due(false, true, false));
    }

    /// （`/` 分隔）+ fetchable=true；全部根外条目 = 文件名 + fetchable=false
    /// （占位仍显示，§7.2）；同板并存文本 → 文件优先（§2.6）；flags 0x04
    /// 钉死（§2.1 旧端安全形态）。
    #[test]
    fn e1_poll_roots_file_meta_relpath_and_fetchable() {
        let pid = std::process::id();
        let root = std::env::temp_dir().join(format!("k91e_root_{pid}"));
        std::fs::create_dir_all(&root).expect("create root");
        let root_c = std::fs::canonicalize(&root).expect("canonicalize root");
        let in1 = root_c.join("docs").join("a.txt");
        let in2 = root_c.join("b.bin");
        let out = std::env::temp_dir().join(format!("k91e_outside_{pid}")).join("c.txt");
        let board = e1_board(vec!(
            (&in1.to_string_lossy(), 111, false),
            (&in2.to_string_lossy(), 222, false),
            (&out.to_string_lossy(), 333, false),
        ));
        let mut st = clipboard::ClipboardSyncState::new();
        let mut io = FakeE1Board::new();
        io.file_board = Some(board);
        io.text = Some("同板并存文本（文件优先）".to_string());

        let pkts = clipboard::clip_poll_tick_roots(&mut st, 0, &mut io, true, &[root_c.clone()])
            .expect("文件沿必推元数据");
        let meta = e1_reassemble_filemeta(&pkts);
        assert!(!meta.cleared && !meta.truncated);
        assert_eq!(meta.entries.len(), 3);
        assert_eq!(
            (meta.entries[0].rel_path.as_str(), meta.entries[0].fetchable),
            ("docs/a.txt", true),
            "根内条目 = 根相对路径（/ 分隔）+ 可拉取"
        );
        assert_eq!(
            (meta.entries[1].rel_path.as_str(), meta.entries[1].fetchable),
            ("b.bin", true)
        );
        assert_eq!(
            (meta.entries[2].rel_path.as_str(), meta.entries[2].fetchable),
            ("c.txt", false),
            "全部根外 = 文件名占位 + 不可拉取（§7.2）"
        );
        assert_eq!(meta.entries[0].size, 111);
        let _ = std::fs::remove_dir_all(&root);
    }

    /// ① Text→File 推元数据 + 同板连续 3 tick（= N 会话 500ms 轮询回读
    /// 同一份清单）仅 1 次（同 sig 不重推 = 各端独立去重的服务端侧前提）；
    /// ② File→Text 推 CLEAR（cleared=true, entries=[]）恰一次沿（再 tick
    /// 无 CLEAR 重放、T1 = last_pushed 不变 → 亦无文本重推，无 ping-pong）；
    /// ③ 同清单回来 → 可再推（sig 已随 CLEAR 复位，同 sig 复现）；
    /// ④ 文本变化既有推送语义零干扰（Text 沿仍走 decide_local_push，
    /// 帧零 0x04 位）。
    #[test]
    fn e1_poll_roots_sig_dedup_clear_and_idempotent() {
        let pid = std::process::id();
        let root = std::env::temp_dir().join(format!("k91e_root8_{pid}"));
        std::fs::create_dir_all(&root).expect("create root");
        let root_c = std::fs::canonicalize(&root).expect("canonicalize root");
        let fa = root_c.join("a.txt");
        let list_a = || e1_board(vec!((&fa.to_string_lossy(), 10, false)));

        let mut st = clipboard::ClipboardSyncState::new();
        let mut io = FakeE1Board::new();
        io.text = Some("T1".to_string());
        let roots = &[root_c.clone()];

        // 基线：Other→Text 推 T1（last_pushed = T1 成立）。
        let base = clipboard::clip_poll_tick_roots(&mut st, 0, &mut io, true, roots)
            .expect("Other→Text 必推");
        assert_eq!(
            base[0].data[0] & clipboard::CLIP_FLAG_FILEMETA,
            0,
            "基线为文本帧"
        );

        // ① Text→File 推元数据；同板再 2 tick（N 会话回读同清单）→ 不重推。
        io.file_board = Some(list_a());
        let first = clipboard::clip_poll_tick_roots(&mut st, 500, &mut io, true, roots)
            .expect("Text→File 必推元数据");
        let meta = e1_reassemble_filemeta(&first);
        assert_eq!(meta.entries.len(), 1);
        let sig = clipboard::filemeta_sig(&meta);
        assert!(
            clipboard::clip_poll_tick_roots(&mut st, 1000, &mut io, true, roots).is_none(),
            "同 sig 不重推（tick 2）"
        );
        assert!(
            clipboard::clip_poll_tick_roots(&mut st, 1500, &mut io, true, roots).is_none(),
            "同 sig 不重推（tick 3）"
        );

        // ② File→Text（板仍 T1）：CLEAR 恰一次沿；再 tick 无 CLEAR 重放
        // （单次沿）且 T1 = last_pushed 未变 → 无文本重推。
        io.file_board = None;
        let clear = clipboard::clip_poll_tick_roots(&mut st, 2000, &mut io, true, roots)
            .expect("File→Text 必推 CLEAR");
        let cm = e1_reassemble_filemeta(&clear);
        assert!(cm.cleared && cm.entries.is_empty());
        // （sig 复位由 ③「同清单可再推」行为级断言——字段私有不可直读）
        assert!(
            clipboard::clip_poll_tick_roots(&mut st, 2500, &mut io, true, roots).is_none(),
            "CLEAR 单次沿：再 tick 无 CLEAR 重放、T1 未变不重推文本"
        );

        // ③ 同清单回来 → 可再推（sig 已随 CLEAR 复位；同 sig 复现）。
        io.file_board = Some(list_a());
        let again = clipboard::clip_poll_tick_roots(&mut st, 3000, &mut io, true, roots)
            .expect("CLEAR 后同清单可再推");
        assert_eq!(
            clipboard::filemeta_sig(&e1_reassemble_filemeta(&again)),
            sig,
            "同清单 = 同 sig（FNV-1a 确定性）"
        );

        // ④ 文本变化既有推送零干扰：File→Text（CLEAR）后 T1→T2 变化推送。
        io.file_board = None;
        let _ = clipboard::clip_poll_tick_roots(&mut st, 3500, &mut io, true, roots)
            .expect("File→Text 必推 CLEAR");
        io.text = Some("T2".to_string());
        let text_pkts =
            clipboard::clip_poll_tick_roots(&mut st, 4000, &mut io, true, roots)
                .expect("文本变化必推");
        assert_eq!(
            text_pkts[0].data[0] & clipboard::CLIP_FLAG_FILEMETA,
            0,
            "文本帧不得带 0x04 位（两路径互斥，§2.1）"
        );
        let _ = std::fs::remove_dir_all(&root);
    }

    /// 启停语义零变化）：get_file_meta / get_text 双读均零调用。
    #[test]
    fn e1_poll_roots_gate_closed_zero_read() {
        let mut st = clipboard::ClipboardSyncState::new();
        let mut io = FakeE1Board::new();
        io.file_board = Some(e1_board(vec!(("/fake/a.txt", 1, false))));
        io.text = Some("T".to_string());
        assert!(
            clipboard::clip_poll_tick_roots(&mut st, 0, &mut io, false, &[]).is_none(),
            "门控关恒 None"
        );
        assert_eq!(io.get_file_calls, 0, "门控关不得读文件板");
        assert_eq!(io.get_text_calls, 0, "门控关不得读文本板");
        // 门控开 → 双读各恰一次（文件先于文本，§2.4 口径）。
        assert!(clipboard::clip_poll_tick_roots(&mut st, 500, &mut io, true, &[]).is_some());
        assert_eq!(io.get_file_calls, 1);
        assert_eq!(io.get_text_calls, 1);
    }
}

// ────────────────────────────────────────────────────────────────────────────
//
// 用户 2026-09-15 22:06 实测定案：局域网 ID 首连「等待对方审批」~3 分钟才
// 出画面、重连正常——与审批无关（Admission 42ms 过、无审批环节）；首帧
// 22:06:20 已到、179 端 22:06:20.003 首次记录受控端指纹（`fingerprint
// confirmation may prompt`）、`Connection window opened` 22:08:53 才出现
// = 2m36s 全在 179 viewer 端且日志静默；重连 54ms = 指纹已记录。**真凶
// = 首次连接指纹确认对话无 OS 级前台提示**（对话是主窗内 egui 子窗、居中
// 服务端审批弹窗，客户端侧确认对话未覆盖）。
//
//   `approval_attention` 门控）：gate **首现** → 提示音（无条件一次）+
//   气泡（隐藏或非前台）+ 置前尝试（可见但非前台，尽力而为）；gate 开启
//   且可见但非前台 → 任务栏**连续闪烁**（每帧状态同步仅翻转调用，隐藏态
//   不闪=无任务栏按钮、气泡承接）；gate 应答/关闭或用户激活主窗 → 停
// - [`connect_form_status_key`]（文案键选择）：指纹 gate 开启且进行态 →
//   `connect.status.fp_confirm`（「等待本机确认对端指纹…」）覆盖决策表
//   文案（「等待对方审批…/校验中」误导纠偏）；gate 关闭或已终态 → 决策
//   表结果零变化；
// - gate 观测闭环（INFO，非纯函数不在此表内）：连接线程
//   `connect gate: fingerprint confirm — waiting (device='…')` /
//   `… — done (N ms, accepted|rejected)`（`confirm_fingerprint_blocking`
//   单点汇聚全客户端路径）+ UI 侧每 episode 一次 `— dialog rendered`。
//
// 无法单测的行为记档：`FlashWindowEx`/`SetForegroundWindow`/`MessageBeep`/
// INFO 观测行（waiting/done/dialog rendered 三行合看）+ 用户复测判据收
// 口；门控**决策**（何时调/不调）= 纯函数，本组单测全覆盖。
#[cfg(test)]
mod r118_tests {
    use super::*;

    /// 定案场景——179 主窗在桌面但用户正在操作别的应用）→ 提示音+气泡+
    /// 干等 2m36s）。
    #[test]
    fn r118_gate_newly_open_visible_not_foreground_all_channels() {
        let a = fingerprint_gate_actions(true, true, false, false);
        assert!(a.foreground_attempt, "可见但非前台必须尝试主窗置前");
        assert!(a.flash, "可见但非前台必须闪任务栏");
    }

    /// 尝试；提示音+气泡保留（气泡是隐藏态的可见通道）。foreground 在隐
    /// 藏态无意义（GetForegroundWindow 永不等隐藏窗），两值同判。
    #[test]
    fn r118_gate_newly_open_hidden_sound_balloon_only() {
        for foreground in [false, true] {
            let a = fingerprint_gate_actions(true, true, true, foreground);
            assert!(a.sound, "隐藏态首现仍有提示音（可闻通道，fg={foreground}）");
            assert!(a.balloon, "隐藏态保留托盘气泡（既有可见通道，fg={foreground}）");
            assert!(!a.flash, "隐藏窗无任务栏按钮——永不闪（fg={foreground}）");
            assert!(!a.foreground_attempt, "隐藏窗不做置前尝试（fg={foreground}）");
        }
    }

    #[test]
    fn r118_gate_newly_open_foreground_sound_only() {
        let a = fingerprint_gate_actions(true, true, false, true);
        assert!(a.sound);
        assert!(!a.balloon && !a.foreground_attempt && !a.flash, "前台态零额外通道");
    }

    /// 气泡/置前）不重复；闪烁在「可见但非前台」期间持续（连续闪直到用
    /// 户激活主窗〔转前台→停〕或 gate 关闭）。
    #[test]
    fn r118_gate_still_open_only_flash_persists() {
        let a = fingerprint_gate_actions(true, false, false, false);
        assert!(
            !a.sound && !a.balloon && !a.foreground_attempt,
            "一次性通道不得每帧重复"
        );
        assert!(a.flash, "gate 开启且可见但非前台 → 闪烁持续");
        let a = fingerprint_gate_actions(true, false, false, true);
        assert!(!a.flash, "用户激活主窗（转前台）→ 停闪");
        let a = fingerprint_gate_actions(true, false, true, false);
        assert!(!a.flash, "隐藏态 → 不闪");
    }

    #[test]
    fn r118_gate_closed_all_off() {
        for (hidden, foreground) in [(false, false), (false, true), (true, false), (true, true)] {
            let a = fingerprint_gate_actions(false, false, hidden, foreground);
            assert_eq!(
                a,
                FingerprintGateActions::default(),
                "gate 关闭 → 全通道 off（hidden={hidden}, fg={foreground}）"
            );
        }
    }

    /// 文案——「校验中」（responded 分支）与「原进度串」两形态均覆盖为
    /// `connect.status.fp_confirm`（「等待本机确认对端指纹…」）。
    #[test]
    fn r118_status_key_overrides_while_gate_open_and_busy() {
        assert_eq!(
            connect_form_status_key(true, true, Some("connect.status.verifying")),
            Some("connect.status.fp_confirm"),
            "指纹 gate 期间「校验中」误导 → 覆盖为本机确认文案"
        );
        assert_eq!(
            connect_form_status_key(true, true, None),
            Some("connect.status.fp_confirm"),
            "gate 开+进行态 → 决策表呈原进度串亦覆盖"
        );
    }

    /// → 决策表结果零变化（零回归锁）。
    #[test]
    fn r118_status_key_passthrough_when_gate_closed_or_terminal() {
        assert_eq!(
            connect_form_status_key(false, true, Some("connect.status.waiting_peer")),
            Some("connect.status.waiting_peer")
        );
        assert_eq!(connect_form_status_key(false, true, None), None);
        assert_eq!(
            connect_form_status_key(true, false, Some("connect.status.verifying")),
            Some("connect.status.verifying"),
            "gate 仍开但状态已终态（看门狗兜底）→ 不覆盖终态文案"
        );
        assert_eq!(connect_form_status_key(true, false, None), None);
    }

    /// `connect.status.fp_confirm` 状态纠偏主文案 + `connect.balloon.
    /// fingerprint` 托盘气泡正文。
    #[test]
    fn r118_new_i18n_keys_paired() {
        let find = |key: &str| {
            i18n::ALL
                .iter()
                .flat_map(|table| table.iter())
                .find(|e| e.0 == key)
                .unwrap_or_else(|| panic!("{key} key must exist"))
        };
        let e = find("connect.status.fp_confirm");
        assert_eq!(e.1, "等待本机确认对端指纹…");
        assert_eq!(e.2, "Waiting for local confirmation of the peer's fingerprint…");
        let e = find("connect.balloon.fingerprint");
        assert_eq!(
            e.1,
            "首次连接需在本机确认对端指纹——请留意主窗口的指纹确认框比对后继续"
        );
        assert_eq!(
            e.2,
            "First connection — please confirm the peer's fingerprint in the main window's dialog before continuing"
        );
    }
}

