#[cfg(test)]
mod r133_3_tests {
    use super::*;

    /// busy = 终态，`is_connect_status_terminal` 矩阵口径）时走退出清理
    /// 关窗/断连两分支在 `run_client_file_session_on_stream` 收尾收敛于
    /// `client_file_session_exit_cleanup` 单一入口，本测即该入口的帧内
    /// 覆盖退出可达性，本测钉清除语义）。持 `test_serial` 与 r113/r74e/
    /// r62/r74f 等写 `connection_status` 的测试串行。
    #[tokio::test]
    async fn file_session_exit_clears_connection_status_within_frame() {
        let _serial = crate::server_media::test_serial().lock().await;
        let terminal = "[shell] Connected to abc@192.168.1.79:59990 (transport: TCP)";
        assert!(
            is_connect_status_terminal(terminal),
        );
        *connection_status().lock().unwrap() = terminal.to_string();
        *connection_failure_detail().lock().unwrap() = Some("detail".to_string());
        // 退出路径（事件驱动清除，非 tick 时间兜底）。
        client_file_session_exit_cleanup(next_session_id());
        assert!(
            connection_status().lock().unwrap().is_empty(),
            "退出帧内必须清状态槽（无 60s 残留）"
        );
        assert!(
            connection_failure_detail().lock().unwrap().is_none(),
            "详情槽随状态同清（两槽全清单一路径）"
        );
        // 复位全局态（防泄漏进其他测试）。
        connection_status().lock().unwrap().clear();
        connection_failure_detail().lock().unwrap().take();
    }

    /// `devices.saved_` 前缀已删键全名）在**全源码树**（workspace 各 crate
    /// src 下 .rs）零命中。串值在测试体 `concat!` 动态拼接：测试体自身
    /// 口径 = 代码树；管理文档（CHANGELOG 历史条目/记录表流水行）按「只追
    /// 加不改他人行」纪律保留历史字面量，本岗新增登记一律前缀形态（记档
    /// 见交付报告）。
    #[test]
    fn leak_strings_absent_from_source_tree() {
        let leaked = concat!("81/", "81");
        let removed_key = concat!("devices.saved_", "badge");
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .expect("CARGO_MANIFEST_DIR 必在 workspace 内");
        let mut scanned = 0usize;
        let mut stack = vec![root.to_path_buf()];
        while let Some(dir) = stack.pop() {
            let Ok(entries) = std::fs::read_dir(&dir) else {
                continue;
            };
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_dir() {
                    let name = entry.file_name();
                    if name == "target" || name == ".git" || name == "node_modules" {
                        continue;
                    }
                    stack.push(path);
                } else if path.extension().is_some_and(|e| e == "rs") {
                    if let Ok(text) = std::fs::read_to_string(&path) {
                        scanned += 1;
                        assert!(
                            !text.contains(leaked),
                            "生产泄漏残留: \"{leaked}\" @ {}",
                            path.display()
                        );
                        assert!(
                            !text.contains(removed_key),
                            "已删键残留: {removed_key} @ {}",
                            path.display()
                        );
                    }
                }
            }
        }
        assert!(
            scanned > 50,
            "源码树扫描文件数异常偏少（路径漂移？）: {scanned}"
        );
    }
}

// ════════════════════════════════════════════════════════════════
// （core 侧「N 轮创建/关闭压测 = 零孤儿 headless ConPTY conhost」门禁单测
// 在 core/src/connection/shell_bridge.rs `mod tests`；此处钉 shell 会话
// ════════════════════════════════════════════════════════════════
#[cfg(test)]
mod r133_8_tests {
    use super::*;

    /// `run_client_shell_session_on_stream` 收尾清理必须调
    /// `client_file_session_exit_cleanup`（与文件会话同一入口：键控清理 +
    ///
    /// 配对提取函数体、断言收尾段（函数末 25 行）含调用。入口语义本身由
    /// 钉死，本测不重复。
    #[test]
    fn r133_8_shell_session_exit_wired_to_status_slot_clear() {
        let src =
            std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/src/lib.rs"))
                .expect("lib.rs 必读（同 crate 源）");
        let text = src.as_str();
        let start = text
            .find("async fn run_client_shell_session_on_stream(")
            .expect("run_client_shell_session_on_stream 必须存在");
        // 参数列表无花括号 → 自函数签名的首个 `{` 起花括号配对取函数体。
        let body_start = text[start..]
            .find('{')
            .map(|i| start + i)
            .expect("函数体开括号");
        let bytes = text.as_bytes();
        let mut depth = 0usize;
        let mut end = 0usize;
        let mut i = body_start;
        while i < bytes.len() {
            match bytes[i] {
                b'{' => depth += 1,
                b'}' => {
                    depth -= 1;
                    if depth == 0 {
                        end = i + 1;
                        break;
                    }
                }
                _ => {}
            }
            i += 1;
        }
        assert!(
            end > body_start + 100,
            "函数体提取异常（花括号配对失败 = 源形态漂移，人工核查）"
        );
        let body = &text[body_start..end];
        let lines: Vec<&str> = body.lines().collect();
        let tail: String = lines.iter().rev().take(25).copied().collect::<Vec<_>>().join("\n");
        assert!(
            tail.contains("client_file_session_exit_cleanup("),
        );
    }
}

