#[cfg(test)]
mod r134_2_tests {
    use super::*;
    use kirin_desk_utils::config::{Config, ConfigError};

    /// ParseError 带键 = 路径 + 出错键名（数据子串钉死；模板按语言 i18n）。
    #[test]
    fn r134_2_banner_parse_error_with_key() {
        let err = ConfigError::ParseError {
            path: std::path::PathBuf::from("C:\\cfg\\default.toml"),
            detail: "boom".into(),
            key_hint: Some("latency_trace".into()),
        };
        let text = config_invalid_banner_text(&Err(err)).expect("横幅必在");
        assert!(text.contains("C:\\cfg\\default.toml"), "含文件路径: {text}");
        assert!(text.contains("latency_trace"), "含出错键名: {text}");
    }

    /// ParseError 无键（key_hint None）= 仅路径模板（无键位占位符）。
    #[test]
    fn r134_2_banner_parse_error_no_key() {
        let err = ConfigError::ParseError {
            path: std::path::PathBuf::from("/home/u/kirin_desk/default.toml"),
            detail: "boom".into(),
            key_hint: None,
        };
        let text = config_invalid_banner_text(&Err(err)).expect("横幅必在");
        assert!(
            text.contains("/home/u/kirin_desk/default.toml"),
            "含文件路径: {text}"
        );
        // 仅路径模板形态：{0} 在、{1} 不在（键位不空悬）。
        let zh = crate::i18n::tr_lang(crate::i18n::Lang::Zh, "consent.config_invalid_banner_path");
        assert!(zh.contains("{0}") && !zh.contains("{1}"), "仅路径模板形态: {zh}");
    }

    /// 其余变体：IoError = 仅路径 / Ok = 无横幅 / 解密（无路径上下文）= 无横幅。
    #[test]
    fn r134_2_banner_other_variants() {
        let io = ConfigError::IoError {
            path: std::path::PathBuf::from("/x/y.toml"),
            source: std::io::Error::new(std::io::ErrorKind::PermissionDenied, "denied"),
        };
        let text = config_invalid_banner_text(&Err(io)).expect("IoError 横幅");
        assert!(text.contains("/x/y.toml"), "含文件路径: {text}");
        assert!(
            config_invalid_banner_text(&Ok(Config::default())).is_none(),
            "Ok 无横幅"
        );
        let dec = ConfigError::Decrypt {
            field: "tunnel.token".into(),
            reason: "bad".into(),
        };
        assert!(
            config_invalid_banner_text(&Err(dec)).is_none(),
            "解密错无路径上下文 → 无横幅（三态 tooltip 不受影响）"
        );
    }

    /// i18n 键形态：2 新键 zh/en 在位 + 占位符对应 + 与原 hint 键前句一致
    /// （「复用 consent.config_invalid_hint 语义」钉死）。
    #[test]
    fn r134_2_i18n_banner_keys_shape() {
        for lang in [crate::i18n::Lang::Zh, crate::i18n::Lang::En] {
            let full = crate::i18n::tr_lang(lang, "consent.config_invalid_banner");
            assert_ne!(full, "consent.config_invalid_banner", "缺键回退: {full:?}");
            assert!(
                full.contains("{0}") && full.contains("{1}"),
                "全量模板形态: {full:?}"
            );
            let path_only = crate::i18n::tr_lang(lang, "consent.config_invalid_banner_path");
            assert_ne!(path_only, "consent.config_invalid_banner_path", "缺键回退: {path_only:?}");
            assert!(
                path_only.contains("{0}") && !path_only.contains("{1}"),
                "仅路径模板形态: {path_only:?}"
            );
            // 语义复用：新键与原 hint 键共享同一前句（零改原键值）。
            let hint = crate::i18n::tr_lang(lang, "consent.config_invalid_hint");
            let head = if lang == crate::i18n::Lang::Zh {
                "配置文件异常"
            } else {
                "Config file is invalid"
            };
            assert!(hint.starts_with(head), "原键零改值: {hint:?}");
            assert!(full.starts_with(head), "横幅复用原键语义: {full:?}");
        }
    }
}

#[cfg(test)]
mod r134_8_tests {
    use super::*;

    // ── 共享探针常量 + 帧复刻（三场景探针与隔离目录截屏自验共用）──
    const OFFSET_Y: f32 = 24.0;
    const MEAS: f32 = 600.0; // 模拟 win.toolbar_size.x（内容自然宽）
    const EPS: f32 = 0.01;

    /// 复刻一帧（生产渲染链同式），返回 (夹取后条体矩形, Area 响应矩形)。
    /// `toolbar_pos` = Some = 拖动态滞留位置 / None = 默认态
    /// （生产 `win.toolbar_pos` 同语义）。
    fn probe_frame(
        ctx: &egui::Context,
        win_size: egui::Vec2,
        toolbar_pos: Option<egui::Pos2>,
        area_id: &str,
    ) -> (egui::Rect, egui::Rect) {
        let mut raw = egui::RawInput::default();
        raw.screen_rect = Some(egui::Rect::from_min_size(egui::Pos2::ZERO, win_size));
        let mut out: Option<(egui::Rect, egui::Rect)> = None;
        let _ = ctx.run(raw, |ctx| {
            let screen = ctx.screen_rect();
            // 生产纯函数链同式（lib.rs 工具栏渲染段）。
            let bounds = egui::Rect::from_min_max(egui::pos2(0.0, OFFSET_Y), screen.max);
            let bar_w = toolbar_bar_width(MEAS, screen.width());
            let bar_size = egui::vec2(bar_w, TOOLBAR_BAR_HEIGHT);
            let min0 = toolbar_pos.unwrap_or_else(|| egui::pos2(0.0, OFFSET_Y));
            let bar_rect = toolbar_live_clamp(min0, bar_size, bounds);
            let resp = egui::Area::new(egui::Id::new(area_id))
                .order(egui::Order::Foreground)
                .anchor(
                    egui::Align2::LEFT_TOP,
                    [bar_rect.min.x, bar_rect.min.y],
                )
                .show(ctx, |ui| {
                    ui.set_min_size(bar_rect.size());
                    ui.set_max_size(bar_rect.size());
                    ui.painter()
                        .rect_filled(ui.max_rect(), 0.0, egui::Color32::WHITE);
                    egui::Frame::none()
                        .inner_margin(egui::Margin::symmetric(6.0, 2.0))
                        .show(ui, |ui| {
                            ui.horizontal(|ui| {
                                // 内容形态等价：10×36px 按钮（自然宽 396 +
                                // 内边距 12 < 600 = 正常窗下内容不溢出钉死宽
                                // → 响应矩形 == 夹取矩形）。
                                for _ in 0..10 {
                                    ui.add(
                                        egui::Button::new("")
                                            .min_size(egui::vec2(36.0, 32.0)),
                                    );
                                }
                            });
                        });
                });
            out = Some((bar_rect, resp.response.rect));
        });
        out.expect("ctx.run 帧必执行")
    }

    /// 每帧把条体矩形夹进窗体可视区：
    /// ① 正常窗 = 原样 no-op（零观感变化）；
    /// ② 拖动态位置窗外（右/左/上）= 收回界内（不脱锚）；
    /// ③ 条体宽于窗宽 → 原点钉左缘、右缘裁到窗缘（不出窗，egui constrain
    ///    同口径）；
    /// ④ 短窗（可视高不足条高）→ 下缘裁到窗底（不出窗）；
    /// ⑤ 退化 0×0 bounds（最小化极端帧）→ 收敛为 bounds.min 锚点矩形
    ///    （不 panic、不 NaN）；
    /// ⑥ 默认原点 (0, offset_y) 亦过同一夹取（正常窗 = 原样，默认态与
    ///    拖动态同口径）。
    #[test]
    fn r134_8_live_clamp_matrix() {
        let b = egui::Rect::from_min_max(egui::pos2(0.0, 24.0), egui::pos2(1440.0, 900.0));
        // ① 正常：(0,24)+(600,40) 原样。
        let r = toolbar_live_clamp(egui::pos2(0.0, 24.0), egui::vec2(600.0, 40.0), b);
        assert_eq!(
            r,
            egui::Rect::from_min_max(egui::pos2(0.0, 24.0), egui::pos2(600.0, 64.0))
        );
        // ② 拖出窗外（右）→ 收回右缘内；左/上越界 → 钉可视区原点。
        let r = toolbar_live_clamp(egui::pos2(2000.0, 24.0), egui::vec2(600.0, 40.0), b);
        assert_eq!(r.min, egui::pos2(840.0, 24.0), "拖出窗外 → 收回界内（不脱锚）");
        assert!(r.max.x <= b.max.x + 1e-6, "右缘不出窗");
        let r = toolbar_live_clamp(egui::pos2(-500.0, -100.0), egui::vec2(600.0, 40.0), b);
        assert_eq!(r.min, egui::pos2(0.0, 24.0), "左/上越界 → 钉可视区原点");
        // ③ 条体宽于窗宽：原点钉左缘，右缘裁到窗缘（不出窗）。
        let r = toolbar_live_clamp(egui::pos2(0.0, 24.0), egui::vec2(2000.0, 40.0), b);
        assert_eq!(
            r,
            egui::Rect::from_min_max(egui::pos2(0.0, 24.0), egui::pos2(1440.0, 64.0))
        );
        // ④ 短窗（可视高 16 < 条高 40）：下缘裁到窗底（不出窗）。
        let b_short = egui::Rect::from_min_max(egui::pos2(0.0, 24.0), egui::pos2(1440.0, 40.0));
        let r = toolbar_live_clamp(egui::pos2(0.0, 24.0), egui::vec2(600.0, 40.0), b_short);
        assert_eq!(r.max.y, 40.0, "短窗 → 下缘裁到窗底（不出窗）");
        assert_eq!(r.min, egui::pos2(0.0, 24.0));
        // ⑤ 退化 0×0 bounds（最小化极端帧）→ 收敛为 bounds.min 锚点矩形。
        let b0 = egui::Rect::from_min_max(egui::pos2(5.0, 5.0), egui::pos2(5.0, 5.0));
        let r = toolbar_live_clamp(egui::pos2(0.0, 0.0), egui::vec2(100.0, 40.0), b0);
        assert_eq!(r.min, egui::pos2(5.0, 5.0));
        assert_eq!(r.max, egui::pos2(5.0, 5.0));
        assert!(
            r.min.x.is_finite() && r.min.y.is_finite() && r.max.x.is_finite() && r.max.y.is_finite(),
            "退化 bounds 不产生 NaN/inf"
        );
        // ⑥ 默认原点 (0, offset_y) 过同一夹取（正常窗 = 原样）。
        let r = toolbar_live_clamp(egui::pos2(0.0, 24.0), egui::vec2(600.0, 40.0), b);
        assert_eq!(r.min, egui::pos2(0.0, 24.0));
    }

    /// 其后每 60 可见帧一对（60fps ≈ 1 对/秒）；计数严格逐可见帧 +1；
    /// 0 起首调 = 第 1 帧（发）。
    #[test]
    fn r134_8_tbw_step_pinned() {
        let mut n = 0u64;
        let mut emits = Vec::new();
        for i in 1..=120u64 {
            let (next, emit) = r134_tbw_step(n);
            n = next;
            assert_eq!(n, i, "计数逐可见帧 +1（frame {i}）");
            emits.push(emit);
        }
        // 全量钉死：frame ≤3 发；4..59 不发；60 发；61..119 不发；120 发。
        for i in 0..120usize {
            let frame = (i + 1) as u64;
            let want = frame <= 3 || frame % 60 == 0;
            assert_eq!(emits[i], want, "frame {frame} emit={want}");
        }
        assert!(emits[0] && emits[1] && emits[2]);
        assert!(!emits[3]);
        assert!(emits[59]);
        assert!(!emits[60]);
        assert!(emits[119]);
    }

    /// 链逐字复刻：`egui::Area` + `anchor(LEFT_TOP, 夹取后原点)` +
    /// `set_min/max_size(夹取后矩形 size)` + Frame(6,2) + horizontal +
    /// 按钮组；几何全走生产纯函数 [`toolbar_live_clamp`]/
    /// [`toolbar_bar_width`]），三场景钉死「不脱锚、不出窗」判据：
    /// - S1 **移动**：窗体移动不改屏内尺寸（`screen_rect` 大小不变）→
    ///   逐帧条体矩形恒等 = 窗内局部坐标不变（不滞留全局坐标 = 不脱锚）；
    /// - S2 **缩放收窄**：拖动态滞留位置（旧窗坐标，09-22 截图症状形态）
    ///   被当帧重夹取收回新窗内（不脱锚、不出窗）；
    /// - S3 **最小化/还原**：最小化极端帧（1×1，`screen_rect` 退化；
    ///   Windows 实际冻结旧尺寸 = 更轻形态）条体矩形不越窗、无 NaN；
    ///   还原后默认原点重算回 (0, offset_y)（不滞留旧窗坐标）。
    /// 每帧判据：① 条体矩形（填充/锚定区）不越窗（右缘/下缘不出窗 = 用户
    /// 症状轴）；② Area 响应原点 == 夹取后原点（anchor 精确，不脱锚）；
    /// ③ 正常窗（内容 ≤ 钉死宽）响应矩形 == 夹取矩形（底色 = 夹取区，
    /// 零越窗）。
    #[test]
    fn r134_8_probe_three_scenarios() {
        /// 正常窗判据：① 条体矩形 ⊆ 窗矩形（不出窗）；② 响应原点 == 夹取
        /// 原点（不脱锚）；③ 内容不溢出 → 响应矩形 == 夹取矩形（底色 =
        /// 夹取区，零越窗）；④ 默认态原点 = (0, offset_y)（活窗重算）。
        fn assert_normal(
            label: &str,
            bar: egui::Rect,
            resp: egui::Rect,
            win_size: egui::Vec2,
            expect_default_origin: bool,
        ) {
            let win = egui::Rect::from_min_size(egui::Pos2::ZERO, win_size);
            assert!(
                bar.min.x >= win.min.x - EPS
                    && bar.min.y >= win.min.y - EPS
                    && bar.max.x <= win.max.x + EPS
                    && bar.max.y <= win.max.y + EPS,
                "{label}: 条体矩形 {bar:?} ⊆ 窗矩形 {win:?}（不出窗）"
            );
            assert!(
                (bar.min.x - resp.min.x).abs() < EPS && (bar.min.y - resp.min.y).abs() < EPS,
                "{label}: Area 原点 {resp:?} == 夹取原点 {bar:?}（不脱锚）"
            );
            assert!(
                (bar.left_top() - resp.left_top()).length() < EPS
                    && (bar.right_bottom() - resp.right_bottom()).length() < EPS,
                "{label}: 响应矩形 == 夹取矩形（底色 = 夹取区，零越窗）: {bar:?} vs {resp:?}"
            );
            if expect_default_origin {
                assert_eq!(
                    bar.min,
                    egui::pos2(0.0, OFFSET_Y),
                    "{label}: 默认态原点 = (0, offset_y)（活窗重算）"
                );
            }
        }

        // ── S1 移动：同尺寸两帧（窗体移动不改 screen_rect 大小）→ 逐帧
        // 条体矩形恒等 = 窗内局部坐标不变（不滞留全局坐标 = 不脱锚）。
        let ctx1 = egui::Context::default();
        let (bar_a, resp_a) = probe_frame(&ctx1, egui::vec2(1440.0, 900.0), None, "r134_8_s1");
        assert_normal("S1 帧1", bar_a, resp_a, egui::vec2(1440.0, 900.0), true);
        let (bar_b, resp_b) = probe_frame(&ctx1, egui::vec2(1440.0, 900.0), None, "r134_8_s1");
        assert_normal("S1 帧2（窗已移动）", bar_b, resp_b, egui::vec2(1440.0, 900.0), true);
        assert_eq!(bar_a, bar_b, "S1: 移动 → 逐帧条体矩形恒等（不脱锚）");
        assert_eq!(resp_a, resp_b, "S1: 移动 → Area 响应矩形恒等");

        // ── S2 缩放收窄：拖动态滞留位置 (1300,24)（旧 1440 窗贴右缘 =
        // 09-22 截图症状形态）→ 缩到 900 宽窗后被当帧重夹取收回 (300,24)
        // ⊆ 新窗（不脱锚、不出窗）。
        let ctx2 = egui::Context::default();
        let (bar_c, resp_c) = probe_frame(
            &ctx2,
            egui::vec2(1440.0, 900.0),
            Some(egui::pos2(1300.0, OFFSET_Y)),
            "r134_8_s2",
        );
        assert_normal("S2 帧1（旧窗贴右缘）", bar_c, resp_c, egui::vec2(1440.0, 900.0), false);
        assert_eq!(
            bar_c.min.x, 840.0,
            "S2 帧1: 1440 窗内拖动态位置 1300 → 夹取 840（贴右缘，症状形态锚）"
        );
        let (bar_d, resp_d) = probe_frame(
            &ctx2,
            egui::vec2(900.0, 500.0),
            Some(egui::pos2(1300.0, OFFSET_Y)),
            "r134_8_s2",
        );
        assert_normal("S2 帧2（收窄后）", bar_d, resp_d, egui::vec2(900.0, 500.0), false);
        assert_eq!(
            bar_d.min.x,
            900.0 - 600.0,
            "S2: 滞留旧窗坐标 → 当帧收回新窗右缘内（不脱锚）"
        );
        // S2 默认态：原点仍按活窗重算 (0, offset_y)（旧坐标不泄漏默认态）。
        let (bar_e, resp_e) = probe_frame(&ctx2, egui::vec2(900.0, 500.0), None, "r134_8_s2_def");
        assert_normal("S2 默认态", bar_e, resp_e, egui::vec2(900.0, 500.0), true);

        // ── S3 最小化/还原：最小化极端帧（1×1；Windows 实际冻结旧尺寸 =
        // 更轻形态）→ 条体矩形不越窗、全有限（不出窗）；还原后默认原点
        // 重算回 (0, offset_y) = 不滞留旧窗坐标。
        let ctx3 = egui::Context::default();
        let (bar_p, resp_p) = probe_frame(&ctx3, egui::vec2(1440.0, 900.0), None, "r134_8_s3");
        assert_normal("S3 最小化前", bar_p, resp_p, egui::vec2(1440.0, 900.0), true);
        // 最小化极端帧判据 = 不越窗（右缘不出窗 = 用户症状轴）+ 全有限。
        // egui Area 自身 constrain 在上帧尺寸 > 退化窗时把锚点收至窗原点
        // （y 轴例外已核：1×1 窗无可视内容，`clip_rect`=屏缘裁切 = 最小化
        // 窗口不可见 = 定义内行为），故本帧 y 轴锚点等式不钉。
        let (bar_m, resp_m) = probe_frame(&ctx3, egui::vec2(1.0, 1.0), None, "r134_8_s3");
        assert!(
            bar_m.min.x >= -EPS
                && bar_m.min.y >= -EPS
                && bar_m.max.x <= 1.0 + EPS
                && bar_m.width() <= 1.0 + EPS,
            "S3 最小化: 条体矩形不越窗（右缘不出窗）: {bar_m:?}"
        );
        assert!(
            bar_m.min.x.is_finite() && bar_m.min.y.is_finite()
                && bar_m.max.x.is_finite() && bar_m.max.y.is_finite(),
            "S3 最小化: 退化帧无 NaN/inf: {bar_m:?}"
        );
        assert!(
            resp_m.min.x >= -EPS && resp_m.min.x <= 1.0 + EPS,
            "S3 最小化: Area 锚点 x 仍在窗内: {resp_m:?}"
        );
        let (bar_r, resp_r) = probe_frame(&ctx3, egui::vec2(1440.0, 900.0), None, "r134_8_s3");
        assert_normal("S3 还原", bar_r, resp_r, egui::vec2(1440.0, 900.0), true);
        assert_eq!(
            bar_r, bar_p,
            "S3: 还原 → 默认原点重算 (0, offset_y)（不滞留旧窗坐标 = 与最小化前恒等）"
        );
    }

    /// 横排，headless 真实 egui 几何（生产纯函数链）+ 手工软件光栅化（窗口
    /// 背景/conn banner/条体 fill/按钮组/窗框；PNG 落 docs **不入库**）：
    /// ① 症状形态（修前）：拖动态滞留位 + 滞留 121px 尺寸 → fill = 右缘
    ///    窄条 + 内容溢出 fill 外 + 最右按钮贴窗缘被裁 = 09-22 复测截图
    ///    症状复现锚；
    /// ② S2 缩放收窄（修后）：滞留旧窗坐标被当帧收回新窗内，fill = 夹取
    ///    矩形 ⊆ 窗（不出窗）；
    /// ③ S1 移动（修后）：窗内局部几何不变（不脱锚）；
    /// ④ S3 最小化/还原（修后）：默认原点重算 (0, offset_y)，与 ③ 同形
    ///    （不滞留旧窗坐标）。
    /// ②③④ 面板真实 egui Area 响应矩形 == 所绘条体矩形（几何 = 生产链
    /// 输出；光栅化仅供观感初验，硬判据由上方三场景探针钉死）。
    #[test]
    fn r134_8_screenshot_dump() {
        let eps = EPS;
        /// 手工光栅化一个面板（窗口背景 + conn banner + 条体 fill + 10 按钮
        /// + 窗框；条体 fill alpha = 生产同口径 `TOOLBAR_BASE_ALPHA`）。
        fn render_panel(win: egui::Vec2, bar: egui::Rect) -> image::RgbaImage {
            let (w, h) = (win.x as u32, win.y as u32);
            let mut img =
                image::RgbaImage::from_pixel(w, h, image::Rgba([58, 58, 66, 255]));
            let blend = |img: &mut image::RgbaImage,
                         r: egui::Rect,
                         c: image::Rgba<u8>| {
                let x0 = r.min.x.max(0.0).floor() as i32;
                let y0 = r.min.y.max(0.0).floor() as i32;
                let x1 = r.max.x.min(win.x).ceil() as i32;
                let y1 = r.max.y.min(win.y).ceil() as i32;
                for y in y0.max(0)..y1.min(h as i32) {
                    for x in x0.max(0)..x1.min(w as i32) {
                        let a = c[3] as f32 / 255.0;
                        let px = img.get_pixel(x as u32, y as u32);
                        img.put_pixel(
                            x as u32,
                            y as u32,
                            image::Rgba([
                                (c[0] as f32 * a + px[0] as f32 * (1.0 - a)) as u8,
                                (c[1] as f32 * a + px[1] as f32 * (1.0 - a)) as u8,
                                (c[2] as f32 * a + px[2] as f32 * (1.0 - a)) as u8,
                                255,
                            ]),
                        );
                    }
                }
            };
            // conn banner（顶 24px 状态条）+ 下沿线。
            blend(
                &mut img,
                egui::Rect::from_min_max(egui::Pos2::ZERO, egui::pos2(win.x, OFFSET_Y)),
                image::Rgba([38, 38, 46, 255]),
            );
            blend(
                &mut img,
                egui::Rect::from_min_max(
                    egui::pos2(0.0, OFFSET_Y - 1.0),
                    egui::pos2(win.x, OFFSET_Y),
                ),
                image::Rgba([74, 74, 84, 255]),
            );
            // LIGHT bg = #F5F5F7 = (245,245,247)）。
            blend(
                &mut img,
                bar,
                image::Rgba([245, 245, 247, TOOLBAR_BASE_ALPHA]),
            );
            // 10 按钮（探针同形态：36×32、间距 4、内边距 6/2；越窗缘部分
            // 由 blend 裁切 = 症状①的「被裁」视觉）。
            let border = image::Rgba([150, 152, 158, 255]);
            for i in 0..10 {
                let btn = egui::Rect::from_min_size(
                    egui::pos2(bar.min.x + 6.0 + i as f32 * 40.0, bar.min.y + 4.0),
                    egui::vec2(36.0, 32.0),
                );
                blend(&mut img, btn, image::Rgba([206, 208, 216, 255]));
                blend(
                    &mut img,
                    egui::Rect::from_min_max(btn.min, egui::pos2(btn.max.x, btn.min.y + 1.0)),
                    border,
                );
                blend(
                    &mut img,
                    egui::Rect::from_min_max(egui::pos2(btn.min.x, btn.max.y - 1.0), btn.max),
                    border,
                );
                blend(
                    &mut img,
                    egui::Rect::from_min_max(btn.min, egui::pos2(btn.min.x + 1.0, btn.max.y)),
                    border,
                );
                blend(
                    &mut img,
                    egui::Rect::from_min_max(egui::pos2(btn.max.x - 1.0, btn.min.y), btn.max),
                    border,
                );
            }
            // 窗框（2px）。
            let wf = image::Rgba([130, 132, 140, 255]);
            blend(&mut img, egui::Rect::from_min_max(egui::Pos2::ZERO, egui::pos2(win.x, 2.0)), wf);
            blend(
                &mut img,
                egui::Rect::from_min_max(egui::pos2(0.0, win.y - 2.0), egui::pos2(win.x, win.y)),
                wf,
            );
            blend(&mut img, egui::Rect::from_min_max(egui::Pos2::ZERO, egui::pos2(2.0, win.y)), wf);
            blend(
                &mut img,
                egui::Rect::from_min_max(egui::pos2(win.x - 2.0, 0.0), egui::pos2(win.x, win.y)),
                wf,
            );
            img
        }

        // ① 症状形态（修前）：滞留尺寸 121 + 拖动位 1311（09-22 截图形态）
        // → 修前几何 = 仅原点夹取 + 原尺寸 rect（fill 窄条）+ 内容溢出。
        let w0 = egui::vec2(1440.0, 900.0);
        let bounds0 =
            egui::Rect::from_min_max(egui::pos2(0.0, OFFSET_Y), egui::pos2(w0.x, w0.y));
        let stale_size = egui::vec2(121.0, TOOLBAR_BAR_HEIGHT);
        let bar0 = egui::Rect::from_min_size(
            toolbar_clamp_pos(egui::pos2(1311.0, OFFSET_Y), stale_size, bounds0),
            stale_size,
        );
        assert_eq!(bar0, egui::Rect::from_min_max(egui::pos2(1311.0, OFFSET_Y), egui::pos2(1432.0, 64.0)), "① 症状形态锚（修前几何）");
        let p0 = render_panel(w0, bar0);

        // ② S2 缩放收窄（修后）：滞留旧窗坐标 (1300,24) → 当帧收回 900 窗内。
        let w1 = egui::vec2(900.0, 500.0);
        let (bar1, resp1) = probe_frame(
            &egui::Context::default(),
            w1,
            Some(egui::pos2(1300.0, OFFSET_Y)),
            "r134_8_shot_s2",
        );
        assert!(
            (bar1.left_top() - resp1.left_top()).length() < eps
                && (bar1.right_bottom() - resp1.right_bottom()).length() < eps,
            "② 真实 egui 响应矩形 == 所绘条体矩形: {bar1:?} vs {resp1:?}"
        );
        let p1 = render_panel(w1, bar1);

        // ③ S1 移动（修后）：默认原点 (0, offset_y)（窗内局部几何）。
        let (bar2, resp2) = probe_frame(
            &egui::Context::default(),
            w0,
            None,
            "r134_8_shot_s1",
        );
        assert!(
            (bar2.left_top() - resp2.left_top()).length() < eps
                && (bar2.right_bottom() - resp2.right_bottom()).length() < eps,
            "③ 真实 egui 响应矩形 == 所绘条体矩形: {bar2:?} vs {resp2:?}"
        );
        let p2 = render_panel(w0, bar2);

        // ④ S3 最小化/还原（修后）：与 ③ 同形（默认原点重算 = 无滞留）。
        let (bar3, resp3) = probe_frame(
            &egui::Context::default(),
            w0,
            None,
            "r134_8_shot_s3",
        );
        assert!(
            (bar3.left_top() - resp3.left_top()).length() < eps
                && (bar3.right_bottom() - resp3.right_bottom()).length() < eps,
            "④ 真实 egui 响应矩形 == 所绘条体矩形: {bar3:?} vs {resp3:?}"
        );
        assert_eq!(bar3, bar2, "④ 还原 == ③（默认原点重算，不滞留旧窗坐标）");
        let p3 = render_panel(w0, bar3);

        // 横排合成：1/3 降采样 + 12px 缝 + 8px 外边（总 1792×316）。
        let mut panels = vec![p0, p1, p2, p3];
        let mut xs = 8u32;
        let row_w = (8 * 2 + 1440 / 3 * 3 + 900 / 3 + 12 * 3) as u32;
        let row_h = (900 / 3 + 16) as u32;
        let mut row = image::RgbaImage::from_pixel(row_w, row_h, image::Rgba([30, 30, 34, 255]));
        for p in panels.drain(..) {
            let scaled: image::RgbaImage = image::imageops::resize(
                &p,
                p.width() / 3,
                p.height() / 3,
                image::imageops::FilterType::Lanczos3,
            );
            image::GenericImage::copy_from(&mut row, &scaled, xs, 8)
                .expect("横排合成不越界");
            xs += scaled.width() + 12;
        }
        let out_path = "E:/projects_rd/docs/r134_8_clamp_sandbox.png";
        row.save(out_path).expect("PNG 落盘");
        assert!(std::path::Path::new(out_path).is_file(), "截屏在位");
    }
}

#[cfg(test)]
mod r135_3_tests {
    use super::*;

    /// （RTR 段生产序，11 件 = 生产 Desktop 展开态全部工具；音频门开态 =
    /// 两音频钮在位；隐私菜单 = idle 文案；显示 combo = 显示列表非空形态）。
    /// ——12 → 11 件（生产移除后探针必须同步，否则门禁自证失效）。
    fn r135_3_toolbar_inventory() -> Vec<&'static str> {
        vec![
            "collapse",       // ▁ 收缩（Hidden 浮现态 = 📌，同位）
            "hide",           // 🙈 隐藏
            "display_combo",  // 🖥 显示器下拉（ComboBox，宽 170，TOP 带）
            "display_refresh",// ⟳ 显示器刷新
            "display_mode",   // 显示模式（menu_button，文案 = 当前档）
            "special_keys",   // 🔑 特殊键面板
            "audio_play",     // 🔊/🔇 播放音频
            "mic",            // 🎙️/🎤 麦克风
            // 摘除——Desktop 工具栏 12 → 11 件。
            "privacy",        // 隐私模式（menu_button）
            "fullscreen",     // ⛶/▣ 全屏（用户点名「消失不见」工具）
            "disconnect",     // ✖ 断开
        ]
    }

    /// 一帧复刻（生产渲染链同形：Area→钉宽（决策宽）→Frame(6,2)→
    /// horizontal→左段（grip ≡）→`with_layout(RTR)`→11 件→RTR 子 ui 末游标
    /// 闭包内捕获→生产换算式 [`hover_hint::toolbar_content_width`]）。
    /// `pin_band` = combo TOP 带分配宽：修后形态 = `R135_3_DISPLAY_COMBO_W`；
    /// 修前症状形态 = `f32::INFINITY`（哨兵 = 取 `available_size_before_wrap().x`
    /// 全宽，修前生产实参原样）。
    /// 返回 (本帧实测, 11 件具名按钮矩形〔RTR 生产序〕, RTR 末游标）。
    fn r135_3_probe_frame(
        ctx: &egui::Context,
        win_w: f32,
        bar_w: f32,
        pin_band: f32,
        id: &str,
    ) -> (f32, Vec<(String, egui::Rect)>, Option<f32>) {
        let mut raw = egui::RawInput::default();
        raw.screen_rect = Some(egui::Rect::from_min_size(
            egui::Pos2::ZERO,
            egui::vec2(win_w, 300.0),
        ));
        let mut meas = f32::NAN;
        let mut rects: Vec<(String, egui::Rect)> = Vec::new();
        let mut rtr_end: Option<f32> = None;
        let _ = ctx.run(raw, |ctx| {
            egui::Area::new(egui::Id::new(format!("r135_3_{id}")))
                .order(egui::Order::Foreground)
                .anchor(egui::Align2::LEFT_TOP, [0.0, 0.0])
                .show(ctx, |ui| {
                    ui.set_min_size(egui::vec2(bar_w, TOOLBAR_BAR_HEIGHT));
                    ui.set_max_size(egui::vec2(bar_w, TOOLBAR_BAR_HEIGHT));
                    egui::Frame::none()
                        .inner_margin(egui::Margin::symmetric(6.0, 2.0))
                        .show(ui, |ui| {
                            ui.horizontal(|ui| {
                                // 左段（生产形态：grip ≡）。
                                ui.add(egui::Label::new("≡"));
                                let left_end_x = ui.cursor().min.x;
                                ui.with_layout(
                                    egui::Layout::right_to_left(egui::Align::Center),
                                    |ui| {
                                        let theme = &crate::theme::Theme::LIGHT;
                                        rects.push((
                                            "collapse".to_string(),
                                            crate::widgets::toolbar_button(ui, theme, "▁", "t").rect,
                                        ));
                                        rects.push((
                                            "hide".to_string(),
                                            crate::widgets::toolbar_button(ui, theme, "🙈", "t").rect,
                                        ));
                                        // 显示 ComboBox（生产同形：TOP 带 +
                                        // padding override + 宽 170）。
                                        let sel_text = "🖥 显示器 A".to_string();
                                        let saved_pad = ui.spacing().button_padding;
                                        let text_h = ui.ctx().fonts(|f| {
                                            f.layout(
                                                sel_text.to_string(),
                                                egui::TextStyle::Button.resolve(ui.style()),
                                                egui::Color32::WHITE,
                                                f32::INFINITY,
                                            )
                                            .size()
                                            .y
                                        });
                                        ui.spacing_mut().button_padding = egui::vec2(
                                            saved_pad.x,
                                            (16.0 - text_h / 2.0).max(saved_pad.y),
                                        );
                                        let band_w = if pin_band.is_infinite() {
                                            ui.available_size_before_wrap().x
                                        } else {
                                            pin_band
                                        };
                                        let combo_rect = ui
                                            .allocate_ui_with_layout(
                                                egui::vec2(band_w, ui.available_size_before_wrap().y),
                                                egui::Layout::left_to_right(egui::Align::TOP),
                                                |ui| {
                                                    let mut sel = 0usize;
                                                    egui::ComboBox::from_id_source(format!("r135_3_combo_{id}"))
                                                        .selected_text(&sel_text)
                                                        .width(R135_3_DISPLAY_COMBO_W)
                                                        .show_ui(ui, |ui| {
                                                            ui.selectable_value(
                                                                &mut sel,
                                                                0,
                                                                "显示器 A 1920×1080 [主屏]",
                                                            );
                                                        })
                                                        .response
                                                        .rect
                                                },
                                            )
                                            .response
                                            .rect;
                                        ui.spacing_mut().button_padding = saved_pad;
                                        rects.push(("display_combo".to_string(), combo_rect));
                                        rects.push((
                                            "display_refresh".to_string(),
                                            crate::widgets::toolbar_button(ui, theme, "⟳", "t").rect,
                                        ));
                                        rects.push((
                                            "display_mode".to_string(),
                                            ui.menu_button("流畅", |_ui| {}).response.rect,
                                        ));
                                        rects.push((
                                            "special_keys".to_string(),
                                            crate::widgets::toolbar_button(ui, theme, "🔑", "t").rect,
                                        ));
                                        rects.push((
                                            "audio_play".to_string(),
                                            crate::widgets::toolbar_button(ui, theme, "🔊", "t").rect,
                                        ));
                                        rects.push((
                                            "mic".to_string(),
                                            crate::widgets::toolbar_button(ui, theme, "🎤", "t").rect,
                                        ));
                                        // 传输队列面板钮）随生产移除同步摘除。
                                        rects.push((
                                            "privacy".to_string(),
                                            ui.menu_button("隐私模式", |_ui| {}).response.rect,
                                        ));
                                        rects.push((
                                            "fullscreen".to_string(),
                                            crate::widgets::toolbar_button(ui, theme, "⛶", "t").rect,
                                        ));
                                        rects.push((
                                            "disconnect".to_string(),
                                            crate::widgets::toolbar_button(ui, theme, "✖", "t").rect,
                                        ));
                                        // RTR 子 ui 末游标（闭包内末端取，生产同式）。
                                        rtr_end = Some(ui.cursor().max.x);
                                    },
                                );
                                let sp = ui.spacing().item_spacing.x;
                                meas = hover_hint::toolbar_content_width(
                                    bar_w,
                                    TOOLBAR_GROUP_GAP,
                                    left_end_x - sp,
                                    rtr_end.unwrap_or(f32::NAN) + sp,
                                );
                            });
                        });
                });
        });
        (meas, rects, rtr_end)
    }

    /// 三帧收敛驱动（生产同式：f1 = 未实测哨兵→全宽过渡帧；f2 = 决策(f1 实测)；
    /// f3 = 决策(f2 实测)，断言对象 = f2/f3）。
    /// 返回 (m1, m2, m3, f3 决策宽, f3 按钮矩形)。
    fn r135_3_run(
        win_w: f32,
        pin_band: f32,
        id: &str,
    ) -> (f32, f32, f32, f32, Vec<(String, egui::Rect)>) {
        let ctx = egui::Context::default();
        let mut bar = win_w;
        let mut m1 = f32::NAN;
        let mut m2 = f32::NAN;
        let mut m3 = f32::NAN;
        let mut bar3 = win_w;
        let mut rects: Vec<(String, egui::Rect)> = Vec::new();
        for i in 0..3u32 {
            let (m, r, _) = r135_3_probe_frame(&ctx, win_w, bar, pin_band, id);
            match i {
                0 => m1 = m,
                1 => m2 = m,
                _ => {
                    m3 = m;
                    rects = r;
                }
            }
            bar = toolbar_bar_width(toolbar_measured_store(Some(m)), win_w);
            if i == 2 {
                bar3 = bar;
            }
        }
        (m1, m2, m3, bar3, rects)
    }

    /// 探针——全量 11 工具形态下断言实测管道产出**内容自然宽**、决策收敛内容
    /// 宽、全量工具在位可见（含全屏）：
    /// (a) f2/f3 实测零回跳（与决策宽无关 = 结构前提）；
    /// (b) 实测 < 窗宽（960）且 > 1.0（非未实测哨兵、非全宽拉伸值）；
    /// (c) f3 决策宽 = 实测（±1px）且 ≠ 全宽（「不再恒最大」）；
    /// (d) 11 件具名按钮矩形全 ⊆ 条体矩形（工具清单在位 + 渲染可见，
    ///     无越条裁剪；顺序 = 生产序）；
    /// (e) combo 与邻钮 ⟳ 相邻（gap ≈ item_spacing，RTR 流未被带撑断）；
    /// (f) combo 宽 = 170（宽度口径钉死）。
    #[test]
    fn r135_3_probe_fixed_flow_content_width() {
        let win = 960.0;
        let (_m1, m2, m3, bar3, rects) = r135_3_run(win, R135_3_DISPLAY_COMBO_W, "fixed");
        assert!(m2.is_finite() && m2 > 1.0, "f2 实测须有限 >1.0: {m2}");
        assert!((m2 - m3).abs() < 1e-3, "f2/f3 实测零回跳: {m2} vs {m3}");
        assert!(
            m3 < win,
            "实测 = 内容自然宽 < 窗宽（非全宽拉伸值）: {m3} vs {win}"
        );
        assert!(
            (bar3 - m3).abs() < 1.0,
            "f3 决策宽 = 内容自然宽（±1px）: {bar3} vs {m3}"
        );
        assert!(
            bar3 < win - 1.0,
            "决策 ≠ 全宽（用户「不再恒最大」）: {bar3} vs {win}"
        );
        let bar_rect = egui::Rect::from_min_size(
            egui::Pos2::ZERO,
            egui::vec2(bar3, TOOLBAR_BAR_HEIGHT),
        );
        let expected = r135_3_toolbar_inventory();
        assert_eq!(rects.len(), expected.len(), "工具清单件数 = 11");
        let got: Vec<&str> = rects.iter().map(|(n, _)| n.as_str()).collect();
        assert_eq!(got, expected, "工具清单生产序在位（含全屏）");
        for (name, r) in &rects {
            assert!(
                r.min.x >= bar_rect.min.x - 0.5
                    && r.max.x <= bar_rect.max.x + 0.5
                    && r.min.y >= bar_rect.min.y - 0.5
                    && r.max.y <= bar_rect.max.y + 0.5,
                "工具 {name} 矩形 {r:?} ⊆ 条体矩形 {bar_rect:?}（在位且可见，无裁剪）"
            );
        }
        // (e) combo 与邻钮 ⟳ 相邻（RTR 流未被带撑断）。
        let combo = rects.iter().find(|(n, _)| n == "display_combo").unwrap().1;
        let refresh = rects.iter().find(|(n, _)| n == "display_refresh").unwrap().1;
        assert!(
            (combo.min.x - refresh.max.x).abs() < 12.0,
            "combo 与邻钮 ⟳ 相邻（gap ≈ 间距）: {combo:?} vs {refresh:?}"
        );
        // (f) combo 宽 = 170 口径。
        assert!(
            (combo.width() - R135_3_DISPLAY_COMBO_W).abs() < 0.5,
            "combo 宽 = 170（宽度口径）: {}",
            combo.width()
        );
    }

    /// 全宽 = 修前生产实参）同 11 工具形态复现 179 日志 09-23 两症状：
    /// (a) 实测 ≈ bar_w + 剩余宽 ≥ 窗宽 → 决策 = 全宽（「展开宽度依旧被设
    ///     置到最大」锚；179 日志 win=960 meas=1428 bar=960 同形态）；
    /// (b) combo 之后 8 钮（⟳ 显示模式 🔑 音频 麦克风 隐私 ⛶ ✖）全被推出
    ///     条左缘（min.x < 0 = 越条裁剪 = 「全屏之类工具已经消失不见」）；
    /// (c) combo 左锚到剩余区左缘（脱离邻钮、条中大空洞）。
    /// 修前症状形态按移除后工具集复刻 = 防回潮锚口径随生产走）。
    #[test]
    fn r135_3_probe_prefix_flow_symptom_repro() {
        let win = 960.0;
        let (_m1, _m2, m3, bar3, rects) = r135_3_run(win, f32::INFINITY, "prefix");
        assert!(
            m3 >= win,
            "修前实测 ≈ 内容 + 剩余宽 ≥ 窗宽: {m3} vs {win}"
        );
        assert_eq!(bar3, win, "修前决策 = 全宽（用户症状锚）: {bar3}");
        let off_bar = [
            "display_refresh",
            "display_mode",
            "special_keys",
            "audio_play",
            "mic",
            "privacy",
            "fullscreen",
            "disconnect",
        ];
        for name in off_bar {
            let r = rects.iter().find(|(n, _)| n == name).unwrap().1;
            assert!(
                r.min.x < -0.5,
                "工具 {name} 被推出条左缘（min.x {r:?} < 0 = 裁剪不可见）"
            );
        }
        let combo = rects.iter().find(|(n, _)| n == "display_combo").unwrap().1;
        let hide = rects.iter().find(|(n, _)| n == "hide").unwrap().1;
        assert!(
            combo.min.x < 60.0,
            "combo 左锚剩余区左缘（脱离邻钮）: {combo:?}"
        );
        assert!(
            hide.min.x - combo.max.x > 300.0,
            "条中大空洞（修前形态）: hide {hide:?} vs combo {combo:?}"
        );
    }

    /// 960 窗形态；PNG 落 docs 不入库）——headless 初验观感证据（CJK
    /// 豆腐块 = headless 字体局限，观感以实机用户终判）。
    #[test]
    fn r135_3_screenshot_dump() {
        /// 手工光栅化一个面板（窗口背景 + 条体 fill + 11 按钮实测矩形；越条
        /// 12 → 11（📁 旧队列面板钮随生产移除）。
        fn render_panel(win_w: f32, bar: egui::Rect, rects: &[(String, egui::Rect)]) -> image::RgbaImage {
            const H: f32 = 200.0;
            let (w, hh) = (win_w as u32, H as u32);
            let mut img = image::RgbaImage::from_pixel(w, hh, image::Rgba([58, 58, 66, 255]));
            let blend = |img: &mut image::RgbaImage, r: egui::Rect, c: image::Rgba<u8>| {
                let x0 = r.min.x.max(0.0).floor() as i32;
                let y0 = r.min.y.max(0.0).floor() as i32;
                let x1 = r.max.x.min(win_w).ceil() as i32;
                let y1 = r.max.y.min(H).ceil() as i32;
                for y in y0.max(0)..y1.min(hh as i32) {
                    for x in x0.max(0)..x1.min(w as i32) {
                        let a = c[3] as f32 / 255.0;
                        let px = img.get_pixel(x as u32, y as u32);
                        img.put_pixel(
                            x as u32,
                            y as u32,
                            image::Rgba([
                                (c[0] as f32 * a + px[0] as f32 * (1.0 - a)) as u8,
                                (c[1] as f32 * a + px[1] as f32 * (1.0 - a)) as u8,
                                (c[2] as f32 * a + px[2] as f32 * (1.0 - a)) as u8,
                                255,
                            ]),
                        );
                    }
                }
            };
            // LIGHT bg = #F5F5F7 = (245,245,247)）。
            blend(&mut img, bar, image::Rgba([245, 245, 247, TOOLBAR_BASE_ALPHA]));
            // 11 按钮（探针实测矩形；越条缘 = 裁切不显 = 修前症状视觉）。
            let border = image::Rgba([150, 152, 158, 255]);
            for (_, r) in rects {
                blend(&mut img, *r, image::Rgba([206, 208, 216, 255]));
                blend(
                    &mut img,
                    egui::Rect::from_min_max(r.min, egui::pos2(r.max.x, r.min.y + 1.0)),
                    border,
                );
            }
            img
        }
        let win = 960.0;
        // 面板 A：修前症状（实测 ≥ 窗宽 → 全宽 + combo 之后 9 钮越条左缘裁切）。
        let (_m1, _m2, _m3a, bar3a, rects_a) = r135_3_run(win, f32::INFINITY, "shot_prefix");
        let bar_a = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(bar3a, TOOLBAR_BAR_HEIGHT));
        assert_eq!(bar3a, win, "修前面板条宽 = 全宽（症状锚）: {bar3a}");
        let p_a = render_panel(win, bar_a, &rects_a);
        // 面板 B：修后（实测 = 内容自然宽 → 决策 = 内容宽，11 工具全在位）。
        let (_m1, _m2, m3b, bar3b, rects_b) = r135_3_run(win, R135_3_DISPLAY_COMBO_W, "shot_fixed");
        let bar_b = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(bar3b, TOOLBAR_BAR_HEIGHT));
        assert!(
            (bar3b - m3b).abs() < 1.0 && bar3b < win - 1.0,
            "修后面板条宽 = 内容自然宽（非全宽）: {bar3b} vs 实测 {m3b} vs 窗宽 {win}"
        );
        let p_b = render_panel(win, bar_b, &rects_b);
        // 横排合成（2× 降采样 + 12px 缝 + 8px 外边）。
        let pw = win as u32 / 2;
        let ph = 100u32;
        let mut row = image::RgbaImage::from_pixel(8 * 2 + pw * 2 + 12, ph + 16, image::Rgba([30, 30, 34, 255]));
        let mut xs = 8u32;
        for p in [&p_a, &p_b] {
            let scaled = image::imageops::resize(
                p,
                pw,
                ph,
                image::imageops::FilterType::Lanczos3,
            );
            image::GenericImage::copy_from(&mut row, &scaled, xs, 8).expect("横排合成不越界");
            xs += scaled.width() + 12;
        }
        let out_path = "E:/projects_rd/docs/r135_3_toolbar_width_sandbox.png";
        row.save(out_path).expect("PNG 落盘");
        assert!(std::path::Path::new(out_path).is_file(), "截屏在位");
    }
}

